  ui_story_5046_50460201_64_dialog_content = "¿Términos? ¿Como cambiar una cosa por otra?",
  ui_story_5046_50460201_65_dialog_content = "Supongo PlayerName es precioso para ti. Eres PlayerName?",
  ui_story_5046_50460201_66_dialog_content = "S-Sí, ese soy yo. Seré tu rehén, solo deja ir a la chica.",
  ui_story_5046_50460201_67_dialog_content = "¡No hagas nada estúpido, Dark Slayer!",
  ui_story_5046_50460201_68_dialog_content = "¿Otra vez con eso? ¡Que irritante!",
  ui_story_5046_50460201_69_dialog_content = "El perrito grande es malo...",
  ui_story_5046_50460201_70_dialog_content = "Puaj-!",
  ui_story_5046_50460201_71_dialog_content = "Dark Slayer tiene PlayerName!",
  ui_story_5046_50460201_72_dialog_content = "Acércate más y lo mataré.",
  ui_story_5046_50460201_73_dialog_content = "Ya que este te parece tan importante, déjame quedármelo por un tiempo.",
  ui_story_5046_50460201_74_dialog_content = "Oye, ¿adónde me llevas? ¡Suéltame!",
  ui_story_5046_50460201_75_dialog_content = "¡Ayuda!",
  ui_story_5046_50460201_76_dialog_content = "¡Detenedlos, guardias!",
  ui_story_5046_50460201_77_dialog_content = "No dejes que Dark Slayer se salga con la suya PlayerName!",
  ui_story_5046_50460202_1_dialog_content = "Los guardias han perdido al Dark Slayer.",
  ui_story_5046_50460202_2_dialog_content = "Lo siento, señor...",
  ui_story_5046_50460202_3_dialog_content = "No es tu culpa. Dark Slayer puede controlar el fuego, eso le da una ventaja.",
  ui_story_5046_50460202_4_dialog_content = "Además, se mueve mucho más rápido que la gente común.",
  ui_story_5046_50460202_5_dialog_content = "No es una sorpresa que no pudiste seguirle el ritmo.",
  ui_story_5046_50460202_6_dialog_content = "Bueno, tu plan de contingencia fue útil.",
  ui_story_5046_50460202_7_dialog_content = "Todavía es caótico, pero al menos los invitados fueron evacuados de manera segura.",
  ui_story_5046_50460202_8_dialog_content = "pero podrias explicarme como PlayerName fue tomado como rehén por el Dark Slayer?",
  ui_story_5046_50460202_9_dialog_content = "Lo siento, no cumplimos con nuestro deber.",
  ui_story_5046_50460202_10_dialog_content = "No, es mi culpa que PlayerName fue secuestrado...",
  ui_story_5046_50460202_11_dialog_content = "Hemos identificado al sospechoso, señorita. Bethel.",
  ui_story_5046_50460202_12_dialog_content = "Muy bien, bien hecho.",
  ui_story_5046_50460202_13_dialog_content = "\"Hati, mujer, 18 años, lugar de nacimiento desconocido\".",
  ui_story_5046_50460202_14_dialog_content = "\"Tuvo una breve estancia en el orfanato de Umbraton. El Señor de las Sombras la acogió después de que ella provocara un incendio que incendiara el orfanato\".",
  ui_story_5046_50460202_15_dialog_content = "(¿Padre...? ¿Fue idea de Padre?)",
  ui_story_5046_50460202_16_dialog_content = "¿Causó un incendio que quemó el orfanato? Suena a reincidente.",
  ui_story_5046_50460202_17_dialog_content = "\"Hati cumplió 18 años hace dos meses y dejó el patrimonio después de una evaluación exitosa\".",
  ui_story_5046_50460202_18_dialog_content = "(Es mejor dejar que el Padre sepa sobre esto.)",
  ui_story_5046_50460202_19_dialog_content = "¿Cómo podría ser liberado un pirómano conocido como ese...?",
  ui_story_5046_50460202_20_dialog_content = "De todos modos, le transmitiré esto al Señor de las Sombras e informaré a todas las facciones de Umbraton para que busquen PlayerNameel paradero de .",
  ui_story_5046_50460202_21_dialog_content = "Pero eso lo hará público...",
  ui_story_5046_50460202_22_dialog_content = "Me preocupa la reacción violenta en el orfanato cuando se corre la voz de que un VIP fue secuestrado durante el ensayo.",
  ui_story_5046_50460202_23_dialog_content = "Pero ni siquiera sabemos si PlayerName está vivo ahora mismo!",
  ui_story_5046_50460202_24_dialog_content = "Suspiro...",
  ui_story_5046_50460202_25_dialog_content = "Extrañar Bethel, Sr. Hamell.",
  ui_story_5046_50460202_26_dialog_content = "Si estás dispuesto a confiar en mí, por favor sigue PlayerNameEl secuestro en secreto por ahora.",
  ui_story_5046_50460202_27_dialog_content = "Si lo publicitamos, Dark Slayer podría amenazar PlayerNamela vida",
  ui_story_5046_50460202_28_dialog_content = "Localizaré al Dark Slayer y lo liberaré. PlayerName lo antes posible.",
  ui_story_5046_50460202_29_dialog_content = "...",
  ui_story_5046_50460202_30_dialog_content = "Por favor, perdóname por no tener confianza en ti.",
  ui_story_5046_50460202_31_dialog_content = "Si no puedes confiar en nuestras habilidades...",
  ui_story_5046_50460202_32_dialog_content = "Estoy dispuesto a responder por mi instructor, Knight Zenas, sobre el nombre de Ivan.",
  ui_story_5046_50460202_33_dialog_content = "No tiene que hacer esto, mi señora...",
  ui_story_5046_50460202_34_dialog_content = "Por favor, dénos otra oportunidad de corregir nuestro error, señorita. Bethel.",
  ui_story_5046_50460202_35_dialog_content = "He oído historias sobre Knight Zenas.",
  ui_story_5046_50460202_36_dialog_content = "Muy impresionante abrirse camino desde una familia noble humilde hasta donde está ahora.",
  ui_story_5046_50460202_37_dialog_content = "Está bien, dado que los Ivan están detrás de ti, confiaré en ti por el momento.",
  ui_story_5046_50460202_38_dialog_content = "Pero tenga en cuenta que el Señor de las Sombras se enterará de esto eventualmente.",
  ui_story_5046_50460202_39_dialog_content = "Tienes tres días.",
  ui_story_5046_50460202_40_dialog_content = "Quiero PlayerName en la ceremonia, ileso, tres días después.",
  ui_story_5046_50460202_41_dialog_content = "Si no puedes hacer eso, lo manejaré a la manera de Umbraton.",
  ui_story_5046_50460202_42_dialog_content = "Mi agradecimiento.",
  ui_story_5046_50460202_43_dialog_content = "La mía también.",
  ui_story_5046_50460202_44_dialog_content = "Bien, así es como nos ocuparemos PlayerNameEs un secuestro por ahora.",
  ui_story_5046_50460202_45_dialog_content = "Mientras tanto, necesitaremos su ayuda para calmar a los invitados, Sr. Hamell.",
  ui_story_5046_50460202_46_dialog_content = "¡Por supuesto por supuesto!",
  ui_story_5046_50460202_47_dialog_content = "Por aquí, Sr. Hamell.",
  ui_story_5046_50460202_48_dialog_content = "Por favor, déjeme ayudarlo a rastrear al Dark Slayer, señor.",
  ui_story_5046_50460202_49_dialog_content = "Me he esforzado mucho aprendiendo Luminatics y habilidades de combate a lo largo de los años solo para poder protegerte algún día.",
  ui_story_5046_50460202_50_dialog_content = "¡Por favor dame una oportunidad!",
  ui_story_5046_50460202_51_dialog_content = "No.",
  ui_story_5046_50460202_52_dialog_content = "¿No confías en mí por lo que pasó en ese incendio?",
  ui_story_5046_50460202_53_dialog_content = "Todo es mi culpa. Y tuviste que salvarme de otro incendio.",
  ui_story_5046_50460202_54_dialog_content = "Oh, ¿por qué siempre te pongo en aprietos...?",
  ui_story_5046_50460202_55_dialog_content = "Deja de culparte, milady.",
  ui_story_5046_50460202_56_dialog_content = "Siempre los rescataré de las culpas, en el pasado, presente y futuro.",
  ui_story_5046_50460202_57_dialog_content = "Entonces por qué...",
  ui_story_5046_50460202_58_dialog_content = "Eres capaz de discernir pistas vitales de informes de delitos y documentos asociados.",
  ui_story_5046_50460202_59_dialog_content = "Entonces, en comparación con perseguir al culpable en el campo, creo que investigar la escena del crimen y sondear documentos es más adecuado para usted.",
  ui_story_5046_50460202_60_dialog_content = "Preferiría no verte forzándote a hacer algo en lo que no eres bueno.",
  ui_story_5046_50460202_61_dialog_content = "Lo llamaría algo que no hago a menudo en lugar de algo en lo que no soy bueno...",
  ui_story_5046_50460202_62_dialog_content = "¿Mi señora?",
  ui_story_5046_50460202_63_dialog_content = "N-Nada.",
  ui_story_5046_50460202_64_dialog_content = "Así que por favor quédense atrás y examinen el sitio del incendio provocado. Estoy seguro de que encontrará pistas valiosas.",
  ui_story_5046_50460202_65_dialog_content = "¡Ok, lo tengo!",
  ui_story_5046_50460202_66_dialog_content = "¡No dejaré piedra sin remover!",
  ui_story_5046_50460202_67_dialog_content = "Padre, eso es lo que pasó.",
  ui_story_5046_50460202_68_dialog_content = "¿Qué debemos hacer a continuación?",
  ui_story_5046_50460202_69_dialog_content = "Mmm...",
  ui_story_5046_50460202_70_dialog_content = "No es una cosa en este momento.",
  ui_story_5046_50460202_71_dialog_content = "Pero que pasa PlayerName...",
  ui_story_5046_50460202_72_dialog_content = "No se preocupe, alguien se mantendrá al tanto PlayerName.",
  ui_story_5046_50460202_73_dialog_content = "Si mi señor.",
  ui_story_5046_50460301_1_dialog_content = "<color=#e8d9bb>Barra de luciérnagas en Umbraton</color>",
  ui_story_5046_50460301_2_dialog_content = "Estás de vuelta.",
  ui_story_5046_50460301_3_dialog_content = "(¿Adónde me ha llevado Dark Slayer?)",
  ui_story_5046_50460301_4_dialog_content = "¿Pensé que fuiste al ensayo hoy? ¿Y qué pasa con el gato callejero que trajiste?",
  ui_story_5046_50460301_5_dialog_content = "(Parece que estoy en un bar. Probablemente debería pretender que todavía estoy fuera y escuchar lo que dicen...)",
  ui_story_5046_50460301_6_dialog_content = "Es la cizaña la que se te pega.",
  ui_story_5046_50460301_7_dialog_content = "Jaja, ¿te refieres a la semilla con espinas afiladas que se pegan a tu ropa como los cardos?",
  ui_story_5046_50460301_8_dialog_content = "Sí. Mamá solía traerlos a la casa sin querer, y yo siempre se los quitaba.",
  ui_story_5046_50460301_9_dialog_content = "Oh, ¿conseguiste la cosa?",
  ui_story_5046_50460301_10_dialog_content = "No. La cizaña me detuvo, y luego apareció más gente, así que no pude hacer ningún movimiento.",
  ui_story_5046_50460301_11_dialog_content = "El cocklebur parece ser una figura muy importante. Estaban preocupados.",
  ui_story_5046_50460301_12_dialog_content = "Oye, ¿no es esta la Caelestita?",
  ui_story_5046_50460301_13_dialog_content = "¿Qué es eso?",
  ui_story_5046_50460301_14_dialog_content = "¿No conoces la Caelestita? Oh, es cierto, olvidé que solo has estado en el mundo durante dos meses.",
  ui_story_5046_50460301_15_dialog_content = "¿A los Caelestitas les gusta fingir que están dormidos?",
  ui_story_5046_50460301_16_dialog_content = "(¿Qué? ¡¿Ella sabe que estoy escuchando a escondidas?!)",
  ui_story_5046_50460301_17_dialog_content = "No sé. Ningún tabloide en Umbraton mencionó eso.",
  ui_story_5046_50460301_18_dialog_content = "Oye, levántate.",
  ui_story_5046_50460301_19_dialog_content = "(¡Me está sacudiendo con la fuerza suficiente para romperme los huesos!)",
  ui_story_5046_50460301_20_dialog_content = "(Tendré que fingir que me acabo de despertar.)",
  ui_story_5046_50460301_21_dialog_content = "Oh...",
  ui_story_5046_50460301_22_dialog_content = "¿Dónde estoy?",
  ui_story_5046_50460301_23_dialog_content = "¿Por qué finges como si acabaras de despertar? Estabas mirando alrededor del bar cuando entramos.",
  ui_story_5046_50460301_24_dialog_content = "Uh, jaja, ¿de qué estás hablando? Obviamente acabo de recuperar mis sentidos.",
  ui_story_5046_50460301_25_dialog_content = "Una buena persona no mentiría.",
  ui_story_5046_50460301_26_dialog_content = "Está bien, no nos asustemos PlayerName.",
  ui_story_5046_50460301_27_dialog_content = "¿Como sabes mi nombre?",
  ui_story_5046_50460301_28_dialog_content = "Eres popular en todo el país. No es inusual saber quién eres.",
  ui_story_5046_50460301_29_dialog_content = "Bien, eso es cierto.",
  ui_story_5046_50460301_30_dialog_content = "No estés nervioso. No tenemos malas intenciones.",
  ui_story_5046_50460301_31_dialog_content = "Soy Grimme, el barman de este Firefly Bar.",
  ui_story_5046_50460301_32_dialog_content = "ella es Hati, actualmente trabajando para el bar.",
  ui_story_5046_50460301_33_dialog_content = "En cuanto a lo que soy para ella... Puedes llamarme su guardián.",
  ui_story_5046_50460301_34_dialog_content = "Ha estado a mi cuidado desde que dejó al Señor de las Sombras.",
  ui_story_5046_50460301_35_dialog_content = "No te dejes engañar por su apariencia. Puede parecer que tiene veintitantos años, ¡pero en realidad solo tiene dieciocho!",
  ui_story_5046_50460301_36_dialog_content = "Y solo ha estado en el mundo real durante dos meses, por lo que su mente es más cercana a la de una niña de siete u ocho años.",
  ui_story_5046_50460301_37_dialog_content = "no estoy seguro de por qué Hati te trajo de vuelta, pero créeme, es una buena chica.",
  ui_story_5046_50460301_38_dialog_content = "¿Crees que secuestrar a alguien es bueno...?",
  ui_story_5046_50460301_39_dialog_content = "Ella es franca y directa, pero no quiere hacer daño.",
  ui_story_5046_50460301_40_dialog_content = "Aunque ella tiene la culpa de esto, haré que se disculpe contigo.",
  ui_story_5046_50460301_41_dialog_content = "Ahora, ¿por qué debería disculparme con esa persona?",
  ui_story_5046_50460301_42_dialog_content = "Todos me trataron como a un chico malo y me llamaron Dark Slayer...",
  ui_story_5046_50460301_43_dialog_content = "A pesar de lo que te dijeron, haces mal en secuestrar a alguien.",
  ui_story_5046_50460301_44_dialog_content = "Tienes que disculparte cuando haces algo mal.",
  ui_story_5046_50460301_45_dialog_content = "Tsk...",
  ui_story_5046_50460301_46_dialog_content = "Lo siento.",
  ui_story_5046_50460301_47_dialog_content = "(No esperaba que alguien tan feroz escuchara a Grimme...)",
  ui_story_5046_50460301_48_dialog_content = "no debí haberlo hecho, PlayerName.",
  ui_story_5046_50460301_49_dialog_content = "(Eso sonó sincero, y en realidad no me hizo ningún daño...)",
  ui_story_5046_50460301_50_dialog_content = "S-Claro, dado lo sincero que eres, te perdono.",
  ui_story_5046_50460301_51_dialog_content = "Luego ustedes dos se dan la mano y comenzamos de nuevo desde cero.",
  ui_story_5046_50460301_52_dialog_content = "...",
  ui_story_5046_50460301_53_dialog_content = "...",
  ui_story_5046_50460301_54_dialog_content = "Jaja, ustedes dos actúan igual cuando están en desacuerdo.",
  ui_story_5046_50460301_55_dialog_content = "No me mezcles con ella...",
  ui_story_5046_50460301_56_dialog_content = "Oh, escuché que Caelestites tiene habilidades psíquicas y puede vislumbrar profundamente la memoria de otros.",
  ui_story_5046_50460301_57_dialog_content = "Tal vez PlayerName puede ayudarte a recordar lo que pasó con tu madre.",
  ui_story_5046_50460301_58_dialog_content = "(Hati parece muy triste cuando se menciona a su madre.)",
  ui_story_5046_50460301_59_dialog_content = "¿No has querido saber qué pasó, Hati?",
  ui_story_5046_50460301_60_dialog_content = "¿Crees que este tipo puede ayudar?",
  ui_story_5046_50460301_61_dialog_content = "¿Me estás mirando hacia abajo? ¿Y por qué debería hacer eso?",
  ui_story_5046_50460301_62_dialog_content = "Hmm, parece que tenemos un dilema.",
  ui_story_5046_50460301_63_dialog_content = "¿Qué tal esto, entonces? Si te ayudo con mis poderes, tienes que llevarme de regreso.",
  ui_story_5046_50460301_64_dialog_content = "También, Hati ¡tiene que entregarse por todos los crímenes que ha cometido!",
  ui_story_5046_50460301_65_dialog_content = "Es razonable. Podemos ir con eso.",
  ui_story_5046_50460301_66_dialog_content = "Pero Hati no hice todas esas cosas, puedo dar fe de eso.",
  ui_story_5046_50460301_67_dialog_content = "Si está interesado en resolver los casos, puede descubrir al culpable con Hati.",
  ui_story_5046_50460301_68_dialog_content = "¿Cómo es eso de una ganga por tu ayuda?",
  ui_story_5046_50460301_69_dialog_content = "¡Es un trato!",
  ui_story_5046_50460301_70_dialog_content = "...",
  ui_story_5046_50460301_71_dialog_content = "Si de verdad puedes recuperar ese recuerdo para mí...",
  ui_story_5046_50460301_72_dialog_content = "No me importa que me entregues para las recompensas de 200,000 Nightium.",
  ui_story_5046_50460301_73_dialog_content = "Relájate, si no lo hiciste, no te cambio por el dinero.",
  ui_story_5046_50460301_74_dialog_content = "Aunque 200.000 es mucho, nunca lo haría por codicia.",
  ui_story_5046_50460301_75_dialog_content = "No me importa.",
  ui_story_5046_50460301_76_dialog_content = "A-Muy bien, entonces solo ayúdame a averiguar qué hacer.",
  ui_story_5046_50460301_77_dialog_content = "Tienes que ser tan detallado con la historia como puedas para maximizar el resultado.",
  ui_story_5046_50460301_78_dialog_content = "Quiero encontrar a mi madre.",
  ui_story_5046_50460301_79_dialog_content = "Viví con ella cuando era pequeño. Ella no era ni buena ni mala conmigo.",
  ui_story_5046_50460301_80_dialog_content = "Hasta que un día, nos separamos por razones desconocidas.",
  ui_story_5046_50460301_81_dialog_content = "Lo siguiente que supe fue que estaba en el orfanato.",
  ui_story_5046_50460301_82_dialog_content = "Así que estás diciendo que falta una parte en tu memoria.",
  ui_story_5046_50460301_83_dialog_content = "Si podemos recuperarlo, es posible encontrar a tu madre.",
  ui_story_5046_50460301_84_dialog_content = "Así es.",
  ui_story_5046_50460301_85_dialog_content = "¿Eso es todo lo que tienes para continuar?",
  ui_story_5046_50460301_86_dialog_content = "En seguida.",
  ui_story_5046_50460301_87_dialog_content = "Bueno. Puedo entender que no me creas a mí ni a mis habilidades psíquicas.",
  ui_story_5046_50460301_88_dialog_content = "Pero haré todo lo posible para hacer lo que prometí.",
  ui_story_5046_50460301_89_dialog_content = "...",
  ui_story_5046_50460301_90_dialog_content = "Lo siento, PlayerName, el niño es nuevo en el mundo y no se abrirá fácilmente.",
  ui_story_5046_50460301_91_dialog_content = "Esta bien. Solo espero que hagas lo prometido y me dejes ir después.",
  ui_story_5046_50460301_92_dialog_content = "Hati, necesito que te concentres en recordar lo último que viste antes de que se interrumpiera el recuerdo.",
  ui_story_5046_50460301_93_dialog_content = "Avísame cuando estés listo.",
  ui_story_5046_50460301_94_dialog_content = "Estoy listo.",
  ui_story_5046_50460301_95_dialog_content = "Tomar una respiración profunda, Hati, y relájate.",
  ui_story_5046_50460301_96_dialog_content = "Comencemos.",
  ui_story_5046_50460301_97_option_content = "¡Potencia de fuerza!",
  ui_story_5046_50460301_98_dialog_content = "...",
  ui_story_5046_50460301_99_dialog_content = "(¿Dónde estoy? Parece una casa ordinaria.)",
  ui_story_5046_50460301_100_dialog_content = "(¿Es aquí donde Hati ¿vivido?)",
  ui_story_5046_50460301_101_dialog_content = "(PlayerName?)",
  ui_story_5046_50460301_102_dialog_content = "(Puedes ver en mi memoria.)",
  ui_story_5046_50460301_103_dialog_content = "(¿Ahora me crees?)",
  ui_story_5046_50460301_104_dialog_content = "<color=#e8d9bb>El patrón de Pitter...</color>",
  ui_story_5046_50460301_105_dialog_content = "(Oigo pasos y se acercan.)",
  ui_story_5046_50460301_106_dialog_content = "¿Adónde te escapaste esta vez? Hati?",
  ui_story_5046_50460301_107_dialog_content = "(¿Quién es éste?)",
  ui_story_5046_50460301_108_dialog_content = "(Mamá...)",
  ui_story_5046_50460301_109_dialog_content = "Suspiro...",
  ui_story_5046_50460301_110_dialog_content = "Cada vez es más difícil controlar el poder de ese niño, y estoy preocupado...",
  ui_story_5046_50460301_111_dialog_content = "No solo eso, ella está empezando a anhelar el mundo exterior.",
  ui_story_5046_50460301_112_dialog_content = "Pero nunca debo dejarla salir...",
  ui_story_5046_50460301_113_dialog_content = "(¿Por qué no dejaría Hati ¿afuera?)",
  ui_story_5046_50460301_114_dialog_content = "(Porque teme a mis poderes, teme a mi... fuego.)",
  ui_story_5046_50460301_115_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5046_50460301_116_dialog_content = "¡Rugido!",
  ui_story_5046_50460301_117_dialog_content = "(¡Vaya—!)",
  ui_story_5046_50460301_118_dialog_content = "(¿Es eso un perro o un lobo? ¡Es tan grande!)",
  ui_story_5046_50460301_119_dialog_content = "(Y algo parecido Hati...)",
  ui_story_5046_50460301_120_dialog_content = "(Es mi demonio interior, la encarnación de los miedos y el odio por mi propio poder).",
  ui_story_5046_50460301_121_dialog_content = "(Está protegiendo la memoria perdida y no me deja acercarme).",
  ui_story_5046_50460301_122_dialog_content = "(¡Urgh-! ¡Me duele la cabeza!)",
  ui_story_5046_50460301_123_dialog_content = "(¿Qué pasa? No te ves bien.)",
  ui_story_5046_50460301_124_dialog_content = "Me odias...? Pero yo soy... tú...",
  ui_story_5046_50460301_125_dialog_content = "(Esto no se siente bien. ¡Debería terminar la sesión aquí!)",
  ui_story_5046_50460301_126_dialog_content = "Podrías ver mi memoria, PlayerName, e incluso mi demonio interior...",
  ui_story_5046_50460301_127_dialog_content = "El poder de Caelestite es realmente maravilloso.",
  ui_story_5046_50460301_128_dialog_content = "Avanzamos con las habilidades psíquicas de Caelestite, por lo que veo.",
  ui_story_5046_50460301_129_dialog_content = "Eso es maravilloso, Hati.",
  ui_story_5046_50460301_130_dialog_content = "Hati Me emocioné mucho cuando apareció el demonio interior, así que terminé la sesión.",
  ui_story_5046_50460301_131_dialog_content = "No sacamos nada más de eso.",
  ui_story_5046_50460301_132_dialog_content = "Cuanto más sepas, más fácil me ayudarás a recordar, ¿verdad?",
  ui_story_5046_50460301_133_dialog_content = "¿Ah?",
  ui_story_5046_50460301_134_dialog_content = "S-Sí, eso es correcto...",
  ui_story_5046_50460301_135_dialog_content = "Entonces, si te digo más, ¿puedes usar el poder de nuevo?",
  ui_story_5046_50460301_136_dialog_content = "Sí, puedo...",
  ui_story_5046_50460301_137_dialog_content = "Pero tienes que dejarme ir como prometiste.",
  ui_story_5046_50460301_138_dialog_content = "Acuerdo.",
  ui_story_5046_50460401_1_dialog_content = "Este es el informe sobre el incendio del orfanato para su lectura, juez. Kristen.",
  ui_story_5046_50460401_2_dialog_content = "Gracias. Solo soy un interno en este momento, así que solo llámame Kristen.",
  ui_story_5046_50460401_3_dialog_content = "La fuente era combustible inflamable y se almacenó en el almacén junto con otros materiales de construcción sobrantes.",
  ui_story_5046_50460401_4_dialog_content = "Todos estaban demasiado ocupados con la ceremonia para prestar atención al combustible adicional almacenado.",
  ui_story_5046_50460401_5_dialog_content = "El combustible es idéntico al que se encontró en los sitios de incendios provocados en los últimos dos meses, por lo que la misma persona debe ser responsable.",
  ui_story_5046_50460401_6_dialog_content = "Sí, esa es una conclusión lógica.",
  ui_story_5046_50460401_7_dialog_content = "Pero nunca hubo un secuestro en ninguno de los casos anteriores, y Caelestite fue atrapado esta vez...",
  ui_story_5046_50460401_8_dialog_content = "Eso no parece encajar en el patrón. ¿Y cuál es el motivo del sospechoso?",
  ui_story_5046_50460401_9_dialog_content = "Según relatos de testigos presenciales, el sospechoso es un auroriano semihumano llamado Hati.",
  ui_story_5046_50460401_10_dialog_content = "Hati había estado viviendo en la mansión del Señor de las Sombras hasta hace dos meses. Este es su archivo.",
  ui_story_5046_50460401_11_dialog_content = "Mmm...",
  ui_story_5046_50460401_12_dialog_content = "\"Según testigos presenciales, Hati lanzó una llama masiva de Lumina en la noche del incendio del orfanato y provocó un gran incendio\".",
  ui_story_5046_50460401_13_dialog_content = "Todas las pistas actuales apuntan al demi-humano llamado Hati.",
  ui_story_5046_50460401_14_dialog_content = "Y todos los incendios provocados ocurrieron después de que ella dejó la mansión del Señor de las Sombras. Sin embargo, ¿cuál sería su motivo?",
  ui_story_5046_50460401_15_dialog_content = "Ah, y la niña que acabamos de rescatar...",
  ui_story_5046_50460401_16_dialog_content = "La pusimos en el dormitorio del orfanato bajo la vigilancia del cuidador.",
  ui_story_5046_50460401_17_dialog_content = "Déjame ir a preguntarle qué pasó.",
  ui_story_5046_50460401_18_dialog_content = "Hola soy Kristen, un juez de prueba de Lumopolis.",
  ui_story_5046_50460401_19_dialog_content = "Me gustaría preguntarle a este niño sobre el fuego.",
  ui_story_5046_50460401_20_dialog_content = "Una dama noble de Lumopolis, por lo que veo. No puedo rechazar su pedido, pero sepa que el niño finalmente se calmó hace solo un momento.",
  ui_story_5046_50460401_21_dialog_content = "Deberías hacerlo rápido, porque debo pedirte que te vayas si el niño hace otra rabieta.",
  ui_story_5046_50460401_22_dialog_content = "Gracias por el pensamiento. Terminaré con esto lo más rápido posible.",
  ui_story_5046_50460401_23_dialog_content = "Hola pequeño.",
  ui_story_5046_50460401_24_dialog_content = "¡Oye, eres la dama de antes!",
  ui_story_5046_50460401_25_dialog_content = "¿Están aquí también el perrito grande y el tipo amable que me salvó?",
  ui_story_5046_50460401_26_dialog_content = "Oh, no están aquí. ¿Conoces a los dos?",
  ui_story_5046_50460401_27_dialog_content = "No. ¡Pero el gentil me protegió en el fuego, así que es una buena persona!",
  ui_story_5046_50460401_28_dialog_content = "¡Y cuando cayó una viga, apareció el perrito grande y nos salvó!",
  ui_story_5046_50460401_29_dialog_content = "(Hati salvarlos?)",
  ui_story_5046_50460401_30_dialog_content = "¿Puedes decirme por qué estabas allí?",
  ui_story_5046_50460401_31_dialog_content = "Sollozo...",
  ui_story_5046_50460401_32_dialog_content = "¿Qué está pasando?",
  ui_story_5046_50460401_33_dialog_content = "¿Quieres dulces, pequeña?",
  ui_story_5046_50460401_34_dialog_content = "¡Sí!",
  ui_story_5046_50460401_35_dialog_content = "*Mastica* Así que estaba jugando al escondite y me escondí dentro de esa casa.",
  ui_story_5046_50460401_36_dialog_content = "Había muchos barriles adentro y una pequeña caja extraña.",
  ui_story_5046_50460401_37_dialog_content = "¿Pequeña caja extraña?",
  ui_story_5046_50460401_38_dialog_content = "Lo tiré accidentalmente al suelo y ¡comenzó a arder!",
  ui_story_5046_50460401_39_dialog_content = "Intenté salir corriendo, pero había fuego por todas partes, daba miedo.",
  ui_story_5046_50460401_40_dialog_content = "Boo-hoo... No quise quemar la casa...",
  ui_story_5046_50460401_41_dialog_content = "¡Waah!",
  ui_story_5046_50460401_42_dialog_content = "¡El fuego fue tan aterrador!",
  ui_story_5046_50460401_43_dialog_content = "Está bien, la hiciste llorar de nuevo. Se acabó el tiempo, tienes que irte ahora.",
  ui_story_5046_50460401_44_dialog_content = "Lo siento... Ahora, pequeña, no vayas a un lugar desconocido la próxima vez.",
  ui_story_5046_50460401_45_dialog_content = "Boo-hoo... lo tengo...",
  ui_story_5046_50460401_46_dialog_content = "<color=#e8d9bb>Barra de luciérnagas en Umbraton</color>",
  ui_story_5046_50460401_47_dialog_content = "No, todavía no puedo recordar...",
  ui_story_5046_50460401_48_dialog_content = "Incluso con todos los detalles, ¿tu poder aún no puede recuperar la memoria perdida por mí?",
  ui_story_5046_50460401_49_dialog_content = "Siento no haber podido ayudar...",
  ui_story_5046_50460401_50_dialog_content = "Es muy amable de tu parte no culparla por secuestrarte e incluso tratar de ayudarla con tus habilidades psíquicas.",
  ui_story_5046_50460401_51_dialog_content = "¡Tiene que haber otra manera!",
  ui_story_5046_50460401_52_dialog_content = "¡El colgante! ¡Sí, el colgante!",
  ui_story_5046_50460401_53_dialog_content = "¿El colgante?",
  ui_story_5046_50460401_54_dialog_content = "Lo secuestré para comerciar con el hombre enmascarado por el colgante.",
  ui_story_5046_50460401_55_dialog_content = "Ese colgante es muy significativo para mí, al igual que tú eres muy significativo para ese hombre enmascarado.",
  ui_story_5046_50460401_56_dialog_content = "Es un comercio justo.",
  ui_story_5046_50460401_57_dialog_content = "¿Cambiarme por un colgante? ¡Qué grosero de tu parte proponer eso!",
  ui_story_5046_50460401_58_dialog_content = "¡Ningún conocimiento social en absoluto!",
  ui_story_5046_50460401_59_dialog_content = "¿No tienes nada que decir como su guardián, Grimme?",
  ui_story_5046_50460401_60_dialog_content = "Fue contundente, pero no vi nada malo en lo que dijo.",
  ui_story_5046_50460401_61_dialog_content = "Puedes volver atrás y Hati obtiene lo que quiere consumando el intercambio.",
  ui_story_5046_50460401_62_dialog_content = "¿No es eso razonable?",
  ui_story_5046_50460401_63_dialog_content = "E-Eso tiene sentido...",
  ui_story_5046_50460401_64_dialog_content = "Espera un minuto, ¿no prometiste dejarme ir si ayudaba?",
  ui_story_5046_50460401_65_dialog_content = "¡¿Por qué soy una moneda de cambio ahora?! ¡Estás lloriqueando!",
  ui_story_5046_50460401_66_dialog_content = "Pero Hati no recuperó la memoria.",
  ui_story_5046_50460401_67_dialog_content = "Veo que la gente de Umbraton es tortuosa.",
  ui_story_5046_50460401_68_dialog_content = "(No se siente bien ser tratado como un chip, aunque de lo contrario no estoy lastimado...)",
  ui_story_5046_50460401_69_dialog_content = "(Tal vez pueda escabullirme cuando no estén mirando, encontrar Bethel y hacerle saber que...)",
  ui_story_5046_50460401_70_dialog_content = "Solo tenemos que averiguar cómo hacer un trato con el hombre enmascarado.",
  ui_story_5046_50460401_71_dialog_content = "Hay carteles tuyos por toda la ciudad, Hati. Si te muestras, te arrestarán antes de llegar a la mesa de negociación.",
  ui_story_5046_50460401_72_dialog_content = "Hagámoslo. Escribes un mensaje, Hati, y se lo entregaré al hombre.",
  ui_story_5046_50460401_73_dialog_content = "Pídele que venga solo a algún lugar fuera de Umbraton.",
  ui_story_5046_50460401_74_dialog_content = "Está bien...",
  ui_story_5046_50460401_75_dialog_content = "Vigila de cerca al tipo, Grimme, para que no haya escapatoria.",
  ui_story_5046_50460401_76_dialog_content = "Intenta correr, apaga la luz, tal como arrastré el cuerpo.",
  ui_story_5046_50460401_77_dialog_content = "¿Qué?",
  ui_story_5046_50460401_78_dialog_content = "¿Quieres algo de beber? Puedes volver una vez que el trato esté cerrado.",
  ui_story_5046_50460401_79_dialog_content = "Entonces no tendrás la oportunidad de disfrutar de una ronda.",
  ui_story_5046_50460401_80_dialog_content = "¿Cuál es la historia con ese colgante?",
  ui_story_5046_50460401_81_dialog_content = "Por que Hati ¿Lo quieres tanto?",
  ui_story_5046_50460401_82_dialog_content = "Bueno, puedo contarte la historia ahora que Hati no está alrededor",
  ui_story_5046_50460401_83_dialog_content = "Recuerdo un día, Hati volvió corriendo y me dijo que vio el colgante de su madre en un hombre enmascarado.",
  ui_story_5046_50460401_84_dialog_content = "¿Hombre enmascarado? Ese debe ser el Capitán Zenas. Es el único que lleva una máscara.",
  ui_story_5046_50460401_85_dialog_content = "Ella se acercó a él antes, pero él parecía muy sorprendido de verla y no estaba dispuesto a renunciar al colgante por nada.",
  ui_story_5046_50460401_86_dialog_content = "Así que ella ha estado conspirando para quitarle el colgante desde entonces.",
  ui_story_5046_50460401_87_dialog_content = "¡Eso constituye un crimen!",
  ui_story_5046_50460401_88_dialog_content = "y porque es Hati ¿Está tan seguro de que el colgante de Zenas es el que está buscando?",
  ui_story_5046_50460401_89_dialog_content = "Dijo que le dio dolor de cabeza la primera vez que vio el colgante en Zenas.",
  ui_story_5046_50460401_90_dialog_content = "Dijo que recordaba muy claramente que el patrón coincidía exactamente con el de su madre.",
  ui_story_5046_50460401_91_dialog_content = "También dijo que obtener ese colgante le permitirá recuperar aún más recuerdos perdidos.",
  ui_story_5046_50460401_92_dialog_content = "¿Te refieres al patrón del pequeño pony?",
  ui_story_5046_50460401_93_dialog_content = "Escuché que todas las familias nobles de Lumopolis tienen su propio escudo, entonces, ¿las madres de Zenas y Hati provienen del mismo linaje?",
  ui_story_5046_50460401_94_dialog_content = "Eso no lo sé.",
  ui_story_5046_50460401_95_dialog_content = "El mensaje está listo.",
  ui_story_5046_50460401_96_dialog_content = "<color=#e8d9bb>Toc-toc, toc, toc-toc</color>",
  ui_story_5046_50460401_97_dialog_content = "Justo a tiempo. Venga.",
  ui_story_5046_50460401_98_dialog_content = "Jefe.",
  ui_story_5046_50460401_99_dialog_content = "Todo está bien, Hati y PlayerName son guays.",
  ui_story_5046_50460401_100_dialog_content = "Nada con las facciones de Umbraton hasta ahora. El caballero de Lumopolis está de camino al bar con gente ahora mismo.",
  ui_story_5046_50460401_101_dialog_content = "Deberían estar aquí en cualquier momento.",
  ui_story_5046_50460401_102_dialog_content = "¿Es eso así? Tiempo perfecto.",
  ui_story_5046_50460401_103_dialog_content = "Buen trabajo. Aquí está tu paga.",
  ui_story_5046_50460401_104_dialog_content = "¡Gracias jefe!",
  ui_story_5046_50460401_105_dialog_content = "Me iré ahora.",
  ui_story_5046_50460401_106_dialog_content = "(¿Ese niño es el informante de Grimme? ¿Quién es Grimme, en realidad...?)",
  ui_story_5046_50460401_107_dialog_content = "Voy a entregar el mensaje, Hati. Te diriges al punto de encuentro.",
  ui_story_5046_50460401_108_dialog_content = "Bueno. Vamos, PlayerName.",
  ui_story_5046_50460401_109_dialog_content = "Será mejor que vengas en silencio y no intentes pedir ayuda, o...",
  ui_story_5046_50460401_110_dialog_content = "O me noquearás, ¿verdad?",
  ui_story_5046_50460401_111_dialog_content = "Espero que hagas lo que prometiste esta vez: déjame ir una vez que tengas el colgante.",
  ui_story_5046_50460401_112_dialog_content = "Los guardias de Lumopolis están cerca, así que ten cuidado cuando te vayas.",
  ui_story_5046_50460401_113_dialog_content = "Simplemente los noquearé en silencio.",
  ui_story_5046_50460402_1_dialog_content = "<color=#e8d9bb>Timbre-</color>",
  ui_story_5046_50460402_2_dialog_content = "Bienvenido. ¿Qué le gustaría beber?",
  ui_story_5046_50460402_3_dialog_content = "Oh, son funcionarios de Lumopolis. ¿Qué te trae a mi pequeño bar Umbraton, puedo preguntar?",
  ui_story_5046_50460402_4_dialog_content = "No estamos aquí para charlar, solo para hacer algunas preguntas.",
  ui_story_5046_50460402_5_dialog_content = "¿Por qué no te quedas y te tomas una copa? Te diré todo lo que sé.",
  ui_story_5046_50460402_6_dialog_content = "Eso no es necesario.",
  ui_story_5046_50460402_7_dialog_content = "Los testigos afirmaron que el pirómano en el ensayo era tu amigo. Hati.",
  ui_story_5046_50460402_8_dialog_content = "A juzgar por su ruta de escape, creemos que huyó a este bar.",
  ui_story_5046_50460402_9_dialog_content = "Esperamos que coopere con nuestra investigación.",
  ui_story_5046_50460402_10_dialog_content = "Me encantaría, pero espero que pueda producir pruebas concretas de que Hati es el pirómano.",
  ui_story_5046_50460402_11_dialog_content = "O no puedo ayudarte.",
  ui_story_5046_50460402_12_dialog_content = "Entonces tendremos que buscar por la fuerza.",
  ui_story_5046_50460402_13_dialog_content = "Hati tiene la Caelestita.",
  ui_story_5046_50460402_14_dialog_content = "!",
  ui_story_5046_50460402_15_dialog_content = "La seguridad de Lumopolis llegó a Umbraton solo para perder a un VIP.",
  ui_story_5046_50460402_16_dialog_content = "Extrañar Bethel no recurrió a ninguna facción de Umbraton, pero te permitió investigar de forma encubierta.",
  ui_story_5046_50460402_17_dialog_content = "Mi conjetura es que ella no quería que saliera a la luz pública.",
  ui_story_5046_50460402_18_dialog_content = "Tampoco querrás que lo difunda, ¿verdad?",
  ui_story_5046_50460402_19_dialog_content = "Humph, para que sepas dónde Hati ¿es? Déjala y podrías obtener algo de Lumopolis y Umbraton.",
  ui_story_5046_50460402_20_dialog_content = "Sí, podemos hablar de eso cuando estamos solos.",
  ui_story_5046_50460402_21_dialog_content = "Déjanos a todos.",
  ui_story_5046_50460402_22_dialog_content = "Pero Capitán—",
  ui_story_5046_50460402_23_dialog_content = "Espérame afuera.",
  ui_story_5046_50460402_24_dialog_content = "¡Sí señor!",
  ui_story_5046_50460402_25_dialog_content = "Hay una razón por la que llegaste a donde estás hoy.",
  ui_story_5046_50460402_26_dialog_content = "Ahora bien, este es un mensaje que Hati quería que yo entregara.",
  ui_story_5046_50460402_27_dialog_content = "\"Al hombre enmascarado:\"",
  ui_story_5046_50460402_28_dialog_content = "\"Trae el colgante y encuéntrame bajo el arce más alto en el lado este de Umbraton antes del atardecer. Lo vas a cambiar por Caelestite\".",
  ui_story_5046_50460402_29_dialog_content = "\"Asegúrate de venir solo y no le digas a nadie. Tampoco intentes ningún truco\".",
  ui_story_5046_50460402_30_dialog_content = "\"Hati\"",
  ui_story_5046_50460402_31_dialog_content = "...",
  ui_story_5046_50460402_32_dialog_content = "¿Puedes garantizar que la Caelestita es segura?",
  ui_story_5046_50460402_33_dialog_content = "Está seguro. El Caelestite es completamente seguro. Además, el tiempo no está de tu lado y es tu única opción.",
  ui_story_5046_50460402_34_dialog_content = "Nadie me amenaza.",
  ui_story_5046_50460402_35_dialog_content = "Tómalo con calma. Quédate a tomar algo la próxima vez.",
  ui_story_5046_50460402_36_dialog_content = "...",
  ui_story_5046_50460402_37_dialog_content = "Jefe.",
  ui_story_5046_50460402_38_dialog_content = "Mira la barra. Me tengo que ir.",
  ui_story_5046_50460402_39_dialog_content = "¡Capitán!",
  ui_story_5046_50460402_40_dialog_content = "Tengo que comprobar algo solo.",
  ui_story_5046_50460402_41_dialog_content = "Ustedes se quedan y peinan cada centímetro del lugar.",
  ui_story_5046_50460402_42_dialog_content = "Si ve al sospechoso y al Caelestite, tráigalos siempre y cuando la seguridad de este último esté garantizada.",
  ui_story_5046_50460402_43_dialog_content = "¡Sí señor!",
  ui_story_5046_50460402_44_dialog_content = "<color=#e8d9bb>Archivo Umbratón</color>",
  ui_story_5046_50460402_45_dialog_content = "Todo sobre los incendios de los últimos dos meses está aquí.",
  ui_story_5046_50460402_46_dialog_content = "Gracias. Los revisaré yo mismo.",
  ui_story_5046_50460402_47_dialog_content = "Los incendios ocurrieron con demasiada frecuencia en el período de tiempo, pero solo tres murieron.",
  ui_story_5046_50460402_48_dialog_content = "Andre, hombre, 36 años, víctima del primer incendio, trabajaba medio tiempo y era alcohólico.",
  ui_story_5046_50460402_49_dialog_content = "Fairmont, hombre, 42 años, víctima del segundo incendio, un comerciante que maneja un negocio tibio.",
  ui_story_5046_50460402_50_dialog_content = "Carlotta, mujer, 31 años, víctima del tercer incendio, una lavandera común.",
  ui_story_5046_50460402_51_dialog_content = "Los tres alguna vez trabajaron en el orfanato. Andre era contador, Fairmont, repartidor, y Carlotta, señora de la limpieza.",
  ui_story_5046_50460402_52_dialog_content = "Y el denominador común que compartían con Hati es el orfanato.",
  ui_story_5046_50460402_53_dialog_content = "Así fue Hati intimidado por ellos en el orfanato y los mató por despecho?",
  ui_story_5046_50460402_54_dialog_content = "Debo profundizar más en el antiguo personal del orfanato.",
  ui_story_5046_50460402_55_dialog_content = "Sin embargo, cada uno de ellos se dispersó después del fuego. Es prácticamente imposible encontrar a alguien con quien hablar.",
  ui_story_5046_50460402_56_dialog_content = "¿Que voy a hacer?",
  ui_story_5046_50460402_57_dialog_content = "\"El Sr. Hamell ha donado al orfanato durante mucho tiempo y organiza regularmente eventos de caridad para recaudar fondos para las instalaciones...\"",
  ui_story_5046_50460402_58_dialog_content = "¡¿Señor Hamell?!",
  ui_story_5046_50460402_59_dialog_content = "<color=#e8d9bb>dentro del orfanato</color>",
  ui_story_5046_50460402_60_dialog_content = "¿Puedo tomar unos minutos de su tiempo, Sr. Hamell?",
  ui_story_5046_50460402_61_dialog_content = "Extrañar Kristen! Encontraste la Caelestita, ¿verdad? ¡Qué maravilloso!",
  ui_story_5046_50460402_62_dialog_content = "Todavía no hay señales de Caelestite, desafortunadamente, pero tengo algunas preguntas sobre Dark Slayer que me gustaría hacerle.",
  ui_story_5046_50460402_63_dialog_content = "¿Ese pirómano?",
  ui_story_5046_50460402_64_dialog_content = "Hati es la principal sospechosa del caso, y podría haber provocado los incendios en venganza contra los trabajadores del antiguo orfanato con los que guardaba rencor.",
  ui_story_5046_50460402_65_dialog_content = "Ha estado financiando y dirigiendo organizaciones benéficas para las instalaciones durante mucho tiempo, por lo que debe conocer bien la situación.",
  ui_story_5046_50460402_66_dialog_content = "Así que me gustaría pedir su opinión.",
  ui_story_5046_50460402_67_dialog_content = "Bueno, es cierto que he estado financiando y administrando organizaciones benéficas para el orfanato.",
  ui_story_5046_50460402_68_dialog_content = "Pero el director y el personal realmente manejaron los detalles. Solo tenía que mostrar mi cara en los eventos.",
  ui_story_5046_50460402_69_dialog_content = "El orfanato me presentaba estados financieros con regularidad, pero aparte de eso, no sé nada más.",
  ui_story_5046_50460402_70_dialog_content = "Pero usted es el director del nuevo orfanato y tenía una estrecha relación con la antigua instalación.",
  ui_story_5046_50460402_71_dialog_content = "Entonces, si el sospechoso realmente está apuntando al antiguo personal del orfanato para vengarse, usted puede ser el próximo objetivo.",
  ui_story_5046_50460402_72_dialog_content = "Espero que puedas recordar más detalles. Eso nos ayudará a detener al sospechoso.",
  ui_story_5046_50460402_73_dialog_content = "Además, espero que puedas establecer una residencia temporal en un lugar protegido por Lumo Guard.",
  ui_story_5046_50460402_74_dialog_content = "El sospechoso puede atacar y amenazar tu vida en cualquier momento, y Lumo Guard puede mantenerte a salvo.",
  ui_story_5046_50460402_75_dialog_content = "Extrañar Kristen, todo lo que dijiste son conjeturas.",
  ui_story_5046_50460402_76_dialog_content = "Deberías saber que el orfanato solía ser el más grande de Umbraton. Demasiadas personas tenían una conexión con eso.",
  ui_story_5046_50460402_77_dialog_content = "Puede preguntarle a cualquiera aquí y probablemente tenga algo que ver con la instalación.",
  ui_story_5046_50460402_78_dialog_content = "Trabajadores de la construcción, personal de limpieza, incluso vendedores ambulantes fuera del orfanato...",
  ui_story_5046_50460402_79_dialog_content = "¿Me estás diciendo que el sospechoso también quiere deshacerse de ellos?",
  ui_story_5046_50460402_80_dialog_content = "Oh...",
  ui_story_5046_50460402_81_dialog_content = "La especulación es probablemente solo una coincidencia.",
  ui_story_5046_50460402_82_dialog_content = "En lugar de perder el tiempo en coincidencias, tal vez sea mejor dedicarlo a perseguir al sospechoso y hacer que todos respiren mejor.",
  ui_story_5046_50460402_83_dialog_content = "Se está haciendo tarde. Es hora de que estos viejos huesos se entreguen.",
  ui_story_5046_50460402_84_dialog_content = "Lamento molestarlo. Adiós.",
  ui_story_5046_50460402_85_dialog_content = "Perdóname por no acompañarte.",
  ui_story_5046_50460402_86_dialog_content = "Ha pasado mucho tiempo, viejo amigo.",
  ui_story_5046_50460402_87_dialog_content = "Eres tú.",
  ui_story_5046_50460402_88_dialog_content = "¿No estás feliz de ver a tu viejo amigo?",
  ui_story_5046_50460402_89_dialog_content = "No creo que estés aquí por mí, pero <color=#FFB400>esa cosa</color>, ¿bien?",
  ui_story_5046_50460501_1_dialog_content = "El Sr. Hamell estaba actuando un poco sospechoso, como si estuviera escondiendo algo.",
  ui_story_5046_50460501_2_dialog_content = "Pero no estaba dispuesto a dar más información.",
  ui_story_5046_50460501_3_dialog_content = "Hati es sospechoso, el secuestro de Caelestite, los combustibles y el detonador en el local de ensayo...",
  ui_story_5046_50460501_4_dialog_content = "El antiguo incendio del orfanato, la reticencia del Sr. Hamell...",
  ui_story_5046_50460501_5_dialog_content = "¿Puede ser todo una gran coincidencia?",
  ui_story_5046_50460501_6_dialog_content = "Suspiro ... Estoy al final del ingenio.",
  ui_story_5046_50460501_7_dialog_content = "Si tan solo el Sr. Zenas estuviera aquí. Él está seguro de—",
  ui_story_5046_50460501_8_dialog_content = "¿Me buscas, mi señora?",
  ui_story_5046_50460501_9_dialog_content = "¡¿Señor?!",
  ui_story_5046_50460501_10_dialog_content = "Cuanto tiempo llevas aqui?",
  ui_story_5046_50460501_11_dialog_content = "Un rato. Te vi murmurando para ti mismo como si estuvieras pensando profundamente, así que decidí no interrumpir.",
  ui_story_5046_50460501_12_dialog_content = "Lo siento, no me di cuenta...",
  ui_story_5046_50460501_13_dialog_content = "¡Oh, hice un gran descubrimiento en el caso, señor!",
  ui_story_5046_50460501_14_dialog_content = "¿En realidad? ¿Que encontraste?",
  ui_story_5046_50460501_15_dialog_content = "La niña que salvamos en el ensayo dijo que el fuego comenzó porque golpeó accidentalmente una caja.",
  ui_story_5046_50460501_16_dialog_content = "Supongo que la caja es un detonador configurado para encender los barriles de combustible almacenados en el almacenamiento en un momento específico.",
  ui_story_5046_50460501_17_dialog_content = "Quienquiera que lo preparó ciertamente no contó con la niña para estropear el plan.",
  ui_story_5046_50460501_18_dialog_content = "Encendido temporizado... ¿Pero para qué?",
  ui_story_5046_50460501_19_dialog_content = "Con base en investigaciones previas, solo hubo tres incendios en los últimos dos meses con víctimas.",
  ui_story_5046_50460501_20_dialog_content = "Y los tres fallecidos alguna vez trabajaron para el antiguo orfanato.",
  ui_story_5046_50460501_21_dialog_content = "Hati, quien se presentó hoy en el lugar, permaneció en esa instalación durante un mes.",
  ui_story_5046_50460501_22_dialog_content = "Creo que algo le debe haber pasado en el orfanato para que odiara a las víctimas.",
  ui_story_5046_50460501_23_dialog_content = "Después de perder el control de su poder y quemar el orfanato, el Señor de las Sombras la llevó a una mansión, por lo que se vio obligada a abandonar su plan de venganza.",
  ui_story_5046_50460501_24_dialog_content = "Hasta que fue liberada hace dos meses, lo que provocó Hati para ir inmediatamente tras ellos.",
  ui_story_5046_50460501_25_dialog_content = "El Sr. Hamell ha financiado el orfanato durante mucho tiempo y también se presentó en el lugar hoy.",
  ui_story_5046_50460501_26_dialog_content = "Así que estás pensando Hati está apuntando al Sr. Hamell.",
  ui_story_5046_50460501_27_dialog_content = "Sí, pero es solo una teoría sin nada sólido que la respalde.",
  ui_story_5046_50460501_28_dialog_content = "Así que fuiste a ver al Sr. Hamell con la esperanza de que cooperara.",
  ui_story_5046_50460501_29_dialog_content = "Sí...",
  ui_story_5046_50460501_30_dialog_content = "El Sr. Hamell descartó mi teoría como una coincidencia, pero tuve la sensación de que me estaba ocultando algo.",
  ui_story_5046_50460501_31_dialog_content = "Su cuerpo siempre va un paso por delante de su mente, milady.",
  ui_story_5046_50460501_32_dialog_content = "¿Qué quiere decir con eso, señor?",
  ui_story_5046_50460501_33_dialog_content = "Todos los que podrían alcanzar la riqueza y la fama en una bolsa mixta como Umbraton tienen sus propios secretos.",
  ui_story_5046_50460501_34_dialog_content = "Y esos secretos son sus salvavidas que no querrían que nadie más supiera, especialmente los de Lumopolis.",
  ui_story_5046_50460501_35_dialog_content = "Puedo entender cómo quiere proteger al Sr. Hamell, milady, pero solo está alarmando al sospechoso.",
  ui_story_5046_50460501_36_dialog_content = "El Sr. Hamell nunca cooperaría ni aceptaría su protección, y es probable que el sospechoso se dé cuenta de lo que ha hecho y se esconda aún más.",
  ui_story_5046_50460501_37_dialog_content = "Es una falta de previsión de mi parte... Lo siento, señor.",
  ui_story_5046_50460501_38_dialog_content = "Resulta que no te ayudo en nada...",
  ui_story_5046_50460501_39_dialog_content = "Pero no creo que tu teoría sea infundada. No todo es coincidencia.",
  ui_story_5046_50460501_40_dialog_content = "Entonces, ¿aprueba mi teoría, señor?",
  ui_story_5046_50460501_41_dialog_content = "Por supuesto. Habiendo sido testigo de tu desarrollo durante todos estos años, sé mejor que nadie de lo que eres capaz.",
  ui_story_5046_50460501_42_dialog_content = "Eres la mejor sacando pistas de los registros y entretejiéndolas en un cuerpo completo de pruebas, milady.",
  ui_story_5046_50460501_43_dialog_content = "S-Señor...",
  ui_story_5046_50460501_44_dialog_content = "¡Es porque eres un gran instructor!",
  ui_story_5046_50460501_45_dialog_content = "...",
  ui_story_5046_50460501_46_dialog_content = "Ejem. ¿No estaba investigando al sospechoso y el paradero de Caelestite, señor?",
  ui_story_5046_50460501_47_dialog_content = "Sí. Me condujo al Firefly Bar, cuyo dueño es amigo de Hati.",
  ui_story_5046_50460501_48_dialog_content = "Pero ella tenía los labios apretados, así que no pude conseguir nada. Tengo gente vigilando el bar, así que espero que consigamos algo.",
  ui_story_5046_50460501_49_dialog_content = "Ay...",
  ui_story_5046_50460501_50_dialog_content = "¿Qué pasa, señor? ¿Te duele la quemadura?",
  ui_story_5046_50460501_51_dialog_content = "Es mi culpa que te lastimaran...",
  ui_story_5046_50460501_52_dialog_content = "Estoy bien. La herida menor no me va a molestar.",
  ui_story_5046_50460501_53_dialog_content = "Ya que cree que el Sr. Hamell es el próximo objetivo de Hati, debo regresar y hacer planes...",
  ui_story_5046_50460501_54_dialog_content = "Nos quedamos sin tiempo.",
  ui_story_5046_50460501_55_dialog_content = "¡Uh!",
  ui_story_5046_50460501_56_dialog_content = "¡Por favor, deje de esforzarse demasiado, señor!",
  ui_story_5046_50460501_57_dialog_content = "Cuando nos conocimos por primera vez, te lanzaste al fuego para salvarme a pesar de tus heridas.",
  ui_story_5046_50460501_58_dialog_content = "Y hoy, me protegiste cuando me lancé imprudentemente al fuego.",
  ui_story_5046_50460501_59_dialog_content = "¡Es hora de que haga algo por ti!",
  ui_story_5046_50460501_60_dialog_content = "Mi señora...",
  ui_story_5046_50460501_61_dialog_content = "Por favor, deja de llamarme así.",
  ui_story_5046_50460501_62_dialog_content = "No quiero seguir siendo una flor mimada por usted, señor.",
  ui_story_5046_50460501_63_dialog_content = "Quiero ser un juez que traiga justicia a Lumopolis y alguien que sea tan confiable como usted, señor.",
  ui_story_5046_50460501_64_dialog_content = "Sé que todavía tengo un largo camino por recorrer, pero no iré a ninguna parte si no doy el primer paso.",
  ui_story_5046_50460501_65_dialog_content = "Incluso si es solo un pequeño paso, aún debo darlo.",
  ui_story_5046_50460501_66_dialog_content = "Entonces, ¡permítanme garantizar la seguridad del Sr. Hamell!",
  ui_story_5046_50460501_67_dialog_content = "Je...",
  ui_story_5046_50460501_68_dialog_content = "Mi señora...",
  ui_story_5046_50460501_69_dialog_content = "Quiero decir, Kristen.",
  ui_story_5046_50460501_70_dialog_content = "Ese es un sentimiento conmovedor, y estoy profundamente conmovido por la determinación.",
  ui_story_5046_50460501_71_dialog_content = "(Espera, ¿por qué se inclina más cerca...?)",
  ui_story_5046_50460501_72_dialog_content = "(Puedo sentir su aliento...)",
  ui_story_5046_50460501_73_dialog_content = "(Su pelo está haciendo que me pique la cara...)",
  ui_story_5046_50460501_74_dialog_content = "Y también puedo sentir plenamente el cariño que me tienes...",
  ui_story_5046_50460501_75_dialog_content = "(¿Cariño? ¿De qué habla?)",
  ui_story_5046_50460501_76_dialog_content = "(¡No, no me digas!)",
  ui_story_5046_50460501_77_dialog_content = "Kristen, yo...",
  ui_story_5046_50460501_78_dialog_content = "¡S-Señor!",
  ui_story_5046_50460501_79_dialog_content = "¡Debería estar de camino a casa del Sr. Hamell!",
  ui_story_5046_50460501_80_dialog_content = "¡Me esforzaré por cumplir esta misión!",
  ui_story_5046_50460501_81_dialog_content = "Jejeje...",
  ui_story_5046_50460501_82_dialog_content = "Creo que con su inteligencia y coraje, enfrentará el desafío con gran éxito.",
  ui_story_5046_50460501_83_dialog_content = "¡Gracias, señor!",
  ui_story_5046_50460501_84_dialog_content = "¡No te defraudaré y completaré la misión!",
  ui_story_5046_50460501_85_dialog_content = "<color=#e8d9bb>Umbratón rural</color>",
  ui_story_5046_50460501_86_dialog_content = "Ese es el arce más alto del bosque.",
  ui_story_5046_50460501_87_dialog_content = "¿Estamos allí ahora?",
  ui_story_5046_50460501_88_dialog_content = "Los senderos están llenos de baches en el bosque, así que ten cuidado—",
  ui_story_5046_50460501_89_dialog_content = "¡Ay!",
  ui_story_5046_50460501_90_dialog_content = "—o te tropezarás.",
  ui_story_5046_50460501_91_dialog_content = "¡Duele!",
  ui_story_5046_50460501_92_dialog_content = "Siéntate.",
  ui_story_5046_50460501_93_dialog_content = "No es serio. Estarás bien.",
  ui_story_5046_50460501_94_dialog_content = "Siéntate tú.",
  ui_story_5046_50460501_95_dialog_content = "(Qué intimidante... No puedo luchar contra eso en absoluto...)",
  ui_story_5046_50460501_96_dialog_content = "Está bien, me sentaré un rato.",
  ui_story_5046_50460501_97_dialog_content = "Enróllate las piernas del pantalón.",
  ui_story_5046_50460501_98_dialog_content = "¿Para qué?",
  ui_story_5046_50460501_99_dialog_content = "Haré que duela menos.",
  ui_story_5046_50460501_100_dialog_content = "Bueno, no está doliendo tanto... Vaya, no tienes que enrollarlo por mí, ¡puedo hacerlo yo mismo!",
  ui_story_5046_50460501_101_dialog_content = "¿Es esto lo suficientemente bueno?",
  ui_story_5046_50460501_102_dialog_content = "Sí, debería estar aquí. ¿Esto duele cuando lo presiono?",
  ui_story_5046_50460501_103_dialog_content = "¡Está bien, pero tu mano está caliente! Aunque hace bastante frío en el bosque.",
  ui_story_5046_50460501_104_dialog_content = "La temperatura de mi cuerpo es más alta de lo normal. Acércate si tienes frío.",
  ui_story_5046_50460501_105_dialog_content = "(Hati puede parecer inaccesible, pero sus orejas esponjosas se animan cuando se agacha).",
  ui_story_5046_50460501_106_dialog_content = "(Y en realidad es bastante amable, recordándome que tenga cuidado al caminar aquí y masajearme el tobillo torcido...)",
  ui_story_5046_50460501_107_dialog_content = "¿Qué ocurre?",
  ui_story_5046_50460501_108_dialog_content = "¡Nada, nada!",
  ui_story_5046_50460501_109_dialog_content = "Todavía tenemos tiempo. ¿Por qué no nos tomamos un descanso aquí?",
  ui_story_5046_50460501_110_dialog_content = "Está bien...",
  ui_story_5046_50460501_111_dialog_content = "...",
  ui_story_5046_50460501_112_dialog_content = "...",
  ui_story_5046_50460501_113_dialog_content = "(Esto es incómodo. Debería decir algo...)",
  ui_story_5046_50460501_114_dialog_content = "¿Puedes hablarme de tu madre?",
  ui_story_5046_50460501_115_dialog_content = "¡N-no quise decir nada malo con eso!",
  ui_story_5046_50460501_116_dialog_content = "Mi madre me dejó poco después de que yo naciera. Ni siquiera llegué a ver cómo era...",
  ui_story_5046_50460501_117_dialog_content = "...",
  ui_story_5046_50460501_118_dialog_content = "Supongo que no tienes ganas de decírmelo, e-está bien.",
  ui_story_5046_50460501_119_dialog_content = "...",
  ui_story_5046_50460501_120_dialog_content = "Francamente, entiendo cuánto deseas recuperar esos recuerdos.",
  ui_story_5046_50460501_121_dialog_content = "...",
  ui_story_5046_50460501_122_dialog_content = "Soroz es el que me crió durante todos estos años.",
  ui_story_5046_50460501_123_dialog_content = "No es solo un Coloso, sino también mi amigo y maestro.",
  ui_story_5046_50460501_124_dialog_content = "Somos inseparables desde hace muchos años. Me enseñaría sobre el mundo exterior y charlaría cuando estaba aburrido.",
  ui_story_5046_50460501_125_dialog_content = "Lástima que ahora no se acuerde de mí.",
  ui_story_5046_50460501_126_dialog_content = "¿Perdió su memoria también?",
  ui_story_5046_50460501_127_dialog_content = "Perdió todos los recuerdos para salvar mi vida, así que estoy trabajando para encontrar una manera de restaurarlo.",
  ui_story_5046_50460501_128_dialog_content = "Grimme tenía razón, tenemos algo en común.",
  ui_story_5046_50460501_129_dialog_content = "Y eso es que ambos estamos trabajando duro para recuperar los recuerdos.",
  ui_story_5046_50460501_130_dialog_content = "Así que entiendo cómo te sientes y espero que puedas recordar los eventos con tu madre.",
  ui_story_5046_50460501_131_dialog_content = "...",
  ui_story_5046_50460501_132_dialog_content = "Siéntase libre de hacerme saber si hay algo en lo que pueda ayudar con la memoria de Soroz.",
  ui_story_5046_50460501_133_dialog_content = "¡Antes de que puedas ayudar, debes borrar tu estatus de sospechoso!",
  ui_story_5046_50460501_134_dialog_content = "Prométeme que te sincerarás después de que consigamos el colgante, ¿de acuerdo?",
  ui_story_5046_50460501_135_dialog_content = "Tsk... Qué problemático.",
  ui_story_5046_50460501_136_dialog_content = "¡Sí, pero todavía tienes que hacerlo!",
  ui_story_5046_50460501_137_dialog_content = "Está bien.",
  ui_story_5046_50460501_138_dialog_content = "¡Lo prometes!",
  ui_story_5046_50460501_139_dialog_content = "Graah-!",
  ui_story_5046_50460501_140_dialog_content = "Tenemos Eclipses en camino, y muchos de ellos...",
  ui_story_5046_50460501_141_dialog_content = "Gaaaaaah!!!",
  ui_story_5046_50460501_142_dialog_content = "Cuidado.",
  ui_story_5046_50460501_143_dialog_content = "Vamos, PlayerName, ¿por qué eres tan débil?",
  ui_story_5046_50460501_144_dialog_content = "¡Los caelestitas nunca fueron conocidos por pelear!",
  ui_story_5046_50460501_145_dialog_content = "Impotente.",
  ui_story_5046_50460501_146_dialog_content = "No me mires por encima del hombro. ¡Los eclipses vienen a su izquierda!",
  ui_story_5046_50460501_147_dialog_content = "Graah-!",
  ui_story_5046_50460501_148_dialog_content = "¡Cómete mi hacha!",
  ui_story_5046_50460501_149_dialog_content = "¿Como es que? Puede que no sea capaz de pelear, pero mi habilidad para coordinar tiene el sello de aprobación de Carleen!",
  ui_story_5046_50460501_150_dialog_content = "¡Entonces escóndete detrás de mí y coordina!",
  ui_story_5046_50460502_1_dialog_content = "Esto es malo, ¿cómo puede haber tantos eclipses aquí?",
  ui_story_5046_50460502_2_dialog_content = "Jadeo... jadeo...",
  ui_story_5046_50460502_3_dialog_content = "Este no es el lugar ni el momento para que baje...",
  ui_story_5046_50460502_4_dialog_content = "Graah...",
  ui_story_5046_50460502_5_dialog_content = "¡Vienen más eclipses!",
  ui_story_5046_50460502_6_dialog_content = "¡Maldiciones! debo hacer eso...",
  ui_story_5046_50460502_7_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5046_50460502_8_dialog_content = "Graah-!",
  ui_story_5046_50460502_9_dialog_content = "Vaya, los Eclipsites... ¡Están todos quemados!",
  ui_story_5046_50460502_10_dialog_content = "No siento más eclipses por aquí.",
  ui_story_5046_50460502_11_dialog_content = "Uf... uf...",
  ui_story_5046_50460502_12_dialog_content = "¡Urgh!",
  ui_story_5046_50460502_13_dialog_content = "Usaste el poder...",
  ui_story_5046_50460502_14_dialog_content = "Tsk, tsk...",
  ui_story_5046_50460502_15_dialog_content = "Tú... Te has convertido en lo que odiabas...",
  ui_story_5046_50460502_16_dialog_content = "Así es como... madre... nos dejó...",
  ui_story_5046_50460502_17_dialog_content = "¡Callarse la boca! ¡Digo que te calles la boca!",
  ui_story_5046_50460502_18_dialog_content = "Qué ocurre, Hati?!",
  ui_story_5046_50460502_19_dialog_content = "(Hati está rodando por el suelo en agonía con los ojos cerrados.)",
  ui_story_5046_50460502_20_dialog_content = "Digo, ¡cállate!",
  ui_story_5046_50460502_21_dialog_content = "Mamá... no soy un niño travieso... no soy...",
  ui_story_5046_50460502_22_dialog_content = "¿Mamá? ¿Está inmersa en recuerdos del pasado?",
  ui_story_5046_50460502_23_dialog_content = "Esto no va a ser bueno. Tengo que usar mi habilidad psíquica para liberarla.",
  ui_story_5046_50460502_24_dialog_content = "Lo siento, Hati, pero no pretendo entrometerme en tu mente.",
  ui_story_5046_50460502_25_option_content = "¡Potencia de fuerza!",
  ui_story_5046_50460502_26_dialog_content = "(¿Dónde estoy?)",
  ui_story_5046_50460502_27_dialog_content = "¡Mamá, tienes berberecho encima! Déjame quitártelos.",
  ui_story_5046_50460502_28_dialog_content = "Gracias, Hati.",
  ui_story_5046_50460502_29_dialog_content = "Eres un buen chico.",
  ui_story_5046_50460502_30_dialog_content = "Jeje...",
  ui_story_5046_50460502_31_dialog_content = "No es frecuente que me lleves a jugar, mamá.",
  ui_story_5046_50460502_32_dialog_content = "(Es un poco Hati, y su madre también.)",
  ui_story_5046_50460502_33_dialog_content = "...",
  ui_story_5046_50460502_34_dialog_content = "Lo siento, Hati.",
  ui_story_5046_50460502_35_dialog_content = "¿Por qué te disculpas, mamá? No hiciste nada malo.",
  ui_story_5046_50460502_36_dialog_content = "Bueno, es mi culpa.",
  ui_story_5046_50460502_37_dialog_content = "No, no hiciste nada malo...",
  ui_story_5046_50460502_38_dialog_content = "Deberías estar jugando afuera como cualquier otro niño, pero—",
  ui_story_5046_50460502_39_dialog_content = "¿Hago bien en hacer esto, Fenrir...?",
  ui_story_5046_50460502_40_dialog_content = "¿Estás llorando por mí, mamá?",
  ui_story_5046_50460502_41_dialog_content = "Entonces no saldré más.",
  ui_story_5046_50460502_42_dialog_content = "Está bien, estoy bien... ¡Ven, vamos a jugar!",
  ui_story_5046_50460502_43_dialog_content = "¡Cerraré los ojos, contaré hasta tres y vendré a buscarte!",
  ui_story_5046_50460502_44_dialog_content = "¡Está bien!",
  ui_story_5046_50460502_45_dialog_content = "Tres...",
  ui_story_5046_50460502_46_dialog_content = "Graah...",
  ui_story_5046_50460502_47_dialog_content = "Algo negro se acerca a mamá...",
  ui_story_5046_50460502_48_dialog_content = "Dos...",
  ui_story_5046_50460502_49_dialog_content = "La cosa negra parece que la va a lastimar...",
  ui_story_5046_50460502_50_dialog_content = "Uno...",
  ui_story_5046_50460502_51_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5046_50460502_52_dialog_content = "!!!",
  ui_story_5046_50460502_53_dialog_content = "Hati?!",
  ui_story_5046_50460502_54_dialog_content = "¡Mamá, este bicho es muy malo!",
  ui_story_5046_50460502_55_dialog_content = "¡Lo convertiré en una bola de fuego!",
  ui_story_5046_50460502_56_dialog_content = "¡Hah!",
  ui_story_5046_50460502_57_dialog_content = "¡¿Por qué no te dije que no usaras fuego?!",
  ui_story_5046_50460502_58_dialog_content = "¿Por qué no escuchas?",
  ui_story_5046_50460502_59_dialog_content = "Pero mama...",
  ui_story_5046_50460502_60_dialog_content = "¡Vete a casa conmigo ahora!",
  ui_story_5046_50460502_61_dialog_content = "Boo-hoo... ¿Por qué...?",
  ui_story_5046_50460502_62_dialog_content = "¿Mamá me odia... cuando juego con fuego...?",
  ui_story_5046_50460502_63_dialog_content = "(A mamá no le gusta Hati... No le gusta el fuego...)",
  ui_story_5046_50460502_64_dialog_content = "(Hati es un niño travieso...)",
  ui_story_5046_50460502_65_dialog_content = "(Niño travieso...)",
  ui_story_5046_50460502_66_dialog_content = "(Hati es... un niño travieso?)",
  ui_story_5046_50460502_67_dialog_content = "(No, Hati no es un niño travieso!)",
  ui_story_5046_50460502_68_dialog_content = "(Usar el poder que mamá no aprobó para salvar a sus seres queridos...)",
  ui_story_5046_50460502_69_dialog_content = "(Eso no significa Hati es un niño travieso!)",
  ui_story_5046_50460502_70_dialog_content = "(Hati no es un niño travieso...?)",
  ui_story_5046_50460502_71_dialog_content = "(Tu mamá debe haber tenido una razón tácita para ser mala con Hati...)",
  ui_story_5046_50460502_72_dialog_content = "(¡Y cuando eras joven te veías genial usando fuego para proteger a tu mamá!)",
  ui_story_5046_50460502_73_dialog_content = "(Al igual que el fresco Hati ¡Quién usó el fuego para protegerme!)",
  ui_story_5046_50460502_74_dialog_content = "(Hati es un niño genial, increíble!)",
  ui_story_5046_50460502_75_dialog_content = "(Hati ¿Es un niño increíble?)",
  ui_story_5046_50460502_76_dialog_content = "(Así es, Hati es un chico genial! Ahora cálmate y despierta lentamente...)",
  ui_story_5046_50460502_77_dialog_content = "...",
  ui_story_5046_50460502_78_dialog_content = "¿PlayerName?",
  ui_story_5046_50460502_79_dialog_content = "Soy yo. Te sientes bien, ¿verdad?",
  ui_story_5046_50460502_80_dialog_content = "Sí...",
  ui_story_5046_50460502_81_dialog_content = "Siento causarte problemas.",
  ui_story_5046_50460502_82_dialog_content = "No, debería disculparme.",
  ui_story_5046_50460502_83_dialog_content = "Me colé en tu memoria sin tu permiso...",
  ui_story_5046_50460502_84_dialog_content = "¡Espero que no estés enojado conmigo por eso!",
  ui_story_5046_50460502_85_dialog_content = "Si no fuera por ti...",
  ui_story_5046_50460502_86_dialog_content = "Probablemente me hubiera vuelto loco.",
  ui_story_5046_50460502_87_dialog_content = "Así que gracias.",
  ui_story_5046_50460502_88_dialog_content = "Vale, no estoy acostumbrado a que te pongas tan recatada de repente.",
  ui_story_5046_50460502_89_dialog_content = "Ejem, ya casi es hora. Tenemos que llegar a ese árbol.",
  ui_story_5046_50460502_90_dialog_content = "Si aún necesitas que recupere recuerdos para ti después de que todo esto termine...",
  ui_story_5046_50460502_91_dialog_content = "Ven a verme al Coloso.",
  ui_story_5046_50460502_92_dialog_content = "Seguro.",
  ui_story_5046_50460502_93_dialog_content = "Además, recuerda que prometiste explicarlo todo y aclararte...",
  ui_story_5046_50460502_94_dialog_content = "De lo contrario, recibirás una recompensa antes de que puedas verme.",
  ui_story_5046_50460502_95_dialog_content = "Lo prometo.",
  ui_story_5046_50460502_96_dialog_content = "¿Tú haces?",
  ui_story_5046_50460502_97_dialog_content = "Si.",
  ui_story_5046_50460601_1_dialog_content = "(Un escuadrón de guardias de Lumopolis llegó al orfanato esta mañana pero el Sr. Hamell no los despidió).",
  ui_story_5046_50460601_2_dialog_content = "(E incluso los sacó de Umbraton y los llevó a este bosque...)",
  ui_story_5046_50460601_3_dialog_content = "(Ahora tanto el Caelestite y Hati están aquí, y los dos bandos chocan.)",
  ui_story_5046_50460601_4_dialog_content = "(Estos guardias no luchan al estilo de Lumopolis, pero vestían uniformes de Lumo Guard).",
  ui_story_5046_50460601_5_dialog_content = "(Que está pasando aqui...?)",
  ui_story_5046_50460601_6_dialog_content = "(Es inútil detenerlos en este momento, así que solo debería mirar desde aquí por el momento).",
  ui_story_5046_50460601_7_dialog_content = "Huff... huff... Incluso eso no podría matarte.",
  ui_story_5046_50460601_8_dialog_content = "Sr. Hamell? ¿Qué estás diciendo? ¿Y que estás haciendo aquí?",
  ui_story_5046_50460601_9_dialog_content = "¿Dónde está el Sr. Zenas? ¿No le llegó el mensaje?",
  ui_story_5046_50460601_10_dialog_content = "En lugar de esperar a que vengas a matarme, prefiero un ataque preventivo.",
  ui_story_5046_50460601_11_dialog_content = "¿No mataste a Andre, Fairmont y Carlotta?",
  ui_story_5046_50460601_12_dialog_content = "¿Guardas rencor por lo que te pasó en el orfanato y quieres vengarte de nosotros?",
  ui_story_5046_50460601_13_dialog_content = "Querías matarnos a los dos de un solo golpe en el ensayo, ¿verdad?",
  ui_story_5046_50460601_14_dialog_content = "Lástima que ese plan fracasó.",
  ui_story_5046_50460601_15_dialog_content = "No tengo idea de quiénes son esas personas, y solo estaba pasando por el ensayo.",
  ui_story_5046_50460601_16_dialog_content = "¡Deja de hacerte el tonto! Nada te gustaría más que para mí y... ¡Argh!",
  ui_story_5046_50460601_17_dialog_content = "¡Cuidado!",
  ui_story_5046_50460601_18_dialog_content = "(¡El Sr. Hamell está caído! Hati ¿Mátalo?)",
  ui_story_5046_50460601_19_dialog_content = "¡Aguante, Sr. Hamell!",
  ui_story_5046_50460601_20_dialog_content = "Él está muerto.",
  ui_story_5046_50460601_21_dialog_content = "Hati Kelp, eres sospechoso de asesinato. ¡Exijo que vengas conmigo a Umbraton para una mayor investigación!",
  ui_story_5046_50460601_22_dialog_content = "Extrañar Kristen? ¿Qué estás haciendo aquí?",
  ui_story_5046_50460601_23_dialog_content = "Yo no lo maté.",
  ui_story_5046_50460601_24_dialog_content = "Por supuesto, dirías eso.",
  ui_story_5046_50460601_25_dialog_content = "Puedo dar fe de la inocencia de Hati. El Sr. Hamell cayó intacto.",
  ui_story_5046_50460601_26_dialog_content = "¿Por qué estás albergando a un asesino, PlayerName?",
  ui_story_5046_50460601_27_dialog_content = "Todavía tiene un arma letal en la mano...",
  ui_story_5046_50460601_28_dialog_content = "¡Yo estoy diciendo la verdad!",
  ui_story_5046_50460601_29_dialog_content = "Ya que quieren defenderse, ¿por qué no vienen al Salón de la Justicia conmigo?",
  ui_story_5046_50460601_30_dialog_content = "Aunque solo soy un juez de prueba, debo asegurarme de que se haga justicia y que ningún delito quede impune.",
  ui_story_5046_50460601_31_dialog_content = "De ninguna manera, no puedo ir contigo todavía.",
  ui_story_5046_50460601_32_dialog_content = "Resistirse al arresto solo empeorará las cosas.",
  ui_story_5046_50460601_33_dialog_content = "Sí lo que sea.",
  ui_story_5046_50460601_34_dialog_content = "¡Por favor, tranquilícense, los dos!",
  ui_story_5046_50460601_35_dialog_content = "¡Kristen! ¿Estás bien?",
  ui_story_5046_50460601_36_dialog_content = "Llegas tarde, hombre enmascarado.",
  ui_story_5046_50460601_37_dialog_content = "¿Es este el Sr. Hamell?",
  ui_story_5046_50460601_38_dialog_content = "Hati? Mataste al Sr. Hamell, ¿no? arrestarla de una vez, Kristen.",
  ui_story_5046_50460601_39_dialog_content = "¡Espera un minuto! Hati no hizo nada de eso!",
  ui_story_5046_50460601_40_dialog_content = "¿Quieres pelear? No hay problema conmigo!",
  ui_story_5046_50460601_41_dialog_content = "Es peligroso allá, PlayerName, ¡ven aquí!",
  ui_story_5046_50460601_42_dialog_content = "¡Toma esto!",
  ui_story_5046_50460601_43_dialog_content = "Eres muy lento.",
  ui_story_5046_50460601_44_dialog_content = "<color=#e8d9bb>¡Golpe!</color>",
  ui_story_5046_50460601_45_dialog_content = "mi mascara...",
  ui_story_5046_50460601_46_dialog_content = "La cara...!",
  ui_story_5046_50460601_47_dialog_content = "¿Quién es él? ¡¿Quién es él?!",
  ui_story_5046_50460601_48_dialog_content = "¿Qué pasa, Hati?",
  ui_story_5046_50460601_49_dialog_content = "¡Yo... eh... oh...!",
  ui_story_5046_50460601_50_dialog_content = "<color=#e8d9bb>\"Ese día-\"</color>",
  ui_story_5046_50460601_51_dialog_content = "<color=#e8d9bb>\"Vi esta cara\".</color>",
  ui_story_5046_50460601_52_dialog_content = "<color=#e8d9bb>\"Ese día-\"</color>",
  ui_story_5046_50460601_53_dialog_content = "<color=#e8d9bb>\"¿Qué me pasó... a mí... madre?\"</color>",
  ui_story_5046_50460601_54_dialog_content = "¡Aghhhh!",
  ui_story_5046_50460601_55_dialog_content = "Hati? Hati?!",
  ui_story_5046_50460601_56_dialog_content = "Algo anda mal con ella, señor.",
  ui_story_5046_50460601_57_dialog_content = "¡Ahhhhhhh!",
  ui_story_5046_50460601_58_dialog_content = "Hati! Hati! ¿Puedes oírme?",
  ui_story_5046_50460601_59_dialog_content = "¡Animarse!",
  ui_story_5046_50460601_60_dialog_content = "¡Uh!",
  ui_story_5046_50460601_61_dialog_content = "<color=#e8d9bb>Chisporrotear-</color>",
  ui_story_5046_50460601_62_dialog_content = "¡Su look acaba de cambiar! ¡¿Y ella está en llamas?!",
  ui_story_5046_50460601_63_dialog_content = "¡Cuidadoso! Retroceder, Kristen!",
  ui_story_5046_50460601_64_dialog_content = "Awoo!!!",
  ui_story_5046_50460601_65_dialog_content = "Hati!!!",
  ui_story_5046_50460601_66_dialog_content = "(La forma en que se ve ahora se parece al demonio interior que vi en su memoria...)",
  ui_story_5046_50460601_67_dialog_content = "(¿Se ha apoderado de ella? De ninguna manera, ¡tengo que sacarla de ahí!)",
  ui_story_5046_50460601_68_dialog_content = "Ven aquí, PlayerName! Hati es una amenaza peligrosa en este momento!",
  ui_story_5046_50460601_69_dialog_content = "Todo está bien, Hati no me hará daño! ¡Ella me necesita ahora!",
  ui_story_5046_50460601_70_dialog_content = "debes calmarte, Hati!",
  ui_story_5046_50460601_71_dialog_content = "¡Awooo!",
  ui_story_5046_50460601_72_dialog_content = "¡Deja de perder el tiempo, ella no está escuchando!",
  ui_story_5046_50460601_73_dialog_content = "Ven aquí rápido, PlayerName!",
  ui_story_5046_50460601_74_dialog_content = "PlayerName...",
  ui_story_5046_50460601_75_dialog_content = "Hati está llamando mi nombre!",
  ui_story_5046_50460601_76_dialog_content = "¡No, no puedo dejarla sola!",
  ui_story_5046_50460601_77_dialog_content = "(¿Hay alguna forma de que ella me escuche...)",
  ui_story_5046_50460601_78_dialog_content = "(Lo tengo, puedo hacer esto...)",
  ui_story_5046_50460601_79_option_content = "¡Potencia de fuerza!",
  ui_story_5046_50460601_80_dialog_content = "(Cálmate, Hati!)",
  ui_story_5046_50460601_81_dialog_content = "(PlayerName? Yo... simplemente no pude controlarme... cuando vi la cara de ese hombre...)",
  ui_story_5046_50460601_82_dialog_content = "(Me empezó a doler mucho la cabeza. Urgh—)",
  ui_story_5046_50460601_83_dialog_content = "(Que voy a hacer...?)",
  ui_story_5046_50460601_84_dialog_content = "(De todos modos, tenemos que salir de aquí y encontrar un lugar tranquilo para que te relajes).",
  ui_story_5046_50460601_85_dialog_content = "(Vamos juntos...?)",
  ui_story_5046_50460601_86_dialog_content = "(¡Juntos!)",
  ui_story_5046_50460601_87_dialog_content = "¡No dejes que se escapen! ¡Puaj!",
  ui_story_5046_50460601_88_dialog_content = "¡Quédese quieto, señor, está herido!",
  ui_story_5046_50460601_89_dialog_content = "¿Dónde está la Caelestita?",
  ui_story_5046_50460601_90_dialog_content = "Hati se lo llevo con ella...",
  ui_story_5046_50460601_91_dialog_content = "¡Ratas, se escapó otra vez!",
  ui_story_5046_50460601_92_dialog_content = "¿Dónde está mi máscara?",
  ui_story_5046_50460601_93_dialog_content = "¡Te lo conseguiré, solo quédate quieto!",
  ui_story_5046_50460601_94_dialog_content = "(La herida en su rostro...)",
  ui_story_5046_50460601_95_dialog_content = "¡Ay no, fuego!",
  ui_story_5046_50460601_96_dialog_content = "¡La joven señorita todavía está adentro!",
  ui_story_5046_50460601_97_dialog_content = "¿Hay alguien todavía allí?",
  ui_story_5046_50460601_98_dialog_content = "Por favor, señor, le ruego que salve a la señorita Kristen!",
  ui_story_5046_50460601_99_dialog_content = "Tose, tose.",
  ui_story_5046_50460601_100_dialog_content = "Mamá... Papá... ¿Dónde estás...?",
  ui_story_5046_50460601_101_dialog_content = "¡Extrañar!",
  ui_story_5046_50460601_102_dialog_content = "Quién... Quién es este...",
  ui_story_5046_50460601_103_dialog_content = "Por fin te encontré. No tengas miedo, te sacaré de esta.",
  ui_story_5046_50460601_104_dialog_content = "¿Estás bien, mi señora?",
  ui_story_5046_50460601_105_dialog_content = "Estoy bien, gracias—¡Ah!",
  ui_story_5046_50460601_106_dialog_content = "¡Oh, no! ¡Tu cara está gravemente herida! ¡Debe ser tratado inmediatamente!",
  ui_story_5046_50460601_107_dialog_content = "¿A mí? Lamento asustar a la joven.",
  ui_story_5046_50460601_108_dialog_content = "Lo siento. Me salvaste solo para que yo...",
  ui_story_5046_50460601_109_dialog_content = "Está bien. Me alegro de que estés bien.",
  ui_story_5046_50460601_110_dialog_content = "May Pregunto tu nombre...?",
  ui_story_5046_50460601_111_dialog_content = "Zenas.",
  ui_story_5046_50460601_112_dialog_content = "A partir de hoy, soy su tutora en casa, milady.",
  ui_story_5046_50460601_113_dialog_content = "¡Eso es genial, señor!",
  ui_story_5046_50460601_114_dialog_content = "Estoy agradecido de que aceptes a un noble humilde como yo, además de recomendarme a tu padre.",
  ui_story_5046_50460601_115_dialog_content = "¿Es usted un noble, señor?",
  ui_story_5046_50460601_116_dialog_content = "Sí. Mira, este es el escudo de mi familia.",
  ui_story_5046_50460601_117_dialog_content = "Qué patrón tan único.",
  ui_story_5046_50460601_118_dialog_content = "La casa ha declinado y ya no vale la pena mencionarla.",
  ui_story_5046_50460601_119_dialog_content = "<color=#e8d9bb>\"Desde entonces, se quedó y me enseñó\".</color>",
  ui_story_5046_50460601_120_dialog_content = "<color=#e8d9bb>\"Hasta que renunció y se fue a servir a Lumopolis a título oficial\".</color>",
  ui_story_5046_50460601_121_dialog_content = "<color=#e8d9bb>\"Después de graduarme de Dawn Academy, me uní al Lumo Hall of Justice y continué siguiéndolo\".</color>",
  ui_story_5046_50460601_122_dialog_content = "Su máscara, señor.",
  ui_story_5046_50460601_123_dialog_content = "Uf...",
  ui_story_5046_50460601_124_dialog_content = "Hati mató al Sr. Hamell y secuestró a Caelestite nuevamente.",
  ui_story_5046_50460601_125_dialog_content = "Debemos enviar guardias en su persecución y ampliar nuestra investigación.",
  ui_story_5046_50460601_126_dialog_content = "¡Sí señor!",
  ui_story_5046_50460601_127_dialog_content = "Aquí es donde te sales del caso, Kristen.",
  ui_story_5046_50460601_128_dialog_content = "¿Qué?",
  ui_story_5046_50460601_129_dialog_content = "Teniendo en cuenta que el caso solo empeorará, no quiero ponerte en más peligro.",
  ui_story_5046_50460601_130_dialog_content = "Además, basándome en el incidente con Hamell, creo que todavía te falta la experiencia para enredarte con el sospechoso.",
  ui_story_5046_50460601_131_dialog_content = "Pero nadie está más involucrado en estos casos que yo excepto usted, señor. ¡Permíteme seguir ayudándote!",
  ui_story_5046_50460601_132_dialog_content = "No digas más. Los manejaré yo mismo.",
  ui_story_5046_50460601_133_dialog_content = "Simplemente recopile todos los hallazgos hasta ahora en un archivo y entréguelo al Salón de Justicia.",
  ui_story_5046_50460601_134_dialog_content = "Pero-",
  ui_story_5046_50460601_135_dialog_content = "¡Suficiente! Puede que seas mi jovencita, pero yo soy tu superior.",
  ui_story_5046_50460601_136_dialog_content = "¡Sigue mi orden!",
  ui_story_5046_50460601_137_dialog_content = "Si...",
  ui_story_5046_50460601_138_dialog_content = "Probablemente fui demasiado duro con mis palabras, pero fue por preocupación por tu seguridad.",
  ui_story_5046_50460601_139_dialog_content = "Deberías volver ahora.",
  ui_story_5046_50460601_140_dialog_content = "La primera vez que mandé a seguir al sospechoso y lo arruiné todo.",
  ui_story_5046_50460601_141_dialog_content = "Incluso si él no me dejara, voy a llegar al fondo de esto.",
  ui_story_5046_50460601_142_dialog_content = "Sin mencionar que tengo mis dudas sobre todos estos casos...",
  ui_story_5046_50460601_143_dialog_content = "Si Hati destinado a prender el fuego, ¿por qué salvó PlayerName y la niña?",
  ui_story_5046_50460601_144_dialog_content = "Además, ¿por qué PlayerName hablar por Hati y ayudarla a escapar cuando él es el rehén?",
  ui_story_5046_50460601_145_dialog_content = "Antes de morir, Hamell mencionó que Hati tenía otro objetivo a su lado.",
  ui_story_5046_50460601_146_dialog_content = "Averigua quién es y lo encontraré. Hati.",
  ui_story_5046_50460601_147_dialog_content = "¡Señor Zenas, esta vez le demostraré que ya no soy una flor mimada!",
  ui_story_5046_50460601_148_dialog_content = "¡Seré absolutamente una ayuda invaluable a través de mis propias habilidades!",
  ui_story_5046_50460701_1_dialog_content = "(Uf, la manta mojada es lo peor).",
  ui_story_5046_50460701_2_dialog_content = "(¿El techo está goteando otra vez? Ese nunca fue el caso con la casa anterior).",
  ui_story_5046_50460701_3_dialog_content = "¿Mamá mamá?",
  ui_story_5046_50460701_4_dialog_content = "(¿Mamá está dormida?)",
  ui_story_5046_50460701_5_dialog_content = "(Últimamente ha salido mucho y tenía que cocinar y hacer quehaceres cuando llegaba a casa, así que debe estar muy cansada).",
  ui_story_5046_50460701_6_dialog_content = "(¡Soy una niña grande ahora y no puedo causarle problemas a mamá!)",
  ui_story_5046_50460701_7_dialog_content = "(¡Tengo que secar la manta yo mismo!)",
  ui_story_5046_50460701_8_dialog_content = "(¡Ella estará muy feliz cuando me vea haciendo las tareas después de que se despierte!)",
  ui_story_5046_50460701_9_dialog_content = "(¡Ella me llamará un buen chico!)",
  ui_story_5046_50460701_10_dialog_content = "<color=#e8d9bb>Tu-tum... Tu-tum...</color>",
  ui_story_5046_50460701_11_dialog_content = "(Uf, esto debería bastar. ¿Cuánto tiempo suele colgar mamá la manta?)",
  ui_story_5046_50460701_12_dialog_content = "(¡Ojalá se seque antes de que mamá se despierte!)",
  ui_story_5046_50460701_13_dialog_content = "¡Seca, mantita!",
  ui_story_5046_50460701_14_dialog_content = "¡Mantita, mantita!",
  ui_story_5046_50460701_15_dialog_content = "¡Seca ahora!",
  ui_story_5046_50460701_16_dialog_content = "<color=#e8d9bb>Chisporrotear-</color>",
  ui_story_5046_50460701_17_dialog_content = "¡Whoa!",
  ui_story_5046_50460701_18_dialog_content = "¡¿De dónde vino el fuego?!",
  ui_story_5046_50460701_19_dialog_content = "¡Mamá se va a enojar si ve esto!",
  ui_story_5046_50460701_20_dialog_content = "¡Tengo que apagar el fuego!",
  ui_story_5046_50460701_21_dialog_content = "Hati? ¡¿Qué estás haciendo?!",
  ui_story_5046_50460701_22_dialog_content = "Boo-hoo... ¡Mamá!",
  ui_story_5046_50460701_23_dialog_content = "(Parecía muy asustada... ¡Tengo que disculparme ahora!)",
  ui_story_5046_50460701_24_dialog_content = "Lo siento, solo quería secar la manta...",
  ui_story_5046_50460701_25_dialog_content = "No quise prenderle fuego... solo...",
  ui_story_5046_50460701_26_dialog_content = "¿Estás herida?",
  ui_story_5046_50460701_27_dialog_content = "No... No lo hice a propósito, mamá...",
  ui_story_5046_50460701_28_dialog_content = "Y no quise hacer nada que tú no quisieras que hiciera...",
  ui_story_5046_50460701_29_dialog_content = "De acuerdo, ¡recuerda nunca volver a usar tu poder!",
  ui_story_5046_50460701_30_dialog_content = "¿¡Me escuchas!?",
  ui_story_5046_50460701_31_dialog_content = "(Mamá es tan feroz...)",
  ui_story_5046_50460701_32_dialog_content = "Pero solo estaba... No lo hice a propósito...",
  ui_story_5046_50460701_33_dialog_content = "¡Wahhhhh—!",
  ui_story_5046_50460701_34_dialog_content = "Todavía no puedes controlar el poder en este momento...",
  ui_story_5046_50460701_35_dialog_content = "Y es muy poderoso, lo suficiente como para lastimarte si te descuidas...",
  ui_story_5046_50460701_36_dialog_content = "También hay personas que querrían el poder y eso también puede lastimarte...",
  ui_story_5046_50460701_37_dialog_content = "Así que nunca lo vuelvas a usar, oyes, Hati?",
  ui_story_5046_50460701_38_dialog_content = "Boo-hoo... Lo tengo...",
  ui_story_5046_50460701_39_dialog_content = "(Mamá...)",
  ui_story_5046_50460701_40_dialog_content = "<color=#e8d9bb>\"¿Tanto miedo tienes de mi poder, mamá?\"</color>",
  ui_story_5046_50460701_41_dialog_content = "<color=#e8d9bb>\"¿Me tienes tanto miedo, mamá?\"</color>",
  ui_story_5046_50460701_42_dialog_content = "<color=#e8d9bb>\"¡Pero te amo más, mamá!\"</color>",
  ui_story_5046_50460701_43_dialog_content = "¡Aghhhh!",
  ui_story_5046_50460701_44_dialog_content = "(Mamá no quiere Hati ya no...)",
  ui_story_5046_50460701_45_dialog_content = "(Porque Hati no la escuché...)",
  ui_story_5046_50460701_46_dialog_content = "Yo... Ugh... Mamá... ¡Aghhh!",
  ui_story_5046_50460701_47_dialog_content = "¡Despierta, Hati!",
  ui_story_5046_50460701_48_dialog_content = "(Parece estar atrapada en su memoria).",
  ui_story_5046_50460701_49_dialog_content = "(Puedo sentir su demonio interior susurrando implacablemente en su oído...)",
  ui_story_5046_50460701_50_dialog_content = "Si Hati no puede enfrentarse a su demonio interior de frente, permanecerá atrapada en sus recuerdos para siempre...",
  ui_story_5046_50460701_51_dialog_content = "Dejarla a la deriva inconscientemente en el pasado de esta manera no es una opción.",
  ui_story_5046_50460701_52_dialog_content = "¡Tengo que ayudarla!",
  ui_story_5046_50460701_53_option_content = "¡Potencia de fuerza!",
  ui_story_5046_50460701_54_dialog_content = "(Esta debe ser la casa de Hati.)",
  ui_story_5046_50460701_55_dialog_content = "Hati! ¿¡Qué estás haciendo!?",
  ui_story_5046_50460701_56_dialog_content = "¿M-mamá?",
  ui_story_5046_50460701_57_dialog_content = "Respóndeme, ¿¡qué estás haciendo!?",
  ui_story_5046_50460701_58_dialog_content = "Solo quería ver a qué juegan los niños afuera.",
  ui_story_5046_50460701_59_dialog_content = "¡Cerrar la ventana! ¡Ahora mismo!",
  ui_story_5046_50460701_60_dialog_content = "Pero yo también quiero salir y jugar.",
  ui_story_5046_50460701_61_dialog_content = "¿Cuántas veces te lo he dicho? ¿Necesitas que te lo repita?",
  ui_story_5046_50460701_62_dialog_content = "Sollozo...",
  ui_story_5046_50460701_63_dialog_content = "¿¡Por qué no me dejas salir a jugar!?",
  ui_story_5046_50460701_64_dialog_content = "¡Siempre dices que es por mi propia protección!",
  ui_story_5046_50460701_65_dialog_content = "¡Pero nunca me dices por qué es eso!",
  ui_story_5046_50460701_66_dialog_content = "...",
  ui_story_5046_50460701_67_dialog_content = "¡Este nuevo lugar al que nos hemos mudado está tan deteriorado y frío! ¡Es horrible aquí!",
  ui_story_5046_50460701_68_dialog_content = "¿No tienes esos libros ilustrados? Ve y lee solo.",
  ui_story_5046_50460701_69_dialog_content = "¡Pero ya he leído todos esos libros tantas veces!",
  ui_story_5046_50460701_70_dialog_content = "Los niños de esos libros pueden jugar juntos y visitarse...",
  ui_story_5046_50460701_71_dialog_content = "Usaste esos libros ilustrados para enseñarme cómo hablar con la gente, comprar cosas y decir gracias...",
  ui_story_5046_50460701_72_dialog_content = "...",
  ui_story_5046_50460701_73_dialog_content = "¡Pero no he tenido la oportunidad de usar nada de eso!",
  ui_story_5046_50460701_74_dialog_content = "¡Porque no me dejas salir!",
  ui_story_5046_50460701_75_dialog_content = "Te enseñé todas estas cosas porque...",
  ui_story_5046_50460701_76_dialog_content = "Espero que puedas cuidar de ti mismo algún día, cuando ya no esté cerca.",
  ui_story_5046_50460701_77_dialog_content = "¿Por qué ya no estarías cerca?",
  ui_story_5046_50460701_78_dialog_content = "...",
  ui_story_5046_50460701_79_dialog_content = "¿Por qué te ves tan triste, mamá?",
  ui_story_5046_50460701_80_dialog_content = "¿Alguien fue malo contigo?",
  ui_story_5046_50460701_81_dialog_content = "¡Ya estoy grande!",
  ui_story_5046_50460701_82_dialog_content = "¡Si alguien te está acosando, los golpearé a todos hasta que se escapen!",
  ui_story_5046_50460701_83_dialog_content = "¡Y si no puedo golpearlos a todos, los quemaré!",
  ui_story_5046_50460701_84_dialog_content = "!!!",
  ui_story_5046_50460701_85_dialog_content = "<color=#e8d9bb>¡Bofetada!</color>",
  ui_story_5046_50460701_86_dialog_content = "M... ¿Mamá?",
  ui_story_5046_50460701_87_dialog_content = "¿¡No te dije que no puedes hacer eso!?",
  ui_story_5046_50460701_88_dialog_content = "Mamá... me pegaste...",
  ui_story_5046_50460701_89_dialog_content = "¡Dime! ¿¡Por qué no puedo!?",
  ui_story_5046_50460701_90_dialog_content = "¡¿Por qué, por qué, por qué?!",
  ui_story_5046_50460701_91_dialog_content = "(Dime... ¿Por qué no puedo...)",
  ui_story_5046_50460701_92_dialog_content = "<color=#e8d9bb>Whoosh</color>",
  ui_story_5046_50460701_93_dialog_content = "¡¿?!",
  ui_story_5046_50460701_94_dialog_content = "¡Wow!",
  ui_story_5046_50460701_95_dialog_content = "Hati, tú...!",
  ui_story_5046_50460701_96_dialog_content = "¿M-mamá? Mi cuerpo... está en llamas...",
  ui_story_5046_50460701_97_dialog_content = "Mamá tiene un colgante como el mío.",
  ui_story_5046_50460701_98_dialog_content = "¿Para qué es este colgante?",
  ui_story_5046_50460701_99_dialog_content = "Este colgante es muy importante.",
  ui_story_5046_50460701_100_dialog_content = "Así que cuídalo bien.",
  ui_story_5046_50460701_101_dialog_content = "¡Oh!",
  ui_story_5046_50460701_102_dialog_content = "Pero, ¿por qué es tan importante este colgante?",
  ui_story_5046_50460701_103_dialog_content = "... El colgante... importante...",
  ui_story_5046_50460701_104_dialog_content = "... colgante... en...",
  ui_story_5046_50460701_105_dialog_content = "(Esta parte de su memoria es tan vaga...)",
  ui_story_5046_50460701_106_dialog_content = "¿Mama que estas haciendo? Pareces estresado.",
  ui_story_5046_50460701_107_dialog_content = "¡Hoy es mi cumpleaños! ¡Quiero comer pastel de fresas!",
  ui_story_5046_50460701_108_dialog_content = "... Hati... Escúchame.",
  ui_story_5046_50460701_109_dialog_content = "Es demasiado tarde... Es demasiado tarde para hablar así. No hay tiempo.",
  ui_story_5046_50460701_110_dialog_content = "¡Toma este colgante, mantenlo cerca y nunca lo pierdas!",
  ui_story_5046_50460701_111_dialog_content = "Mamá, ¿qué estás diciendo? No entiendo.",
  ui_story_5046_50460701_112_dialog_content = "Una mala persona... Una muy mala persona viene por ti.",
  ui_story_5046_50460701_113_dialog_content = "¿Una mala persona? ¿OMS?",
  ui_story_5046_50460701_114_dialog_content = "Mamá, ¿quién es esta mala persona?",
  ui_story_5046_50460701_115_dialog_content = "Mamá, ¿qué vas a hacer? ¿Mamá?",
  ui_story_5046_50460701_116_dialog_content = "¡Ah—!",
  ui_story_5046_50460701_117_dialog_content = "<color=#e8d9bb>\"Mamá, ¿quién es esta mala persona?\"</color>",
  ui_story_5046_50460701_118_dialog_content = "<color=#e8d9bb>\"¿Por qué la persona mala vino y nos hizo esto...?\"</color>",
  ui_story_5046_50460701_119_dialog_content = "<color=#e8d9bb>\"¿Mamá piensa... que soy una mala persona?\"</color>",
  ui_story_5046_50460701_120_dialog_content = "<color=#e8d9bb>\"¿Es por eso que me prendió fuego...?\"</color>",
  ui_story_5046_50460701_121_dialog_content = "<color=#e8d9bb>\"¿Tengo razón, mamá?\"</color>",
  ui_story_5046_50460701_122_dialog_content = "(Por fin entiendo... Hati...)",
  ui_story_5046_50460701_123_dialog_content = "(La mala persona de la que mamá estaba hablando... eres tú...)",
  ui_story_5046_50460701_124_dialog_content = "(Odio este poder... Este poder... nos traga enteros...)",
  ui_story_5046_50460701_125_dialog_content = "A nosotros...?",
  ui_story_5046_50460701_126_dialog_content = "Hati! Hati!",
  ui_story_5046_50460701_127_dialog_content = "Quién es ese...?",
  ui_story_5046_50460701_128_dialog_content = "¡Soy yo! PlayerName!",
  ui_story_5046_50460701_129_dialog_content = "PlayerName? ¿Quieres... abandonarme también?",
  ui_story_5046_50460701_130_dialog_content = "(PlayerName... Tu amada PlayerName...)",
  ui_story_5046_50460701_131_dialog_content = "(Él también te dejará atrás...)",
  ui_story_5046_50460701_132_dialog_content = "(¿A quién le gustaría alguien que siempre prende fuego a todo...? Alguien que no puede controlar sus propias llamas...)",
  ui_story_5046_50460701_133_dialog_content = "(Alguien que siempre hizo enojar a su madre... Hasta que finalmente la abandonó... Hati...)",
  ui_story_5046_50460701_134_dialog_content = "Mamá no me quiere... nadie lo hará...",
  ui_story_5046_50460701_135_dialog_content = "¡No es así!",
  ui_story_5046_50460701_136_dialog_content = "¡Cada vez que usas tu poder, es para personas importantes para ti!",
  ui_story_5046_50460701_137_dialog_content = "Para evitar que los Eclipsites lastimen a tu madre... Secar tu edredón tú mismo, para que tu madre pueda descansar más...",
  ui_story_5046_50460701_138_dialog_content = "Salvándome de una horda de Eclipsites cuando estaba indefenso para luchar contra ellos...",
  ui_story_5046_50460701_139_dialog_content = "Usando tu poder prohibido por el bien de aquellos que te importan...",
  ui_story_5046_50460701_140_dialog_content = "no puedes ver, Hati? ¡Eres una chica muy amable y considerada!",
  ui_story_5046_50460701_141_dialog_content = "¡Eso es lo que me gusta de ti!",
  ui_story_5046_50460701_142_dialog_content = "¡Y sé que tu madre debe sentir lo mismo!",
  ui_story_5046_50460701_143_dialog_content = "¿Cómo podría tu madre no amar a un niño tan amable y compasivo como tú?",
  ui_story_5046_50460701_144_dialog_content = "Mamá... ¿me ama?",
  ui_story_5046_50460701_145_dialog_content = "(Te está mintiendo...)",
  ui_story_5046_50460701_146_dialog_content = "¡Todo lo que dije es verdad!",
  ui_story_5046_50460701_147_dialog_content = "¡Tú eres el mentiroso! Todo lo que has hecho es desgarrar Hati ¡abajo! ¡Eres la mala persona!",
  ui_story_5046_50460701_148_dialog_content = "Hati, ¡vamos a vencer a esta mala persona juntos!",
  ui_story_5046_50460702_1_dialog_content = "¿Gané?",
  ui_story_5046_50460702_2_dialog_content = "(Ganaste...?)",
  ui_story_5046_50460702_3_dialog_content = "(No... todavía estás aquí... yo todavía estoy aquí...)",
  ui_story_5046_50460702_4_dialog_content = "(Todavía no puedes... realmente... aceptarte a ti mismo...)",
  ui_story_5046_50460702_5_dialog_content = "¿Qué vas a?",
  ui_story_5046_50460702_6_dialog_content = "(Nos reuniremos de nuevo...)",
  ui_story_5046_50460702_7_dialog_content = "Hati!",
  ui_story_5046_50460702_8_dialog_content = "Urgh... uf...",
  ui_story_5046_50460702_9_dialog_content = "¿Mmm? PlayerName...?",
  ui_story_5046_50460702_10_dialog_content = "Genial, por fin despertaste.",
  ui_story_5046_50460702_11_dialog_content = "...",
  ui_story_5046_50460702_12_dialog_content = "Gracias. Me acabas de salvar de nuevo.",
  ui_story_5046_50460702_13_dialog_content = "No necesitas agradecerme. ¡Me salvaste de los eclipses ahora mismo!",
  ui_story_5046_50460702_14_dialog_content = "...",
  ui_story_5046_50460702_15_dialog_content = "Quiero recuperar mi colgante de ese hombre enmascarado porque pertenecía a mi mamá.",
  ui_story_5046_50460702_16_dialog_content = "Desde que era un niño, siempre fui diferente a los demás. Solo podía verlos desde la distancia a través de la ventana, y nunca me permitían salir.",
  ui_story_5046_50460702_17_dialog_content = "En mi mundo, solo estaba mi mamá.",
  ui_story_5046_50460702_18_dialog_content = "Ella jugaba conmigo, me enseñaba a leer, me leía cuentos... Mi mamá lo era todo para mí.",
  ui_story_5046_50460702_19_dialog_content = "La amaba tanto, pero mi mamá... Tal vez ella no me amaba tanto como yo la amaba a ella.",
  ui_story_5046_50460702_20_dialog_content = "Cómo puedes decir eso...?",
  ui_story_5046_50460702_21_dialog_content = "Desde que tengo memoria, siempre estábamos en movimiento y nunca permanecíamos en un lugar por mucho tiempo.",
  ui_story_5046_50460702_22_dialog_content = "Mi madre a menudo me miraba con un dejo de miedo en los ojos y nunca me dejaba salir.",
  ui_story_5046_50460702_23_dialog_content = "Nuestra última casa fue en la que nos quedamos más tiempo. También fue el lugar donde terminó mi infancia...",
  ui_story_5046_50460702_24_dialog_content = "Hati...",
  ui_story_5046_50460702_25_dialog_content = "Siempre trato de escapar, para no tener que recordar ese día. Pero, ¿cómo puedo olvidar?",
  ui_story_5046_50460702_26_dialog_content = "26 de agosto Ese día... era mi cumpleaños.",
  ui_story_5046_50460702_27_dialog_content = "¡¿?!",
  ui_story_5046_50460702_28_dialog_content = "Hati...",
  ui_story_5046_50460702_29_dialog_content = "Aunque mi madre podía ser estricta a veces, era muy buena conmigo.",
  ui_story_5046_50460702_30_dialog_content = "Ella siempre recordaba mi cumpleaños y preparaba todo con un día de anticipación. Incluso hizo un pastel de crema de fresa conmigo...",
  ui_story_5046_50460702_31_dialog_content = "Ese día, mamá se levantó temprano como siempre, pero parecía estar de un humor extraño.",
  ui_story_5046_50460702_32_dialog_content = "Simplemente me deseó un feliz cumpleaños y luego comenzó a ocuparse de la casa como si estuviera preparando algo.",
  ui_story_5046_50460702_33_dialog_content = "Seguí preguntando si podía comer el pastel, pero mi mamá no respondió.",
  ui_story_5046_50460702_34_dialog_content = "Luego me arrojó a la chimenea. Trató de quemarme viva.",
  ui_story_5046_50460702_35_dialog_content = "¿¡Por qué haría eso!?",
  ui_story_5046_50460702_36_dialog_content = "Realmente no puedo recordar lo que pasó después de que ella me arrojó al fuego. Cuando me desperté, estaba en el orfanato.",
  ui_story_5046_50460702_37_dialog_content = "Esa fue la primera vez que salí con tantos niños...",
  ui_story_5046_50460702_38_dialog_content = "Siempre había querido salir y jugar con otros niños, pero nunca imaginé que así sería.",
  ui_story_5046_50460702_39_dialog_content = "Aprendí a llevarme bien con los otros niños y adultos del orfanato, pero no eran muy amigables.",
  ui_story_5046_50460702_40_dialog_content = "Los niños siempre peleaban entre ellos y los adultos eran muy malos con nosotros.",
  ui_story_5046_50460702_41_dialog_content = "Fue horrible allí, y solo quería quejarme con mi mamá, pero no sabía dónde estaba.",
  ui_story_5046_50460702_42_dialog_content = "Fue entonces cuando me di cuenta... que ella me había abandonado.",
  ui_story_5046_50460702_43_dialog_content = "Una noche, la gente del orfanato trató de hacerme algo mientras dormía. Traté de liberarme con todas mis fuerzas y alguien me cortó la oreja.",
  ui_story_5046_50460702_44_dialog_content = "Un trozo de mi oreja se desprendió, así como así. Nunca antes había sentido tanto dolor.",
  ui_story_5046_50460702_45_dialog_content = "No pude controlar mis emociones, dejé salir mi rabia y quemé todo el orfanato.",
  ui_story_5046_50460702_46_dialog_content = "Como sabes, me enviaron al Señor de las Sombras después de esto y me dejó ir hace solo dos meses.",
  ui_story_5046_50460702_47_dialog_content = "Hati...",
  ui_story_5046_50460702_48_dialog_content = "No existe tal cosa como una madre que no ama a su hijo.",
  ui_story_5046_50460702_49_dialog_content = "Estoy seguro de que ella quiere que vivas una buena vida, sin importar lo que se cruce en tu camino.",
  ui_story_5046_50460702_50_dialog_content = "No necesitas tratar de hacerme sentir mejor, PlayerName.",
  ui_story_5046_50460702_51_dialog_content = "Si mi mamá me amaba, ¿por qué me habría arrojado a esa chimenea?",
  ui_story_5046_50460702_52_dialog_content = "Sé que eso no es lo que realmente piensas en el fondo de tu corazón, ¿verdad? Hati?",
  ui_story_5046_50460702_53_dialog_content = "De lo contrario, ¿por qué te esforzarías tanto por encontrar ese recuerdo perdido?",
  ui_story_5046_50460702_54_dialog_content = "Debes creer que tu mamá todavía te ama, en algún lugar de tu corazón.",
  ui_story_5046_50460702_55_dialog_content = "...",
  ui_story_5046_50460702_56_dialog_content = "... Humm.",
  ui_story_5046_50460702_57_dialog_content = "Cuando perdí el control de mí mismo hace un momento, ¿por qué no te fuiste con los demás en medio de todo el caos?",
  ui_story_5046_50460702_58_dialog_content = "Porque... pensé que podrías necesitar mi ayuda.",
  ui_story_5046_50460702_59_dialog_content = "Aparte de Grimme, nadie se esforzaría tanto por ayudarme.",
  ui_story_5046_50460702_60_dialog_content = "Es justo que los amigos se apoyen mutuamente.",
  ui_story_5046_50460702_61_dialog_content = "¿Amigos? no tengo amigos",
  ui_story_5046_50460702_62_dialog_content = "A partir de ahora, puedes llamarme tu amigo.",
  ui_story_5046_50460702_63_dialog_content = "Has estado buscando tus recuerdos durante los dos meses completos desde que dejaste al Señor de las Sombras.",
  ui_story_5046_50460702_64_dialog_content = "Pero todavía hay un mundo enorme ahí afuera, esperando que lo explores.",
  ui_story_5046_50460702_65_dialog_content = "Cuando recuperes la memoria, ¡te invitamos a pasar el rato conmigo en el Coloso!",
  ui_story_5046_50460702_66_dialog_content = "¡Podemos viajar por todo el mundo y recuperar el tiempo que no se te permitía salir en el pasado!",
  ui_story_5046_50460702_67_dialog_content = "...",
  ui_story_5046_50460702_68_dialog_content = "¿Así que, qué piensas?",
  ui_story_5046_50460702_69_dialog_content = "...",
  ui_story_5046_50460702_70_dialog_content = "Seguro.",
  ui_story_5046_50460801_1_dialog_content = "(Las últimas palabras del Sr. Hamell y el único sobreviviente que mencionó, todo está relacionado con el orfanato).",
  ui_story_5046_50460801_2_dialog_content = "(No hay otras pistas disponibles en este momento. Los sospechosos Hati y PlayerName también han huido.)",
  ui_story_5046_50460801_3_dialog_content = "(Tal como están las cosas, mi única opción es seguir buscando en el orfanato).",
  ui_story_5046_50460801_4_dialog_content = "(Casi no quedan rastros del pasado después de la reconstrucción del orfanato. Ahora, solo los niños restantes de ese año aún no han sido investigados).",
  ui_story_5046_50460801_5_dialog_content = "¿Eres un juez? ¿Estás seguro de que tienes a la persona adecuada? solo soy un sirviente...",
  ui_story_5046_50460801_6_dialog_content = "(Solo había dos personas de las que pude encontrar registros en los archivos. Parece que esta chica es dos años mayor que Hati.)",
  ui_story_5046_50460801_7_dialog_content = "(Después del incendio, la enviaron a vivir con una familia adoptiva cercana. Ahora, es sirvienta de una familia noble en Lumopolis).",
  ui_story_5046_50460801_8_dialog_content = "Por favor, no hay necesidad de estar nervioso. Solo quiero saber sobre el incendio en el orfanato de Umbraton.",
  ui_story_5046_50460801_9_dialog_content = "Hasta donde yo sé, te quedaste allí durante bastante tiempo.",
  ui_story_5046_50460801_10_dialog_content = "Me hicieron todas estas preguntas tantas veces antes... ¿Por qué está pasando esto de nuevo?",
  ui_story_5046_50460801_11_dialog_content = "Estaba profundamente dormido esa noche... hasta que me despertaron los gritos de los otros niños. Cuando me desperté, todo el lugar ya estaba envuelto en llamas.",
  ui_story_5046_50460801_12_dialog_content = "Esa chica nueva, la demi-humana, todo su cuerpo estaba en llamas. El chico en la cama a mi lado dijo que ella fue quien empezó todo.",
  ui_story_5046_50460801_13_dialog_content = "Me apresuré a salir de allí, realmente no podía prestar atención a mucho más.",
  ui_story_5046_50460801_14_dialog_content = "(Hmm... Es exactamente lo mismo que su declaración anterior. Toda esta es información conocida).",
  ui_story_5046_50460801_15_dialog_content = "¿Te diste cuenta en ese momento si este demi-humano llamado Hati había estado discutiendo con alguien en el orfanato?",
  ui_story_5046_50460801_16_dialog_content = "¿O tenía algún agravio hacia los maestros, administradores u otras personas en el orfanato?",
  ui_story_5046_50460801_17_dialog_content = "No estoy seguro, no había escuchado nada.",
  ui_story_5046_50460801_18_dialog_content = "¿Pero venganza...? ¿Qué edad tenía ella en ese entonces? Ni siquiera es tan vieja como yo.",
  ui_story_5046_50460801_19_dialog_content = "Y ella solo había estado en el orfanato durante un mes. ¿A quién podría haber hecho enemigos en tan poco tiempo?",
  ui_story_5046_50460801_20_dialog_content = "Si realmente crees que podría ser posible, algunos niños eran más grandes que el resto y les gustaba hacer todo lo posible para intimidar a las personas para que hicieran lo que querían.",
  ui_story_5046_50460801_21_dialog_content = "Esa chica demi-humana era demasiado pequeña para luchar contra esos niños grandes...",
  ui_story_5046_50460801_22_dialog_content = "Y a los profesores allí no les importaba ninguna de las disputas entre los niños, no eran ni pacientes ni amables...",
  ui_story_5046_50460801_23_dialog_content = "No creo que a ninguno de nosotros le haya gustado el personal allí.",
  ui_story_5046_50460801_24_dialog_content = "Por cierto, hay una cosa más que quiero preguntar.",
  ui_story_5046_50460801_25_dialog_content = "¿Se ha mantenido en contacto con alguno de los niños que fueron adoptados del orfanato?",
  ui_story_5046_50460801_26_dialog_content = "La tasa de adopción en el orfanato fue muy alta, pero no hay registros de los adoptados ni pruebas de revisitas...",
  ui_story_5046_50460801_27_dialog_content = "No me he mantenido en contacto con nadie.",
  ui_story_5046_50460801_28_dialog_content = "En ese entonces, solíamos bromear que cuando venían a llevarse a ocho o nueve niños cada mes, se los estaban dando de comer a los Eclipsites.",
  ui_story_5046_50460801_29_dialog_content = "Cada mes se adoptaban ocho o nueve niños...",
  ui_story_5046_50460801_30_dialog_content = "(Esta es de hecho una situación anormal...)",
  ui_story_5046_50460801_31_dialog_content = "Lo siento por tomar su tiempo. Muchas gracias.",
  ui_story_5046_50460801_32_dialog_content = "(El próximo superviviente es un niño de la misma edad que Hati.)",
  ui_story_5046_50460801_33_dialog_content = "(Según los registros, administró la panadería con sus padres adoptivos después de ser adoptado).",
  ui_story_5046_50460801_34_dialog_content = "¿Eres un juez? ¡Yo no hice nada!",
  ui_story_5046_50460801_35_dialog_content = "Por favor, no hay necesidad de estar tan nervioso. Quiero entender qué pasó con respecto al incendio en el orfanato de Umbraton.",
  ui_story_5046_50460801_36_dialog_content = "¿Eh? Todo eso sucedió hace mucho tiempo, pero todavía lo estás investigando, ¿eh?",
  ui_story_5046_50460801_37_dialog_content = "Pero me temo que no tienes suerte, no puedo decirte nada nuevo. Todo lo que pude recordar ya ha sido anotado en mi declaración.",
  ui_story_5046_50460801_38_dialog_content = "Si es posible, espero que se abstenga de asustar a mis clientes.",
  ui_story_5046_50460801_39_dialog_content = "Oh...",
  ui_story_5046_50460801_40_dialog_content = "Si puedes ayudarme recordando más de lo que pasó, te compraré todo el pan de tu panadería.",
  ui_story_5046_50460801_41_dialog_content = "En serio!?",
  ui_story_5046_50460801_42_dialog_content = "Bueno, ahora que lo mencionas, tal vez pueda recordar algunos detalles más.",
  ui_story_5046_50460801_43_dialog_content = "Gracias por su cooperación. dijiste eso Hati enciende el fuego. ¿Puedes describir lo que pasó con más detalle?",
  ui_story_5046_50460801_44_dialog_content = "Esa noche... Siempre he tenido el sueño muy ligero desde que era pequeño, así que me desperté tan pronto como escuché que el demi-humano comenzaba a gritar.",
  ui_story_5046_50460801_45_dialog_content = "Mi cama estaba bastante lejos de la de ella. No vi lo que había pasado, pero ella comenzó a enfadarse después de los gritos.",
  ui_story_5046_50460801_46_dialog_content = "Luego, las llamas de todo su cuerpo incendiaron la cortina. El fuego comenzó a hacerse más y más grande, y los otros niños finalmente se despertaron.",
  ui_story_5046_50460801_47_dialog_content = "Corrí hacia él, junto con todos los demás niños, pero mi pierna estaba quemada. Ya dije todo esto antes cuando me preguntaron la primera vez.",
  ui_story_5046_50460801_48_dialog_content = "Entonces, ¿sabes si Hati, el demi-humano, había hecho enemigos en el orfanato?",
  ui_story_5046_50460801_49_dialog_content = "Todas las víctimas de los recientes ataques incendiarios han estado relacionadas con el orfanato. Quiero saber si guardan rencor contra Hati.",
  ui_story_5046_50460801_50_dialog_content = "Siempre aparecían niños nuevos en el orfanato, pero la mayoría terminaban siendo expulsados antes de que pudieran conocer realmente a alguien.",
  ui_story_5046_50460801_51_dialog_content = "Si no fuera por el hecho de que es una semihumana, ni siquiera habría recordado quién era, y mucho menos con quién no se llevaba bien.",
  ui_story_5046_50460801_52_dialog_content = "En cuanto a las personas que dirigían el orfanato...",
  ui_story_5046_50460801_53_dialog_content = "Tenían que lidiar con un gran grupo de mocosos ruidosos todos los días, y ninguno de ellos era suyo.",
  ui_story_5046_50460801_54_dialog_content = "Incluso si parecían lo suficientemente amigables en la superficie, ¿quién sabía cómo eran realmente a puerta cerrada?",
  ui_story_5046_50460801_55_dialog_content = "(Parece que todos tienen una mala impresión del personal del orfanato...)",
  ui_story_5046_50460801_56_dialog_content = "¿Ha tenido algún contacto con alguno de los otros niños adoptados del orfanato?",
  ui_story_5046_50460801_57_dialog_content = "¿O tienes los datos de contacto de alguna de las familias adoptivas?",
  ui_story_5046_50460801_58_dialog_content = "Perdí contacto con todos después de que fueron adoptados.",
  ui_story_5046_50460801_59_dialog_content = "En cuanto a los datos de contacto de las familias adoptivas...",
  ui_story_5046_50460801_60_dialog_content = "¿No es algo de lo que el director debería haber tomado nota?",
  ui_story_5046_50460801_61_dialog_content = "Sabes, solía ver a los maestros del orfanato mirando a ciertos niños, escribiendo y dibujando en sus cuadernos.",
  ui_story_5046_50460801_62_dialog_content = "Y cuando llegó el momento de la adopción, esos fueron los niños que fueron expulsados.",
  ui_story_5046_50460801_63_dialog_content = "Ahora que lo pienso, esos cuadernos deberían contener mucha información sobre los niños adoptados, ¿no? No sé, eres un juez, deberías tener la autoridad para ir a verlos, ¿verdad?",
  ui_story_5046_50460801_64_dialog_content = "Desafortunadamente, parece que todo fue destruido en el incendio.",
  ui_story_5046_50460801_65_dialog_content = "De todos modos, gracias por su cooperación. Tomaré todo el pan que tengas.",
  ui_story_5046_50460801_66_dialog_content = "(Uf, me las arreglé para lidiar con esa ridículamente enorme cantidad de pan. Pero ahora...)",
  ui_story_5046_50460801_67_dialog_content = "(Todavía está el asunto de esos niños adoptados que desaparecieron, y Hati, quien fue acusada de ser una asesina cuando era solo una niña.)",
  ui_story_5046_50460801_68_dialog_content = "(¿Qué clase de orfanato logra tener tantos niños adoptados cada mes, y luego todos desaparecen sin dejar rastro?)",
  ui_story_5046_50460801_69_dialog_content = "(El peor de los casos es que los usaron para algo...)",
  ui_story_5046_50460801_70_dialog_content = "(Es un pensamiento horrible... pero si es verdad, Hati tenía una causa justa para iniciar el fuego y matar al Sr. Hamell.)",
  ui_story_5046_50460801_71_dialog_content = "(Solo pensar en eso me hace estremecer. ¿Cuántos secretos se esconden en ese viejo orfanato?)",
  ui_story_5046_50460801_72_dialog_content = "Oh...",
  ui_story_5046_50460801_73_dialog_content = "Cuide sus pasos, señorita.",
  ui_story_5046_50460801_74_dialog_content = "Gracias...",
  ui_story_5046_50460801_75_dialog_content = "Grimme es el nombre. Soy el dueño del Firefly Bar, a la vuelta de la esquina.",
  ui_story_5046_50460801_76_dialog_content = "Grimme? ¿No eres amigo de Hati? El Sr. Zenas lo mencionó.",
  ui_story_5046_50460801_77_dialog_content = "Oh, ¿así que has oído hablar de mí? Escucha, ¿te importa si dejamos la pequeña charla para más tarde? De hecho, hay algo con lo que me preguntaba si podrías ayudarme.",
  ui_story_5046_50460801_78_dialog_content = "Qué es...?",
  ui_story_5046_50460801_79_dialog_content = "Graaahh—!",
  ui_story_5046_50460801_80_dialog_content = "!!!",
  ui_story_5046_50460801_81_dialog_content = "Acabo de terminar de lidiar con algunas cosas sucias en los suburbios.",
  ui_story_5046_50460801_82_dialog_content = "¿¡Eclipsitos!? ¡Mira detrás de ti!",
  ui_story_5046_50460802_1_dialog_content = "Gracias señorita. Si no estuvieras aquí para ayudar ahora, esos Eclipsites me habrían hecho un trabajo rápido.",
  ui_story_5046_50460802_2_dialog_content = "No fue nada. Por cierto, quiero preguntarte algo sobre Hati.",
  ui_story_5046_50460802_3_dialog_content = "Ciertamente. El Firefly Bar está en la esquina más adelante. Sentémonos y charlemos mientras tomamos una copa.",
  ui_story_5046_50460802_4_dialog_content = "<color=#e8d9bb>Timbre-!</color>",
  ui_story_5046_50460802_5_dialog_content = "Lo siento por los inconvenientes ocasionados.",
  ui_story_5046_50460802_6_dialog_content = "Me acaba de impresionar mucho, señorita. Esto es lo menos que puedo hacer.",
  ui_story_5046_50460802_7_dialog_content = "Por favor tome asiento. Todavía no es horario comercial. ¿Quieres algo de beber?",
  ui_story_5046_50460802_8_dialog_content = "Estoy de servicio y no bebo.",
  ui_story_5046_50460802_9_dialog_content = "Dejando a un lado el alcohol, aquí también tenemos una variedad de refrescos muy agradables.",
  ui_story_5046_50460802_10_dialog_content = "Hay Blue Storm, Umbraton Delight, White Night Iced Tea...",
  ui_story_5046_50460802_11_dialog_content = "No gracias. Vayamos directo al grano.",
  ui_story_5046_50460802_12_dialog_content = "como tu y Hati ¿encontrarse?",
  ui_story_5046_50460802_13_dialog_content = "Bueno, ella trabaja aquí conmigo, ¿no?",
  ui_story_5046_50460802_14_dialog_content = "Por lo general, se encarga de traer los ingredientes, limpiar la cocina... muchos trabajos diferentes, en realidad. No habla mucho, pero es una gran trabajadora.",
  ui_story_5046_50460802_15_dialog_content = "Donde estaba Hati cuando ocurrieron los incendios recientes?",
  ui_story_5046_50460802_16_dialog_content = "Ahora bien, esos no eran tan recientes en absoluto, no puedo recordar correctamente.",
  ui_story_5046_50460802_17_dialog_content = "Sin embargo, recuerdo este día muy claramente. Era el día de la compra.",
  ui_story_5046_50460802_18_dialog_content = "Hati estuvo ocupado todo el día en la cocina, contando el stock y comprobando la frescura de los ingredientes. No tuvo la oportunidad de descansar hasta la noche.",
  ui_story_5046_50460802_19_dialog_content = "(Este fue el día en que Fairmont fue asesinado. Según el testimonio de Grimme, Hati no tuvo la oportunidad de cometer un asesinato.)",
  ui_story_5046_50460802_20_dialog_content = "(Sin embargo, Grimme puede estar tratando de proteger Hati.)",
  ui_story_5046_50460802_21_dialog_content = "Señorita, por favor, créame. Te estoy diciendo la verdad.",
  ui_story_5046_50460802_22_dialog_content = "Me puedes llamar Kristen.",
  ui_story_5046_50460802_23_dialog_content = "De regreso Hati—¿Tienes alguna otra información sobre ella que puedas compartir conmigo?",
  ui_story_5046_50460802_24_dialog_content = "Por ejemplo, ¿alguna vez ha mencionado que le guarda rencor a alguien? ¿Alguna vez ha mencionado venganza o algo similar?",
  ui_story_5046_50460802_25_dialog_content = "Como dije, Hati no habla mucho No nos conocemos desde hace mucho tiempo, pero no la he oído mencionar algo así en todo el tiempo que la conozco.",
  ui_story_5046_50460802_26_dialog_content = "(Esto no parece llevarme a ninguna parte).",
  ui_story_5046_50460802_27_dialog_content = "En ese caso, no te molestaré más. Buen día.",
  ui_story_5046_50460802_28_dialog_content = "¿Te vas a ir sin probar el jugo casero que hice solo para ti?",
  ui_story_5046_50460802_29_dialog_content = "No parecías interesado en ninguna de las bebidas que mencioné antes, así que preparé una bebida especial para ti hace un momento.",
  ui_story_5046_50460802_30_dialog_content = "Deberías saber que soy el mejor mixólogo de Umbraton.",
  ui_story_5046_50460802_31_dialog_content = "Eso no será necesario.",
  ui_story_5046_50460802_32_dialog_content = "No seas así. Una bebida para una historia a caballo entre la verdad y la mentira: así es como se hacen las cosas en Umbraton.",
  ui_story_5046_50460802_33_dialog_content = "¿Qué tiene de malo intentarlo, eh?",
  ui_story_5046_50460802_34_dialog_content = "(Parece que Grimme está tratando de insinuar algo... ¿¡y por qué de repente está tan cerca de mí!?)",
  ui_story_5046_50460802_35_dialog_content = "Todavía tengo deberes oficiales que atender, y el culpable aún no ha sido atrapado. No puedo...",
  ui_story_5046_50460802_36_dialog_content = "Parecías tan triste cuando te vi en la calle. ¿El caso ha chocado contra una pared de ladrillos?",
  ui_story_5046_50460802_37_dialog_content = "En momentos como estos, deberíamos sentarnos a tomar una copa y escuchar un cuento o dos para relajarnos. Incluso puede encontrar alguna nueva inspiración.",
  ui_story_5046_50460802_38_dialog_content = "(Eso suena bien).",
  ui_story_5046_50460802_39_dialog_content = "(No hay otras pistas para continuar por el momento. Solo debería sentarme y escuchar).",
  ui_story_5046_50460802_40_dialog_content = "Bien, pero solo uno.",
  ui_story_5046_50460802_41_dialog_content = "Jeje, entonces voy a empezar la historia.",
  ui_story_5046_50460802_42_dialog_content = "Hace diez años, Umbraton no tenía un Señor de las Sombras, y nadie se inmutó ante las peleas y matanzas que ocurrían en las calles, y mucho menos en cierto orfanato en las afueras de la ciudad.",
  ui_story_5046_50460802_43_dialog_content = "Pero este orfanato en las afueras se las arregló para permanecer abierto al público...",
  ui_story_5046_50460802_44_dialog_content = "¿Cuál crees que fue la razón de eso?",
  ui_story_5046_50460802_45_dialog_content = "En esta sociedad turbulenta, el orfanato logró permanecer operativo... Supongo que fue gracias al apoyo de una persona caritativa.",
  ui_story_5046_50460802_46_dialog_content = "Eso es correcto. De hecho, el orfanato recibió apoyo, pero no hubo caridad.",
  ui_story_5046_50460802_47_dialog_content = "El orfanato tenía solo cinco empleados y un director, y no había ni el más mínimo rumor de que algún pez gordo de Umbraton mantuviera el lugar a flote.",
  ui_story_5046_50460802_48_dialog_content = "Y de vez en cuando, algunos niños eran adoptados, mientras que otros niños eran enviados al orfanato...",
  ui_story_5046_50460802_49_dialog_content = "Era como comprar y vender bebidas detrás de la barra.",
  ui_story_5046_50460802_50_dialog_content = "D-¿Quieres decir que este orfanato estaba ejecutando una operación de tráfico de niños?",
  ui_story_5046_50460802_51_dialog_content = "No te adelantes, esta historia aún no ha terminado.",
  ui_story_5046_50460802_52_dialog_content = "Dicen que los niños adoptados fueron enviados a ciertos nobles de Lumopolis, nobles cuyos linajes están casi extintos.",
  ui_story_5046_50460802_53_dialog_content = "Sin embargo, escuché que hace algún tiempo, un funcionario llamado Pittman comenzó a investigar a estos nobles de nuevo.",
  ui_story_5046_50460802_54_dialog_content = "<color=#FFB400>El caso</color> Pittman esta investigando!",
  ui_story_5046_50460802_55_dialog_content = "Cinco empleados y un director... ¡Eso coincide exactamente con la información que tengo sobre el antiguo orfanato!",
  ui_story_5046_50460802_56_dialog_content = "El director del antiguo orfanato murió en el incendio, y tres de los empleados han muerto en incendios ocurridos en los últimos dos meses...",
  ui_story_5046_50460802_57_dialog_content = "El Sr. Hamell también estaba relacionado con el antiguo orfanato, además de la persona que mencionó...",
  ui_story_5046_50460802_58_dialog_content = "¡Eso hace cinco!",
  ui_story_5046_50460802_59_dialog_content = "Combinado con las declaraciones previamente investigadas de los dos niños que sobrevivieron al incendio...",
  ui_story_5046_50460802_60_dialog_content = "El orfanato de esta historia es el viejo orfanato, ¿no es así?",
  ui_story_5046_50460802_61_dialog_content = "Bueno... solo estoy contando una historia, nada más.",
  ui_story_5046_50460802_62_dialog_content = "Si puedes inspirarte en él, bien por ti.",
  ui_story_5046_50460802_63_dialog_content = "He aprendido mucho de esta historia. Aprecio tu ayuda.",
  ui_story_5046_50460802_64_dialog_content = "Pero tengo curiosidad... ¿Dónde escuchaste esta historia?",
  ui_story_5046_50460802_65_dialog_content = "El caso Sr. Pittman investigado está relacionado con los nobles de Lumopolis.",
  ui_story_5046_50460802_66_dialog_content = "Quien te haya contado esta historia conoce tantos detalles precisos. No puede haber sido un ciudadano común.",
  ui_story_5046_50460802_67_dialog_content = "Las personas que cuentan historias aquí no siempre dejan sus nombres. Cuanto menos sé, más interesante es la historia.",
  ui_story_5046_50460802_68_dialog_content = "Las sombras conocen todos los secretos.",
  ui_story_5046_50460802_69_dialog_content = "(Grimme parece poco confiable pero habla con perfecta precisión).",
  ui_story_5046_50460802_70_dialog_content = "(Nuestro encuentro en las calles hoy no fue un accidente. Me trajeron aquí a propósito para escuchar todo esto).",
  ui_story_5046_50460802_71_dialog_content = "Todo lo que ocurre en el continente está conectado. Una mariposa en Umbraton puede provocar una tormenta en Lumopolis.",
  ui_story_5046_50460802_72_dialog_content = "¿Mmm?",
  ui_story_5046_50460802_73_dialog_content = "(¿Qué pasa con esa mirada y el dicho repentino?)",
  ui_story_5046_50460802_74_dialog_content = "Jeje... Muy bien, muy bien, se acabó la hora del cuento.",
  ui_story_5046_50460802_75_dialog_content = "Mira, la vista nocturna es increíble. Rara vez llegas a ver el cielo nocturno de Umbraton, ¿no es así?",
  ui_story_5046_50460802_76_dialog_content = "Por la noche, muchos pequeños vendedores aparecen en Umbraton, sus lámparas se extienden como un río de estrellas. Es una vista inolvidable.",
  ui_story_5046_50460802_77_dialog_content = "Gracias por tu historia. La bebida también era agradable.",
  ui_story_5046_50460802_78_dialog_content = "Jeje, este cóctel sin alcohol especial es en realidad algo que nunca había probado antes. Solo pensé en ir por este tipo de combinación después de verte.",
  ui_story_5046_50460802_79_dialog_content = "¿Esta bebida tiene nombre?",
  ui_story_5046_50460802_80_dialog_content = "Todavía no, pero lo llamaré—",
  ui_story_5046_50460802_81_dialog_content = "Lirio de Lumópolis.",
  ui_story_5046_50460901_1_dialog_content = "Hati, ¿recuerdas dónde vivías?",
  ui_story_5046_50460901_2_dialog_content = "Si quieres recuperar tus recuerdos del pasado, ve al lugar donde solías vivir y mira lo que puedes recordar.",
  ui_story_5046_50460901_3_dialog_content = "Mi mamá y yo nos mudamos de casa varias veces. No puedo recordar mi antigua dirección.",
  ui_story_5046_50460901_4_dialog_content = "Pero todavía recuerdo la casa que incendié. Estaba cerca de Umbraton.",
  ui_story_5046_50460901_5_dialog_content = "No lo quemaste. Definitivamente te has equivocado en esa parte.",
  ui_story_5046_50460901_6_dialog_content = "Vayamos allí y echemos un vistazo. Quizás recuerdes algo.",
  ui_story_5046_50460901_7_dialog_content = "Eso es todo.",
  ui_story_5046_50460901_8_dialog_content = "Todas las casas por las que pasamos en el camino estaban desiertas. Parece que nadie ha vivido aquí durante mucho tiempo.",
  ui_story_5046_50460901_9_dialog_content = "Esta es la única casa que ha sido quemada hasta los cimientos. Una mirada es todo lo que se necesita para ver eso.",
  ui_story_5046_50460901_10_option_content = "¿Por qué fue abandonado este lugar?",
  ui_story_5046_50460901_11_dialog_content = "No lo sé.",
  ui_story_5046_50460901_12_dialog_content = "Todo lo que recuerdo es que, cuando desperté después del incendio, ya estaba en el orfanato.",
  ui_story_5046_50460901_13_dialog_content = "En poco tiempo, el orfanato se quemó y me enviaron al Señor de las Sombras.",
  ui_story_5046_50460901_14_dialog_content = "Hoy es la primera vez que vuelvo aquí en tanto tiempo.",
  ui_story_5046_50460901_15_dialog_content = "Muéstrame tu casa.",
  ui_story_5046_50460901_16_option_content = "¿Por qué tú y tu madre se mudaban tan a menudo?",
  ui_story_5046_50460901_17_dialog_content = "Porque la gente mala nos perseguía todo el tiempo.",
  ui_story_5046_50460901_18_dialog_content = "Mi mamá me dijo una vez que mi papá era muy poderoso y que alguien quería llevárselo y hacer experimentos con él.",
  ui_story_5046_50460901_19_dialog_content = "Entonces, un día, una mala persona irrumpió en nuestra casa y trató de atrapar a mi papá. Después de eso, mi papá se quedó atrás para proteger a mi mamá.",
  ui_story_5046_50460901_20_dialog_content = "Mamá se escapó y me dio a luz.",
  ui_story_5046_50460901_21_dialog_content = "Recuerdo haberle preguntado a mi mamá por qué nunca pude ver a mi papá. Mamá me dijo que mi papá estaba en algún lugar lejano.",
  ui_story_5046_50460901_22_dialog_content = "Cuando crecí, mi mamá me dijo que una organización aterradora quería atrapar a mi papá para usarlo en sus experimentos.",
  ui_story_5046_50460901_23_dialog_content = "Esta organización no dejaba de perseguirnos, así que mi mamá siempre me arrastraba a lugares nuevos.",
  ui_story_5046_50460901_24_dialog_content = "Muéstrame tu casa.",
  ui_story_5046_50460901_25_option_content = "Muéstrame tu casa.",
  ui_story_5046_50460901_26_dialog_content = "Sé que ahora está todo quemado, pero aún debes recordar cómo era la vida allí.",
  ui_story_5046_50460901_27_dialog_content = "Puede que te entristezca, pero cualquier pequeño detalle podría desencadenar tus recuerdos perdidos.",
  ui_story_5046_50460901_28_dialog_content = "De hecho, tenía miedo de volver aquí... Miedo de recordar los pequeños fragmentos de mis recuerdos viviendo con mamá.",
  ui_story_5046_50460901_29_dialog_content = "También me da miedo recordar ese otro recuerdo perdido...",
  ui_story_5046_50460901_30_dialog_content = "Si descubro que mamá me arrojó a la chimenea porque temía mi poder...",
  ui_story_5046_50460901_31_dialog_content = "De ninguna manera. Tu madre debe haberlo hecho por alguna otra razón.",
  ui_story_5046_50460901_32_dialog_content = "El fuego no puede hacerte daño. Tu madre debe haber sabido esto.",
  ui_story_5046_50460901_33_dialog_content = "Tal vez estabas en peligro en ese momento y tu madre quería protegerte, así que te puso en la chimenea.",
  ui_story_5046_50460901_34_dialog_content = "Al igual que tu padre se quedó atrás para protegerla.",
  ui_story_5046_50460901_35_dialog_content = "...",
  ui_story_5046_50460901_36_dialog_content = "Vamos. Te mostraré dónde solía vivir.",
  ui_story_5046_50460901_37_dialog_content = "¡Está bien!",
  ui_story_5046_50460901_38_dialog_content = "Puedes ver la sala de estar desde aquí una vez que cruzas la puerta. Mi mamá solía traerme comida sabrosa y libros ilustrados.",
  ui_story_5046_50460901_39_dialog_content = "Aquí había una ventana, que siempre estaba cubierta por gruesas cortinas. La luz no podía atravesarlo y no podía ver afuera.",
  ui_story_5046_50460901_40_dialog_content = "Pero podía oír a los niños jugando allí.",
  ui_story_5046_50460901_41_dialog_content = "Recuerdo una vez que quise abrir la ventana para ver qué estaban jugando los niños, pero mi mamá me detuvo tan pronto como lo hice.",
  ui_story_5046_50460901_42_dialog_content = "\"¡Cierra la ventana! ¡Ahora mismo!\"",
  ui_story_5046_50460901_43_dialog_content = "La habitación debe haber estado siempre a oscuras si la luz no podía entrar.",
  ui_story_5046_50460901_44_dialog_content = "Mamá encendió muchas velas en la casa. Eso es lo que usamos para la luz.",
  ui_story_5046_50460901_45_dialog_content = "Que extraño...",
  ui_story_5046_50460901_46_dialog_content = "Nací con llama poderosa Lumina. Mamá dijo que lo heredé de mi papá.",
  ui_story_5046_50460901_47_dialog_content = "Cuando era pequeño, a menudo prendía fuego por accidente a edredones y libros ilustrados, y mi mamá también me dijo que no podía usar mis llamas.",
  ui_story_5046_50460901_48_dialog_content = "Supongo que mi mamá tenía miedo de mi poder, así que no me dejaba salir a jugar con otros niños... y luego me tiró a la chimenea.",
  ui_story_5046_50460901_49_dialog_content = "(La madre de Hati no la dejaba salir y selló la casa de forma segura para que la gente no pudiera ver el interior...)",
  ui_story_5046_50460901_50_dialog_content = "(Además, la gente los estaba persiguiendo. Tal vez la madre de Hati estaba tratando de ocultar algo del mundo exterior).",
  ui_story_5046_50460901_51_dialog_content = "Mira, esta es la chimenea.",
  ui_story_5046_50460901_52_dialog_content = "...",
  ui_story_5046_50460901_53_dialog_content = "PlayerName, yo... quiero ir a la chimenea.",
  ui_story_5046_50460901_54_dialog_content = "¿Ah?",
  ui_story_5046_50460901_55_dialog_content = "De la misma manera que me hiciste recordar mi vida en esta casa, quiero recordar cómo fue ser arrojado allí.",
  ui_story_5046_50460901_56_dialog_content = "Tal vez recordaré algo.",
  ui_story_5046_50460901_57_dialog_content = "Parece una idea razonable...",
  ui_story_5046_50460901_58_dialog_content = "¡Está bien!",
  ui_story_5046_50460901_59_dialog_content = "¡Si tienes algún problema allí, usaré mis habilidades psíquicas para entrar en tus recuerdos y ayudarte!",
  ui_story_5046_50460901_60_dialog_content = "Gracias... pero quiero intentar recordar por mí mismo.",
  ui_story_5046_50460901_61_dialog_content = "Está bien, ¡pero solo dime si necesitas ayuda!",
  ui_story_5046_50460901_62_dialog_content = "<color=#e8d9bb>Umbratón rural</color>",
  ui_story_5046_50460901_63_dialog_content = "El lugar Hati solía vivir está justo más adelante.",
  ui_story_5046_50460901_64_dialog_content = "La mansión de vacaciones de mi padre en Umbraton también está cerca.",
  ui_story_5046_50460901_65_dialog_content = "A la izquierda en esta intersección, y un poco más adelante, debería poder ver las puertas.",
  ui_story_5046_50460901_66_dialog_content = "La última vez que vine a esta mansión estaba de vacaciones con mis padres. El lugar donde me rescató el Sr. Zenas también está por aquí...",
  ui_story_5046_50460901_67_dialog_content = "Eso es... PlayerName!",
  ui_story_5046_50460901_68_dialog_content = "¿Recordaste algo?",
  ui_story_5046_50460901_69_dialog_content = "Aún no.",
  ui_story_5046_50460901_70_dialog_content = "¿Realmente puedo... no recordar?",
  ui_story_5046_50460901_71_dialog_content = "PlayerName! Hati!",
  ui_story_5046_50460901_72_dialog_content = "Kristen!?",
  ui_story_5046_50460901_73_dialog_content = "Hati, de acuerdo con la ley, está bajo arresto bajo sospecha de varios delitos graves, ¡incluidos homicidio intencional e incendio premeditado!",
  ui_story_5046_50460901_74_dialog_content = "¡E-Espera!",
  ui_story_5046_50460901_75_dialog_content = "¡Ella no hizo ninguna de esas cosas! ¿¡Por qué estás tratando de arrestarla!?",
  ui_story_5046_50460901_76_dialog_content = "¿Qué criminal estaría dispuesto a admitir su culpabilidad?",
  ui_story_5046_50460901_77_dialog_content = "B-Bueno, si quieres arrestar a alguien, ¿no necesitas pruebas?",
  ui_story_5046_50460901_78_dialog_content = "... ¿Evidencia?",
  ui_story_5046_50460901_79_dialog_content = "PlayerName, ¿tú también no lo viste? Hati mató a Hamell ante nuestros propios ojos.",
  ui_story_5046_50460901_80_dialog_content = "Kristen, créeme, Hati ¡No mató a Hamell!",
  ui_story_5046_50460901_81_dialog_content = "Alguien más debe haber matado a Hamell desde las sombras.",
  ui_story_5046_50460901_82_dialog_content = "En todo caso, Hati estaba allí cuando Hamell murió.",
  ui_story_5046_50460901_83_dialog_content = "Incluso si ella no lo mató, está obligada a cooperar con la investigación.",
  ui_story_5046_50460901_84_dialog_content = "Ven conmigo.",
  ui_story_5046_50460901_85_dialog_content = "Necesito encontrar mis recuerdos perdidos con mi mamá.",
  ui_story_5046_50460901_86_dialog_content = "Eso es todo lo que me importa ahora.",
  ui_story_5046_50460901_87_dialog_content = "Entonces, ¿te estás resistiendo al arresto?",
  ui_story_5046_50460901_88_dialog_content = "Llámalo como quieras.",
  ui_story_5046_50460901_89_dialog_content = "Parece que tendré que recurrir al uso de la fuerza.",
  ui_story_5046_50460901_90_dialog_content = "Kristen, puedes dejar Hati tratar de recuperar su memoria antes de que te la lleves?",
  ui_story_5046_50460901_91_dialog_content = "Hazte a un lado, PlayerName.",
  ui_story_5046_50460901_92_dialog_content = "Tendré que arrestarte como cómplice si vuelves a interponerte en mi camino hacia el sospechoso.",
  ui_story_5046_50460901_93_dialog_content = "Los recuerdos de mamá... son muy importantes.",
  ui_story_5046_50460901_94_dialog_content = "Puedo entender la importancia de estos recuerdos para Hati.",
  ui_story_5046_50460901_95_dialog_content = "Y le prometí que la ayudaría a encontrar estos recuerdos perdidos...",
  ui_story_5046_50460901_96_dialog_content = "Entonces, no... No hay forma de que vaya a ninguna parte.",
  ui_story_5046_50460901_97_dialog_content = "protegeré Hati hasta que encuentra sus recuerdos perdidos.",
  ui_story_5046_50460901_98_dialog_content = "deseas proteger Hati... ¡pero también deseo proteger al Capitán Zenas!",
  ui_story_5046_50460901_99_dialog_content = "Hati prendió fuego al orfanato y te tomó como rehén...",
  ui_story_5046_50460901_100_dialog_content = "¡Eres tú quien ensombrece el título de caballero del Sr. Zenas!",
  ui_story_5046_50460901_101_dialog_content = "Ha soportado tanto para encontrarte y Hati!",
  ui_story_5046_50460901_102_dialog_content = "Si te llevo de regreso y le explico todo al Señor de las Sombras y a todo Umbraton...",
  ui_story_5046_50460901_103_dialog_content = "¡Si solo hago esto, el Sr. Zenas estará bien!",
  ui_story_5046_50460901_104_dialog_content = "¡Lo diré una vez más!",
  ui_story_5046_50460901_105_dialog_content = "Hazte a un lado, PlayerName!",
  ui_story_5046_50460901_106_dialog_content = "¡No! ¡Nunca me haré a un lado!",
  ui_story_5046_50460901_107_dialog_content = "Hati... proteger... el colgante...",
  ui_story_5046_50460901_108_dialog_content = "Mamá... ¿Qué quería mi mamá que protegiera...?",
  ui_story_5046_50460901_109_dialog_content = "Dime, mamá...",
  ui_story_5046_50460901_110_dialog_content = "¿Qué pasó ese día? Me empujaste a la chimenea tan despiadadamente...",
  ui_story_5046_50460901_111_dialog_content = "¡Lo diré de nuevo, por última vez! Hazte a un lado, PlayerName!",
  ui_story_5046_50460901_112_dialog_content = "Dámelo... muere...",
  ui_story_5046_50460901_113_dialog_content = "¡Urgh! ¡Me duele la cabeza! ¡Es como si algo estuviera excavando en mi cerebro!",
  ui_story_5046_50460901_114_dialog_content = "Él está aquí.",
  ui_story_5046_50460901_115_dialog_content = "Este día... Por fin está aquí.",
  ui_story_5046_50460901_116_dialog_content = "¿Mamá?",
  ui_story_5046_50460901_117_dialog_content = "Hati, no importa lo que pase, si mamá está contigo o no, mamá siempre te amará.",
  ui_story_5046_50460901_118_dialog_content = "¿Por qué no estarías conmigo, mamá?",
  ui_story_5046_50460901_119_dialog_content = "No entiendo.",
  ui_story_5046_50460901_120_dialog_content = "Es demasiado tarde...",
  ui_story_5046_50460901_121_dialog_content = "Hati, asegúrese de proteger esta mitad del colgante.",
  ui_story_5046_50460901_122_dialog_content = "Este colgante simboliza cuánto te queremos tu papá y yo. Siempre te protegeremos, Hati.",
  ui_story_5046_50460901_123_dialog_content = "Vive una buena vida. Mamá te ama...",
  ui_story_5046_50460901_124_dialog_content = "¿¡Mamá!?",
  ui_story_5046_50460901_125_dialog_content = "¡Urgh!",
  ui_story_5046_50460901_126_dialog_content = "(¿¡Por qué mamá me empujó a la chimenea!?)",
  ui_story_5046_50460901_127_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5046_50460901_128_dialog_content = "(¿¡Hay alguien aquí!? ¿Quién es? ¡Nadie ha entrado en la casa antes!)",
  ui_story_5046_50460901_129_dialog_content = "No fue fácil localizarte, Catherine Kelp. ¿De verdad crees que puedes escapar?",
  ui_story_5046_50460901_130_dialog_content = "... Zenas.",
  ui_story_5046_50460901_131_dialog_content = "Tsk, esta casa es tan oscura. ¿Por qué no hay luz aquí?",
  ui_story_5046_50460901_132_dialog_content = "¿Una dama de lujo viviendo en una casa como esta? Parece que la vida no ha sido muy buena contigo últimamente.",
  ui_story_5046_50460901_133_dialog_content = "Por muy destartalada que esté la casa en la que vivo, mientras estés muerto, viviré muy bien.",
  ui_story_5046_50460901_134_dialog_content = "Shh, una buena dama nunca habla cosas tan sucias.",
  ui_story_5046_50460901_135_dialog_content = "Basta de tonterías.",
  ui_story_5046_50460901_136_dialog_content = "Debo matarte hoy... para vengar a Fenrir.",
  ui_story_5046_50460901_137_dialog_content = "(¿Fenrir? ¡Ese es el nombre de mi padre! ¿¡Este hombre mató a mi padre!?)",
  ui_story_5046_50460901_138_dialog_content = "Sobreestimas tu habilidad.",
  ui_story_5046_50460901_139_dialog_content = "Jadeo... jadeo...",
  ui_story_5046_50460901_140_dialog_content = "Catherine, dame el colgante y te perdonaré la vida.",
  ui_story_5046_50460901_141_dialog_content = "Sobre mi cadaver...",
  ui_story_5046_50460901_142_dialog_content = "Que terco. Si realmente deseas morir, te complaceré.",
  ui_story_5046_50460901_143_dialog_content = "(¡Mamá!)",
  ui_story_5046_50460901_144_dialog_content = "Hya-!",
  ui_story_5046_50460901_145_dialog_content = "(¿¡El fuego!? ¿Mamá fue quien lo inició?)",
  ui_story_5046_50460901_146_dialog_content = "¡Argh! ¿Cómo se propagó tan rápido este fuego?",
  ui_story_5046_50460901_147_dialog_content = "¿Ese era tu plan, Catherine?",
  ui_story_5046_50460901_148_dialog_content = "No saldrás de aquí con vida...",
  ui_story_5046_50460901_149_dialog_content = "¡Déjame ir! ¿¡Quieres que me queme hasta quedar crujiente aquí contigo!?",
  ui_story_5046_50460901_150_dialog_content = "Mientras vengue a Fenrir...",
  ui_story_5046_50460901_151_dialog_content = "Aaaaah!",
  ui_story_5046_50460901_152_dialog_content = "(¡Mamá! Mamá todavía me mira...)",
  ui_story_5046_50460901_153_dialog_content = "...",
  ui_story_5046_50460901_154_dialog_content = "(Mamá está diciendo... ¿no salgas?)",
  ui_story_5046_50460901_155_dialog_content = "(¿¡Mamá!? ¿¡Mamá no se mueve!?)",
  ui_story_5046_50460901_156_dialog_content = "(Mamá-!)",
  ui_story_5046_50460901_157_dialog_content = "Hmph, ni siquiera sudó.",
  ui_story_5046_50460901_158_dialog_content = "(Waaaah... Mamá...)",
  ui_story_5046_50460901_159_dialog_content = "(El hombre está buscando algo a mamá...)",
  ui_story_5046_50460901_160_dialog_content = "(¡Necesito salir y matarlo... para vengar a mi mamá!)",
  ui_story_5046_50460901_161_dialog_content = "(No, mamá me acaba de decir que no salga...)",
  ui_story_5046_50460901_162_dialog_content = "Hace tanto calor aquí... ¿¡Dónde escondió esa cosa!?",
  ui_story_5046_50460901_163_dialog_content = "...",
  ui_story_5046_50460901_164_dialog_content = "Finalmente lo encontré. Me pica la cara, ¿está quemada?",
  ui_story_5046_50460901_165_dialog_content = "¡Fuego! ¡Fuego!",
  ui_story_5046_50460901_166_dialog_content = "No puedo dejar que nadie me vea.",
  ui_story_5046_50460901_167_dialog_content = "(Se ha ido... Mamá ya no se mueve...)",
  ui_story_5046_50460901_168_dialog_content = "(Mamá...)",
  ui_story_5046_50460901_169_dialog_content = "Ese fuego estaba fuera de control, pero finalmente logramos apagarlo...",
  ui_story_5046_50460901_170_dialog_content = "Encontraron a Catherine, pero ya había dejado de respirar...",
  ui_story_5046_50460901_171_dialog_content = "Un fuego como ese te ahogará hasta la muerte, incluso si las llamas nunca te tocan...",
  ui_story_5046_50460901_172_dialog_content = "Si no tienes nada bueno que decir, simplemente no digas nada.",
  ui_story_5046_50460901_173_dialog_content = "Hmph.",
  ui_story_5046_50460901_174_dialog_content = "Ayuda a limpiar este lugar si no tienes nada que hacer.",
  ui_story_5046_50460901_175_dialog_content = "Lo sé, lo sé.",
  ui_story_5046_50460901_176_dialog_content = "¡Ven aquí! ¡Hay un niño en la chimenea!",
  ui_story_5046_50460901_177_dialog_content = "Nunca escuché a Catherine mencionar que tenía un hijo...",
  ui_story_5046_50460901_178_dialog_content = "Y el niño no está herido ni un poco, a pesar de esas llamas furiosas...",
  ui_story_5046_50460901_179_dialog_content = "Suspiro... Bloqueó las ventanas y encendió velas en la habitación durante el día.",
  ui_story_5046_50460901_180_dialog_content = "Era solo cuestión de tiempo antes de que esto sucediera. ¿Ver?",
  ui_story_5046_50460901_181_dialog_content = "Vamos, deja de ser tan morboso. La pregunta más importante en este momento es: ¿qué hacemos con este niño?",
  ui_story_5046_50460901_182_dialog_content = "¿Llevarla al orfanato?",
  ui_story_5046_50460901_183_dialog_content = "Supongo que eso es todo lo que podemos hacer.",
  ui_story_5046_50460901_184_dialog_content = "tengo otras preguntas",
  ui_story_5046_50461001_1_dialog_content = "Parece que se está calmando.",
  ui_story_5046_50461001_2_dialog_content = "Gracias, Kristen.",
  ui_story_5046_50461001_3_dialog_content = "¿Para qué?",
  ui_story_5046_50461001_4_dialog_content = "Gracias, que esperas Hati para recuperar su memoria.",
  ui_story_5046_50461001_5_dialog_content = "no piensas Hati ¿El culpable tampoco es usted?",
  ui_story_5046_50461001_6_dialog_content = "Después de realizar una investigación exhaustiva, ciertamente sospecho Hati menos.",
  ui_story_5046_50461001_7_dialog_content = "Aunque todos estos casos están relacionados con Hati, y cada pista apunta a ella.",
  ui_story_5046_50461001_8_dialog_content = "Pero aún quedan muchas contradicciones por resolver.",
  ui_story_5046_50461001_9_dialog_content = "Realmente estás poniendo todo de ti en este caso, Kristen.",
  ui_story_5046_50461001_10_dialog_content = "El Sr. Zenas me enseñó que debemos tomar cada caso con seriedad y nunca dejar una sola pista.",
  ui_story_5046_50461001_11_dialog_content = "Pero todavía no estaba dispuesto a dejarme tomar este caso...",
  ui_story_5046_50461001_12_dialog_content = "Entonces, Kristen, has estado investigando este caso en secreto?",
  ui_story_5046_50461001_13_dialog_content = "Si...",
  ui_story_5046_50461001_14_dialog_content = "Hablando de que, PlayerName¿Por qué te escapaste con Hati? Te ha estado reteniendo contra tu voluntad.",
  ui_story_5046_50461001_15_dialog_content = "Creo que es inocente, y con todo lo que ha pasado, sus emociones han sido muy inestables.",
  ui_story_5046_50461001_16_dialog_content = "Necesitaba mi ayuda, así que le pedí que me llevara con ella.",
  ui_story_5046_50461001_17_dialog_content = "¿Establecieron un vínculo de confianza tan fuerte entre ustedes en tan poco tiempo...?",
  ui_story_5046_50461001_18_dialog_content = "<size=30>Si tan solo el Sr. Zenas pudiera confiar tanto en mí...</size>",
  ui_story_5046_50461001_19_dialog_content = "¿Cómo encontraste este lugar?",
  ui_story_5046_50461001_20_dialog_content = "Un lugareño me mostró el camino.",
  ui_story_5046_50461001_21_dialog_content = "No está lejos del orfanato, pero sigue siendo parte de Umbraton. Hace muchos, muchos años, los lugareños vivían vidas muy duras.",
  ui_story_5046_50461001_22_dialog_content = "El año del incendio del orfanato, Istvan se ganó los corazones de muchas personas después de que se encargó de mejorar la situación.",
  ui_story_5046_50461001_23_dialog_content = "Después de convertirse en el Señor de las Sombras, Istvan pidió a la gente de aquí que se mudara a Umbraton.",
  ui_story_5046_50461001_24_dialog_content = "En realidad, fue el mismo hombre que entregó Hati al orfanato, que me trajo aquí.",
  ui_story_5046_50461001_25_dialog_content = "Dijo que antes hubo un incendio en esta ciudad, y Hati fue encontrado entre los escombros después de que el fuego fuera extinguido.",
  ui_story_5046_50461001_26_dialog_content = "La mujer que vivía aquí murió.",
  ui_story_5046_50461001_27_dialog_content = "Pero los lugareños nunca escucharon a la mujer mencionar que tenía un hijo, por lo que no sabían qué hacer.",
  ui_story_5046_50461001_28_dialog_content = "Finalmente, decidieron enviar al niño al orfanato. ese niño era Hati.",
  ui_story_5046_50461001_29_dialog_content = "Entonces eso es...",
  ui_story_5046_50461001_30_dialog_content = "Increíble trabajo, Kristen. Descubriste mucho con solo unas pocas pistas para continuar.",
  ui_story_5046_50461001_31_dialog_content = "¡Ejem! Realmente no importa cuánto me elogies, te traeré de vuelta conmigo para que cooperes con la investigación.",
  ui_story_5046_50461001_32_dialog_content = "¡Creo desde el fondo de mi corazón que eres realmente increíble! ¡Sé que serás un excelente juez en el futuro!",
  ui_story_5046_50461001_33_dialog_content = "Si tan solo pensara lo mismo...",
  ui_story_5046_50461001_34_dialog_content = "¿Señor Zenas?",
  ui_story_5046_50461001_35_dialog_content = "Sí... El Sr. Zenas resultó herido usando Luminética para apagar el fuego, pero incluso después de esto, el Sr. Hamell murió...",
  ui_story_5046_50461001_36_dialog_content = "Ya no tiene ninguna fe en mí.",
  ui_story_5046_50461001_37_dialog_content = "Creo que lo has hecho muy bien, Kristen.",
  ui_story_5046_50461001_38_dialog_content = "Aunque solo hemos tenido la oportunidad de conocernos unas pocas veces, puedo sentir que es un juez concienzudo, paciente y amable.",
  ui_story_5046_50461001_39_dialog_content = "N-No creas que tus dulces palabras pueden convertirme...",
  ui_story_5046_50461001_40_dialog_content = "¡Recibí una amplia formación profesional en el Lumo Hall of Justice! ¡Mi creencia en la justicia nunca será sacudida por gente como tú!",
  ui_story_5046_50461001_41_dialog_content = "¡Solo dije lo que quería decir! ¡No quise decir nada más con eso!",
  ui_story_5046_50461001_42_dialog_content = "Si Hati realmente hubiera hecho esas cosas, la habría hecho confesar.",
  ui_story_5046_50461001_43_dialog_content = "¡Pero si ella no hizo nada, no puedes incriminarla!",
  ui_story_5046_50461001_44_dialog_content = "R-Claro! ¡Ese es el significado de la justicia!",
  ui_story_5046_50461001_45_dialog_content = "Debes tratar de creer en ti mismo y dejar de preocuparte por lo que piensen los demás.",
  ui_story_5046_50461001_46_dialog_content = "¡Especialmente considerando lo increíble que eres!",
  ui_story_5046_50461001_47_dialog_content = "...",
  ui_story_5046_50461001_48_dialog_content = "¿Alguien te ha dicho alguna vez que eres muy bueno haciendo felices a las chicas?",
  ui_story_5046_50461001_49_dialog_content = "¿Eh? ¿Hago felices a las chicas?",
  ui_story_5046_50461001_50_dialog_content = "Vice siempre me odia por gastar dinero y hacer que se preocupe por los gastos del Coloso todos los días.",
  ui_story_5046_50461001_51_dialog_content = "Será mejor que digas que siempre les causo problemas a las chicas.",
  ui_story_5046_50461001_52_dialog_content = "<size=45>Graaaaah—</size>",
  ui_story_5046_50461001_53_dialog_content = "¿Fue eso un eclipse? Parece que hay más de uno.",
  ui_story_5046_50461001_54_dialog_content = "Este lugar ha estado desierto durante mucho tiempo. Es de esperar que los eclipses acechen en esta área.",
  ui_story_5046_50461001_55_dialog_content = "Pero Hati aún no se ha despertado. Me temo que podría ser peligroso traerla aquí ahora.",
  ui_story_5046_50461001_56_dialog_content = "No te preocupes, son solo algunos eclipses. ¡Los juzgaré en el acto!",
  ui_story_5046_50461002_1_dialog_content = "Uf-",
  ui_story_5046_50461002_2_dialog_content = "El aura de Eclipsite por aquí finalmente se ha disipado.",
  ui_story_5046_50461002_3_dialog_content = "Gracias, Kristen.",
  ui_story_5046_50461002_4_dialog_content = "Ahora veo lo poderosos que son los caelestitas.",
  ui_story_5046_50461002_5_dialog_content = "Si no fuera por ti, los ataques furtivos de esos Eclipsites podrían haber tenido éxito.",
  ui_story_5046_50461002_6_dialog_content = "PlayerName...",
  ui_story_5046_50461002_7_dialog_content = "Hati! ¡Hati está despierto!",
  ui_story_5046_50461002_8_dialog_content = "Ahora que estás despierto, debes volver conmigo para interrogarte. Antes de que salgan los resultados de la investigación...",
  ui_story_5046_50461002_9_dialog_content = "era zenas...",
  ui_story_5046_50461002_10_dialog_content = "¿Mi mentor?",
  ui_story_5046_50461002_11_dialog_content = "PlayerName... Lo recuerdo todo.",
  ui_story_5046_50461002_12_dialog_content = "Esa noche, mi mamá me empujó hacia la chimenea para protegerme.",
  ui_story_5046_50461002_13_dialog_content = "Se enfrentó a Zenas sola... Sí, el nombre de ese hombre era Zenas.",
  ui_story_5046_50461002_14_dialog_content = "Mató a mi mamá y le robó su colgante.",
  ui_story_5046_50461002_15_dialog_content = "Debo recuperar el colgante.",
  ui_story_5046_50461002_16_dialog_content = "¿Mi mentor? ¿Qué tiene esto que ver con mi mentor?",
  ui_story_5046_50461002_17_dialog_content = "Zenas es el asesino.",
  ui_story_5046_50461002_18_dialog_content = "¡Tonterías!",
  ui_story_5046_50461002_19_dialog_content = "Si te atreves a faltarle el respeto al Sr. Zenas otra vez, ¡no me culpes por lo que haga a continuación!",
  ui_story_5046_50461002_20_dialog_content = "Un asesino es un asesino, y él es el indicado.",
  ui_story_5046_50461002_21_dialog_content = "Zenas irrumpió en mi casa esa noche, mató a mi madre y robó mi colgante.",
  ui_story_5046_50461002_22_dialog_content = "¡Lo vi todo con mis propios ojos! ¡Necesito matarlo para vengar a mi mamá!",
  ui_story_5046_50461002_23_dialog_content = "¿¡Cómo puedes decir que mi mentor asesinó a tu madre!?",
  ui_story_5046_50461002_24_dialog_content = "Acabas de recordar este incidente, y ha pasado tanto tiempo.",
  ui_story_5046_50461002_25_dialog_content = "¿Cómo puedes estar seguro de que tu memoria no está equivocada? ¿Y cómo sé que no estás mintiendo?",
  ui_story_5046_50461002_26_dialog_content = "se que no me equivoco...",
  ui_story_5046_50461002_27_dialog_content = "Con las quemaduras en la cara y el colgante de mi mamá...",
  ui_story_5046_50461002_28_dialog_content = "¡Estoy seguro de que es el asesino!",
  ui_story_5046_50461002_29_dialog_content = "Lo siento, pero mi mentor sufrió una quemadura en la cara cuando me estaba salvando.",
  ui_story_5046_50461002_30_dialog_content = "Esa noche, mis padres fueron a un banquete.",
  ui_story_5046_50461002_31_dialog_content = "Recuerdo que oscureció muy temprano ese día... Tan pronto como despedí a mis padres, oscureció.",
  ui_story_5046_50461002_32_dialog_content = "Regresé a mi habitación para leer solo.",
  ui_story_5046_50461002_33_dialog_content = "De repente, un gran incendio estalló en algún lugar. Mis padres no estaban en casa y el humo se hizo más denso, yo me quedé allí llorando a gritos.",
  ui_story_5046_50461002_34_dialog_content = "Afortunadamente, el Sr. Zenas gritó mi nombre y siguió mis sollozos para encontrarme...",
  ui_story_5046_50461002_35_dialog_content = "Mientras escapábamos, el Sr. Zenas me sostuvo con fuerza en sus brazos y no sufrí ninguna lesión, excepto que me asfixiaba el humo denso.",
  ui_story_5046_50461002_36_dialog_content = "Pero el Sr. Zenas... La mitad de su cara estaba quemada.",
  ui_story_5046_50461002_37_dialog_content = "Entonces, la cara de Zenas se quemó mientras rescataba Kristen.",
  ui_story_5046_50461002_38_dialog_content = "...",
  ui_story_5046_50461002_39_dialog_content = "Hati, ¿recuerdas el día que atacó Zenas?",
  ui_story_5046_50461002_40_dialog_content = "26 de agosto Era mi cumpleaños.",
  ui_story_5046_50461002_41_dialog_content = "26 de agosto!?",
  ui_story_5046_50461002_42_dialog_content = "El día que el Sr. Zenas me salvó fue también el 26 de agosto.",
  ui_story_5046_50461002_43_dialog_content = "Ese día... lo recuerdo muy claramente.",
  ui_story_5046_50461002_44_dialog_content = "Parece que estos dos eventos tuvieron lugar el mismo día...",
  ui_story_5046_50461002_45_dialog_content = "En este momento, Kristen dijo que su mansión se incendió esa noche, lo que significa que Zenas apareció en la casa de Kristen por la noche.",
  ui_story_5046_50461002_46_dialog_content = "Pero Hati También dijo que Zenas atacaba de noche.",
  ui_story_5046_50461002_47_dialog_content = "En otras palabras, Zenas apareció en dos lugares diferentes al mismo tiempo el mismo día.",
  ui_story_5046_50461002_48_dialog_content = "Cuando lo miras de esa manera, es imposible. Debes estar equivocado, Hati.",
  ui_story_5046_50461002_49_dialog_content = "¿Cómo explicas el colgante?",
  ui_story_5046_50461002_50_dialog_content = "¿Por qué el colgante que mi mamá me pidió que cuidara en sus manos?",
  ui_story_5046_50461002_51_dialog_content = "Fue precisamente por este colgante que lo reconocí.",
  ui_story_5046_50461002_52_dialog_content = "El colgante que mencionaste es una reliquia familiar de mi mentor.",
  ui_story_5046_50461002_53_dialog_content = "El patrón del colgante es el escudo familiar de una familia noble de Lumopolis que lamentablemente cayó hace más de una década.",
  ui_story_5046_50461002_54_dialog_content = "El día que mi mentor me rescató del fuego, mi padre quiso expresar su agradecimiento por salvarme la vida y le preguntó sobre sus antecedentes.",
  ui_story_5046_50461002_55_dialog_content = "Mi mentor sacó ese colgante y dijo que originalmente era un noble, pero que tuvo que deambular sin esperanza porque su familia declinó.",
  ui_story_5046_50461002_56_dialog_content = "Mi padre simpatizaba con él, siendo un compañero noble, y le pidió a mi mentor que se quedara y sirviera a nuestra familia.",
  ui_story_5046_50461002_57_dialog_content = "Recuerdo claramente que el colgante pertenecía a mi mamá.",
  ui_story_5046_50461002_58_dialog_content = "¡Debe haber tomado el colgante de mi mamá y lo hizo pasar como suyo!",
  ui_story_5046_50461002_59_dialog_content = "¡Tú! Sus inferencias no pueden considerarse verdaderas hasta que tenga evidencia.",
  ui_story_5046_50461002_60_dialog_content = "(Hati mencionó anteriormente que su madre mantenía la casa bien protegida contra la luz del día y la iluminaba con velas).",
  ui_story_5046_50461002_61_dialog_content = "(Así que tal vez Hati ¡No estoy seguro de si era de día o de noche cuando ocurrió el incidente!)",
  ui_story_5046_50461002_62_dialog_content = "Hati, ¿puedes estar seguro de que el asesino irrumpió en tu casa por la noche?",
  ui_story_5046_50461002_63_dialog_content = "Recuerdo que las velas iluminaban la habitación. Debería haber sido de noche.",
  ui_story_5046_50461002_64_dialog_content = "Esa es la cosa.",
  ui_story_5046_50461002_65_dialog_content = "Debido a que las velas a menudo iluminan tu hogar, por supuesto que pensarías—",
  ui_story_5046_50461002_66_dialog_content = "“Porque vi velas encendidas, el incidente ocurrió de noche”.",
  ui_story_5046_50461002_67_dialog_content = "Pero, de hecho, las velas se encendían en su casa tanto de día como de noche, por lo que sería incorrecto usar velas encendidas para juzgar el tiempo.",
  ui_story_5046_50461002_68_dialog_content = "Propongo que la hora en que atacaron la casa de Hati era en realidad de día.",
  ui_story_5046_50461002_69_dialog_content = "Eso es todo...",
  ui_story_5046_50461002_70_dialog_content = "Kristen puede recordar con precisión que sus padres asistieron a un banquete por la noche y recuerda que oscureció temprano ese día.",
  ui_story_5046_50461002_71_dialog_content = "Entonces, el incendio en la casa de Kristen realmente ocurrió de noche.",
  ui_story_5046_50461002_72_dialog_content = "Según esta deducción, el sospechoso atacó la casa de Hati durante el día y corrió a la casa de Kristen por la noche para extinguir el fuego.",
  ui_story_5046_50461002_73_dialog_content = "Por lo tanto, no hay instancia de una persona que aparezca en dos lugares diferentes al mismo tiempo.",
  ui_story_5046_50461002_74_dialog_content = "Brillante razonamiento...",
  ui_story_5046_50461002_75_dialog_content = "Pero aún necesitamos más información. ¿Cuánto tiempo se tarda en llegar desde aquí hasta su mansión de vacaciones?",
  ui_story_5046_50461002_76_dialog_content = "Tomé nota de esto en mi camino aquí. No está lejos de mi mansión.",
  ui_story_5046_50461002_77_dialog_content = "¿Fue realmente... mi mentor? No es imposible...",
  ui_story_5046_50461002_78_dialog_content = "Si desea determinar si Zenas fue el atacante, solo pídale que le muestre su colgante.",
  ui_story_5046_50461002_79_dialog_content = "Hati dijo que estos dos colgantes eran un par a juego.",
  ui_story_5046_50461002_80_dialog_content = "Si Zenas no atacó a la familia de Hati y, como dijo, es un noble caído...",
  ui_story_5046_50461002_81_dialog_content = "Entonces su colgante no coincidirá con el que está en la mano de Hati.",
  ui_story_5046_50461002_82_dialog_content = "Pero si estos dos colgantes encajan perfectamente...",
  ui_story_5046_50461002_83_dialog_content = "Entonces él debe ser el culpable.",
  ui_story_5046_50461002_84_dialog_content = "¡No, mi mentor no puede ser un asesino!",
  ui_story_5046_50461002_85_dialog_content = "¡Oh, sí, es cierto! ¡Motivo!",
  ui_story_5046_50461002_86_dialog_content = "No existía enemistad entre tu familia y mi mentor, así que ¿por qué perseguiría y mataría a tus padres?",
  ui_story_5046_50461002_87_dialog_content = "Mi mamá me dijo que una organización misteriosa quería el poder de mi papá y querían atraparlo para usarlo en sus experimentos.",
  ui_story_5046_50461002_88_dialog_content = "En mi memoria, mi mamá quería vengar a mi papá, y perdió la vida tratando de matar a Zenas...",
  ui_story_5046_50461002_89_dialog_content = "Entonces, Zenas es miembro de esa misteriosa organización.",
  ui_story_5046_50461002_90_dialog_content = "¡No lo creo!",
  ui_story_5046_50461002_91_dialog_content = "¡No, no hay manera!",
  ui_story_5046_50461002_92_dialog_content = "Kristen, cálmate.",
  ui_story_5046_50461002_93_dialog_content = "Si Zenas es el culpable o no, se puede determinar simplemente juntando su colgante y el de Hati.",
  ui_story_5046_50461002_94_dialog_content = "Pídele que te entregue su colgante.",
  ui_story_5046_50461002_95_dialog_content = "Si se niega a entregarlo, lo golpearé hasta convertirlo en pulpa y se lo quitaré.",
  ui_story_5046_50461002_96_dialog_content = "¡No podemos usar la violencia! Umbraton está lleno de soldados buscándote. Será difícil para nosotros confrontar a Zenas y discutir esto con él.",
  ui_story_5046_50461002_97_dialog_content = "...",
  ui_story_5046_50461002_98_dialog_content = "Puedo ayudarle.",
  ui_story_5046_50461002_99_dialog_content = "Como PlayerName dijo, confirmando si los colgantes encajan entre sí es la forma más fácil de probar la inocencia de mi mentor.",
  ui_story_5046_50461002_100_dialog_content = "Así que te ayudaré a encontrarte con mi mentor sin ningún otro soldado.",
  ui_story_5046_50461002_101_dialog_content = "Sin embargo, también debes prometerme que si los colgantes no encajan, cooperarás plenamente con la investigación.",
  ui_story_5046_50461002_102_dialog_content = "Entonces, ¿nos crees?",
  ui_story_5046_50461002_103_dialog_content = "No dije eso.",
  ui_story_5046_50461002_104_dialog_content = "Pero he aprendido mucho de la actitud de investigación seria. PlayerName tiene hacia este incidente.",
  ui_story_5046_50461002_105_dialog_content = "Quiero volver a examinar este caso más detenidamente.",
  ui_story_5046_50461002_106_dialog_content = "Se está haciendo tarde. Volvamos rápido a Umbraton.",
  ui_story_5046_50461101_1_dialog_content = "Extrañar Kristen, estás de vuelta.",
  ui_story_5046_50461101_2_dialog_content = "Solo llamame Kristen.",
  ui_story_5046_50461101_3_dialog_content = "¿Dónde está el Capitán Zenas? ¿Por qué no puedo encontrarlo?",
  ui_story_5046_50461101_4_dialog_content = "El capitán Zenas llevó a varias personas al orfanato.",
  ui_story_5046_50461101_5_dialog_content = "¿El orfanato? ¿Qué hace el capitán ahí?",
  ui_story_5046_50461101_6_dialog_content = "Erm... Él no dijo.",
  ui_story_5046_50461101_7_dialog_content = "Muy bien, continúa.",
  ui_story_5046_50461101_8_dialog_content = "No pudimos encontrar nada, señor.",
  ui_story_5046_50461101_9_dialog_content = "Seguir mirando. Cualquier cosa que encuentres, dámela directamente, ¿entiendes?",
  ui_story_5046_50461101_10_dialog_content = "¡Reportándome!",
  ui_story_5046_50461101_11_dialog_content = "¿Encontraste algo?",
  ui_story_5046_50461101_12_dialog_content = "No, pero señorita Kristen es aquí. Ella quiere verte.",
  ui_story_5046_50461101_13_dialog_content = "¿Que está haciendo ella aquí?",
  ui_story_5046_50461101_14_dialog_content = "Señor.",
  ui_story_5046_50461101_15_dialog_content = "Vamos afuera. Quiero hablar contigo a solas.",
  ui_story_5046_50461101_16_dialog_content = "Está bien...",
  ui_story_5046_50461101_17_dialog_content = "¿Kristen? ¿Qué estás haciendo acá?",
  ui_story_5046_50461101_18_dialog_content = "¿No se suponía que ibas a presentar el caso en el Salón de Justicia de Lumo?",
  ui_story_5046_50461101_19_dialog_content = "Antes de volver a Lumopolis, quería preguntarte algo.",
  ui_story_5046_50461101_20_dialog_content = "¿Me prestas tu colgante?",
  ui_story_5046_50461101_21_dialog_content = "¿Mi colgante?",
  ui_story_5046_50461101_22_dialog_content = "Una vez me mostraste un colgante con el emblema de tu familia.",
  ui_story_5046_50461101_23_dialog_content = "¿Por qué quieres verlo?",
  ui_story_5046_50461101_24_dialog_content = "Mmm...",
  ui_story_5046_50461101_25_dialog_content = "Vi un patrón similar al emblema de su familia mientras revisaba mis archivos, así que quería echar otro vistazo a su colgante, solo para estar seguro.",
  ui_story_5046_50461101_26_dialog_content = "...",
  ui_story_5046_50461101_27_dialog_content = "Kristen, te vi crecer. Puedo decir en un instante cuando estás mintiendo.",
  ui_story_5046_50461101_28_dialog_content = "Señor...",
  ui_story_5046_50461101_29_dialog_content = "Vamos, ¿cuál es la razón?",
  ui_story_5046_50461101_30_dialog_content = "Bueno, en realidad... en realidad quiero probar tu inocencia con ese colgante.",
  ui_story_5046_50461101_31_dialog_content = "¿Probar mi inocencia?",
  ui_story_5046_50461101_32_dialog_content = "Me enteré de que podrías estar relacionado con un caso de incendio provocado hace muchos años.",
  ui_story_5046_50461101_33_dialog_content = "El colgante que siempre llevas puesto es la clave para eliminar todas las sospechas que te rodean.",
  ui_story_5046_50461101_34_dialog_content = "¿Cuál es la relación entre mi colgante y este caso de incendio provocado?",
  ui_story_5046_50461101_35_dialog_content = "Me dijeron que tu colgante es parte de un par y combina con el colgante que tengo aquí en la mano.",
  ui_story_5046_50461101_36_dialog_content = "Sólo necesito que me prestes el colgante y me dejes confirmar si los dos colgantes se pueden combinar...",
  ui_story_5046_50461101_37_dialog_content = "Si tiene algo relacionado con el caso, debe entregárselo al personal correspondiente para que lo examine detalladamente.",
  ui_story_5046_50461101_38_dialog_content = "Cuestionar directamente a su superior con pruebas... Kristen, ¿no te he enseñado nada todos estos años?",
  ui_story_5046_50461101_39_dialog_content = "Si no quiere entregarlo, tenemos otras formas de hacer que coopere.",
  ui_story_5046_50461101_40_dialog_content = "Hati?",
  ui_story_5046_50461101_41_dialog_content = "Kristen, ya que ha atrapado a la sospechosa, ¿por qué no la mete en la cárcel donde pertenece?",
  ui_story_5046_50461101_42_dialog_content = "Porque Hati no es sospechosa, los casos de incendio premeditado en Umbraton y la muerte del Sr. Hamell no tienen nada que ver con ella.",
  ui_story_5046_50461101_43_dialog_content = "Ya veo... Entonces, eso es todo.",
  ui_story_5046_50461101_44_dialog_content = "Kristen, ¿¡realmente albergaste a una sospechosa y conspiraste con ella para engañar a tu superior!?",
  ui_story_5046_50461101_45_dialog_content = "yo... yo no...",
  ui_story_5046_50461101_46_dialog_content = "Ella solo quería tomar prestado tu colgante... ¿No crees que tu reacción parece demasiado extrema?",
  ui_story_5046_50461101_47_dialog_content = "¿Podría ser porque... eres culpable?",
  ui_story_5046_50461101_48_dialog_content = "Aprovechaste que en la casa de Hati se encendían velas día y noche para crearte una coartada, y usaste Kristen como tu testigo!",
  ui_story_5046_50461101_49_dialog_content = "Después de cometer un asesinato en la casa de Hati, prendiste fuego a la mansión de Kristen no muy lejos.",
  ui_story_5046_50461101_50_dialog_content = "¡Fingiste pasar y corriste para salvar a quienquiera que estuviera dentro, creando la ilusión de que la quemadura en tu rostro era el resultado de tu heroísmo!",
  ui_story_5046_50461101_51_dialog_content = "Pero, de hecho, la fea verdad es que la quemadura en tu rostro fue el resultado de la pelea con la madre de Hati, ¡quien provocó un incendio en un intento de asegurarse de que murieras con ella!",
  ui_story_5046_50461101_52_dialog_content = "Hmph. ¿Es esta la historia que inventaste para enmarcarme? Es muy emocionante.",
  ui_story_5046_50461101_53_dialog_content = "Esta es mi opinión sobre el caso en base a la información disponible.",
  ui_story_5046_50461101_54_dialog_content = "Kristen, ¿es esto lo que también crees?",
  ui_story_5046_50461101_55_dialog_content = "Señor... yo...",
  ui_story_5046_50461101_56_dialog_content = "PlayerNamededucción de...",
  ui_story_5046_50461101_57_dialog_content = "Yo...",
  ui_story_5046_50461101_58_dialog_content = "...",
  ui_story_5046_50461101_59_dialog_content = "¡Jajajajajaja!",
  ui_story_5046_50461101_60_dialog_content = "Kristen, mi señora... realmente eres otra cosa.",
  ui_story_5046_50461101_61_dialog_content = "Prefieres creerle a un Caelestite que solo has conocido un día que a tu propio mentor.",
  ui_story_5046_50461101_62_dialog_content = "¿Por qué no nos dejas ver el colgante...?",
  ui_story_5046_50461101_63_dialog_content = "Claramente, todo lo que necesitas hacer es mostrármelo para disipar mis dudas...",
  ui_story_5046_50461101_64_dialog_content = "Dado que las semillas de la duda ya se han sembrado en tu corazón, ¿cuál es el punto?",
  ui_story_5046_50461101_65_dialog_content = "Tanto si te lo doy como si no, ya has llegado a un veredicto.",
  ui_story_5046_50461101_66_dialog_content = "¡No, eso no es cierto en absoluto! Todas las deducciones requieren evidencia para probar su veracidad...",
  ui_story_5046_50461101_67_dialog_content = "Está bien, no digas más.",
  ui_story_5046_50461101_68_dialog_content = "En el futuro, no se refiera a mí como su mentor.",
  ui_story_5046_50461101_69_dialog_content = "Dado que ha elegido asociarse con este sospechoso, la punta de mi espada ahora apunta hacia usted.",
  ui_story_5046_50461101_70_dialog_content = "Señor... ¿Cuál es el significado de esto?",
  ui_story_5046_50461101_71_dialog_content = "Kristen¡Tienes que confiar en tu propio juicio!",
  ui_story_5046_50461101_72_dialog_content = "¡Está tratando de chantajearte emocionalmente! No importa si es tu mentor o no, ¡tienes que aferrarte al sentido de la justicia en tu corazón!",
  ui_story_5046_50461101_73_dialog_content = "Éste es quién eres, Kristen¡Un juez de prueba de Lumópolis!",
  ui_story_5046_50461101_74_dialog_content = "Yo...",
  ui_story_5046_50461101_75_dialog_content = "¡Guardias! Kristen se ha coludido con Caelestite para albergar al sospechoso, Hati. ¡Arréstenlos a todos!",
  ui_story_5046_50461101_76_dialog_content = "¡Señor!",
  ui_story_5046_50461102_1_dialog_content = "Jadeo... jadeo...",
  ui_story_5046_50461102_2_dialog_content = "No puedo creer que derrotaste a todos mis guardias...",
  ui_story_5046_50461102_3_dialog_content = "De acuerdo con las leyes del Salón de la Justicia, ¿qué hacemos con aquellos que se resisten al arresto y atacan a los Lumo Guards?",
  ui_story_5046_50461102_4_dialog_content = "Bien, Kristen?",
  ui_story_5046_50461102_5_dialog_content = "Señor, por favor coopere con la investigación...",
  ui_story_5046_50461102_6_dialog_content = "Una vez concluida la investigación, se probará su inocencia y todo podrá volver a ser como antes...",
  ui_story_5046_50461102_7_dialog_content = "Está bien.",
  ui_story_5046_50461102_8_dialog_content = "¿¡Eh!? ¿¡Usted está de acuerdo!?",
  ui_story_5046_50461102_9_dialog_content = "(Estaba tan decidido a no ceder hace un momento... ¿Por qué de repente estuvo de acuerdo?)",
  ui_story_5046_50461102_10_dialog_content = "¡Entregue el colgante, rápido!",
  ui_story_5046_50461102_11_dialog_content = "Mató a mi mamá... ¡Tiene que pagar por lo que hizo!",
  ui_story_5046_50461102_12_dialog_content = "¡Voy a vengar a mis padres! ¡Lo mataré!",
  ui_story_5046_50461102_13_dialog_content = "Cálmate, Hati!",
  ui_story_5046_50461102_14_dialog_content = "Puedes contar con Kristen para investigar todo este asunto.",
  ui_story_5046_50461102_15_dialog_content = "¡Si usaras la violencia para resolver las cosas, te convertirías en un verdadero asesino!",
  ui_story_5046_50461102_16_dialog_content = "El Hati ¡Sé que es una niña gentil y amable cuyos padres la aman!",
  ui_story_5046_50461102_17_dialog_content = "¡Tus padres no querrían que los vengaras de esta manera!",
  ui_story_5046_50461102_18_dialog_content = "De verdad... ¿Mamá y papá no querrían que yo...?",
  ui_story_5046_50461102_19_dialog_content = "... Humm.",
  ui_story_5046_50461102_20_dialog_content = "Puedo entregar el colgante, pero primero tendré que volver a Umbraton y probar mi inocencia delante de todos.",
  ui_story_5046_50461102_21_dialog_content = "Vamos, Kristen.",
  ui_story_5046_50461102_22_dialog_content = "Cuando volvamos a Umbraton, probaré mi inocencia, y entonces podremos volver a ser como eran las cosas...",
  ui_story_5046_50461102_23_dialog_content = "Mmmm...",
  ui_story_5046_50461102_24_dialog_content = "Ninguno de ustedes se mueva, o le romperé el cuello.",
  ui_story_5046_50461102_25_dialog_content = "¿¡Señor!? Por qué...",
  ui_story_5046_50461102_26_dialog_content = "¿Qué crees que estás haciendo? Deja ir Kristen!",
  ui_story_5046_50461102_27_dialog_content = "Mientras perseguía al sospechoso Hati, el sospechoso se resistió al arresto, y Kristen, por desgracia, murió en el cumplimiento del deber...",
  ui_story_5046_50461102_28_dialog_content = "¡Estas loco!",
  ui_story_5046_50461102_29_dialog_content = "Mientras Kristen muere, seré el único que sepa lo que realmente sucedió aquí hoy.",
  ui_story_5046_50461102_30_dialog_content = "Enviaré un informe a la Sala de Justicia y Hati será tildado de asesino despiadado e incendiario!",
  ui_story_5046_50461102_31_dialog_content = "¡Y tú, Caelestite, te convertirás en su cómplice!",
  ui_story_5046_50461102_32_dialog_content = "En ese momento, nadie creerá nada de lo que digas.",
  ui_story_5046_50461102_33_dialog_content = "¿¡De verdad crees que puedes encubrir la verdad!?",
  ui_story_5046_50461102_34_dialog_content = "¡¿De verdad crees que solo tú puedes incriminarnos con tus mentiras?!",
  ui_story_5046_50461102_35_dialog_content = "Verdad, mentira... ¿Qué importa al final?",
  ui_story_5046_50461102_36_dialog_content = "Lo importante es que sigo mi vida de caballero, a salvo en Lumopolis, sin más incidentes...",
  ui_story_5046_50461102_37_dialog_content = "En cuanto a la verdad... ¡será enterrada con tus huesos, en lo profundo de la tierra para siempre!",
  ui_story_5046_50461102_38_dialog_content = "Señor... ¿Cómo puede decir eso?",
  ui_story_5046_50461102_39_dialog_content = "¿No me enseñaste siempre a defender la justicia y luchar por la verdad? ¿Por qué? ¿Por qué dirías tal cosa...?",
  ui_story_5046_50461102_40_dialog_content = "Kristen, me consideras una persona importante en tu corazón?",
  ui_story_5046_50461102_41_dialog_content = "¡Ahh!",
  ui_story_5046_50461102_42_dialog_content = "Dado que significo tanto para ti, ¿no harías todo lo posible para mantener mi reputación y posición, incluso si eso significara morir por mí?",
  ui_story_5046_50461102_43_dialog_content = "Señor... Señor, ¿qué está diciendo...?",
  ui_story_5046_50461102_44_dialog_content = "Arriesgaste tu vida para salvar Kristen todos esos años atrás! ¡¿Cómo puedes ser tan cruel como para amenazar con matarla?!",
  ui_story_5046_50461102_45_dialog_content = "(Hati! ¡Te estoy hablando usando mi habilidad psíquica! Tenemos que encontrar una manera de salvar Kristen!)",
  ui_story_5046_50461102_46_dialog_content = "¿PlayerName?",
  ui_story_5046_50461102_47_dialog_content = "(¡Distraeré a Zenas, encuentra la oportunidad de acercarte sigilosamente a él!)",
  ui_story_5046_50461102_48_dialog_content = "Entiendo.",
  ui_story_5046_50461102_49_dialog_content = "¿La salvé? ¿Te refieres a ese fuego? Supongo que me debe aún más, entonces. Ahora ella tiene la oportunidad de pagarme.",
  ui_story_5046_50461102_50_dialog_content = "A menos que mi deducción anterior estuviera completamente equivocada, arriesgaste tu vida para lanzarte a las llamas y salvar Kristen...",
  ui_story_5046_50461102_51_dialog_content = "Entonces, ¿¡cómo puedes siquiera pensar en lastimarla ahora!?",
  ui_story_5046_50461102_52_dialog_content = "Sí, la niña por la que sacrifiqué mi vida y le enseñé durante tantos años...",
  ui_story_5046_50461102_53_dialog_content = "¿Cómo podría obligarme a lastimarla?",
  ui_story_5046_50461102_54_dialog_content = "Señor...",
  ui_story_5046_50461102_55_dialog_content = "Pero Kristen, mi jovencita...",
  ui_story_5046_50461102_56_dialog_content = "Desde el principio, solo fuiste un peón para mí.",
  ui_story_5046_50461102_57_dialog_content = "Y eso incluye el fuego. Todo era parte de mi plan.",
  ui_story_5046_50461102_58_dialog_content = "¿¡Qué!?",
  ui_story_5046_50461102_59_dialog_content = "Durante mucho tiempo había querido subirme a la espalda de un poderoso noble y entrar en la sociedad de Lumopolis. Tu mansión estaba cerca.",
  ui_story_5046_50461102_60_dialog_content = "Rápidamente aprendí que todos los que trabajaban en la mansión ese día eran unos tontos débiles, así que soborné a la ayuda y prendí fuego al lugar.",
  ui_story_5046_50461102_61_dialog_content = "Fingí estar pasando e hice como si estuviera arriesgando desesperadamente mi vida y mi cuerpo para rescatar a esta pobre dama noble de Lumopolis.",
  ui_story_5046_50461102_62_dialog_content = "Efectivamente, su familia estaba muy agradecida conmigo, permitiéndome entrar sin problemas en la sociedad de Lumopolis y vivir la vida que siempre había soñado.",
  ui_story_5046_50461102_63_dialog_content = "Todo fue gracias a ti, mi... no, Kristen.",
  ui_story_5046_50461102_X63_dialog_content = "¡Mira, me quemé la cara para salvarte!",
  ui_story_5046_50461102_64_dialog_content = "Tú... ¡Eres abominable! ¡No te perdonaré!",
  ui_story_5046_50461102_65_dialog_content = "¿Valió la pena desfigurarse solo para congraciarse con la nobleza de Lumopolis?",
  ui_story_5046_50461102_66_dialog_content = "¿Alguna vez has probado el poder, Caelestite?",
  ui_story_5046_50461102_67_dialog_content = "El poder se puede intercambiar por dinero, pero el dinero no necesariamente compra poder.",
  ui_story_5046_50461102_68_dialog_content = "¡Mientras tengas poder, nada está fuera de tu alcance y nadie puede interponerse en tu camino!",
  ui_story_5046_50461102_69_dialog_content = "¿No es así, Kristen?",
  ui_story_5046_50461102_70_dialog_content = "Naciste como un noble de Lumopolis. Debe ser una sensación maravillosa, ¿no?",
  ui_story_5046_50461102_71_dialog_content = "Inquieta yace la cabeza que lleva corona...",
  ui_story_5046_50461102_72_dialog_content = "Los nobles deben poseer un carácter noble.",
  ui_story_5046_50461102_73_dialog_content = "Aquellos que usan su condición de nobles para beneficio personal no son dignos de ser llamados nobles.",
  ui_story_5046_50461102_74_dialog_content = "¡Jajajajaja!",
  ui_story_5046_50461102_75_dialog_content = "Kristen, realmente creíste cada pequeño cliché vacío que te enseñé, ¿no es así?",
  ui_story_5046_50461102_76_dialog_content = "¿De verdad crees que todos los nobles son como tú, tan puros y nobles como el lirio?",
  ui_story_5046_50461102_77_dialog_content = "Muy bien, eso es suficiente charla.",
  ui_story_5046_50461102_78_dialog_content = "¿Mmm? donde esta Hati!?",
  ui_story_5046_50461102_79_dialog_content = "...",
  ui_story_5046_50461102_80_dialog_content = "(Ahora, Hati!)",
  ui_story_5046_50461102_81_dialog_content = "Hya-!",
  ui_story_5046_50461102_82_dialog_content = "¡Ahh!",
  ui_story_5046_50461102_83_dialog_content = "¿¡De donde vienes!?",
  ui_story_5046_50461102_84_dialog_content = "Urgh...",
  ui_story_5046_50461102_85_dialog_content = "Kristen, ¿¡Estás bien!?",
  ui_story_5046_50461102_86_dialog_content = "Déjame ayudarte... ¿Aún puedes estar de pie?",
  ui_story_5046_50461102_87_dialog_content = "PlayerName... Boo-hoo...",
  ui_story_5046_50461102_88_dialog_content = "Ven aquí.",
  ui_story_5046_50461102_89_dialog_content = "No más rehenes. Solo entrega el colgante.",
  ui_story_5046_50461102_90_dialog_content = "¿O tengo que golpearte un poco de honestidad?",
  ui_story_5046_50461102_91_dialog_content = "Muy bien... Aquí, aquí tienes.",
  ui_story_5046_50461102_92_dialog_content = "Quieres el colgante...",
  ui_story_5046_50461102_93_dialog_content = "¡Puedes cambiarlo por tu vida!",
  ui_story_5046_50461102_94_dialog_content = "<color=#e8d9bb>Timbre-</color>",
  ui_story_5046_50461102_95_dialog_content = "!!!",
  ui_story_5046_50461102_96_dialog_content = "¡Ahh!",
  ui_story_5046_50461102_97_dialog_content = "Pretendiendo entregar el colgante y lanzando un ataque furtivo... ¡Hmph!",
  ui_story_5046_50461102_98_dialog_content = "Ahora que estamos sin nuestras armas, ¿quién sabe quién ganará?",
  ui_story_5046_50461102_99_dialog_content = "Kristen y Caelestite tienen poco poder de combate para hablar, así que ahora...",
  ui_story_5046_50461102_100_dialog_content = "Solo somos tú y yo.",
  ui_story_5046_50461102_101_dialog_content = "Después de que me ocupe de ti, me ocuparé de esos dos...",
  ui_story_5046_50461102_102_dialog_content = "¡Jajajajaja!",
  ui_story_5046_50461102_103_dialog_content = "...",
  ui_story_5046_50461102_104_dialog_content = "¡Mi espada!",
  ui_story_5046_50461102_105_dialog_content = "¡Hmph! No importa, este hacha funcionará bien.",
  ui_story_5046_50461102_106_dialog_content = "No eres digno de esa espada con toda la sangre en tus manos.",
  ui_story_5046_50461102_X106_dialog_content = "Una espada representa la justicia, pero eres malvado.",
  ui_story_5046_50461102_107_dialog_content = "¿Crees que la justicia siempre prevalecerá contra el mal?",
  ui_story_5046_50461102_108_dialog_content = "Por supuesto.",
  ui_story_5046_50461102_109_dialog_content = "No estés tan seguro de que me ganarás.",
  ui_story_5046_50461102_110_dialog_content = "<color=#e8d9bb>Sonido metálico-</color>",
  ui_story_5046_50461102_111_dialog_content = "¡¡¡Vete al infierno!!!",
  ui_story_5046_50461102_112_dialog_content = "¡Hola!",
  ui_story_5046_50461102_113_dialog_content = "¡Aaaaaah!",
  ui_story_5046_50461102_114_dialog_content = "<color=#e8d9bb>¡Choque!</color>",
  ui_story_5046_50461102_115_dialog_content = "...",
  ui_story_5046_50461102_116_dialog_content = "¿Siente eso? Esa es tu espada presionada contra tu cuello.",
  ui_story_5046_50461102_117_dialog_content = "Podría cortarte el cuello en una fracción de segundo y vengar a mi madre.",
  ui_story_5046_50461102_118_dialog_content = "!!!",
  ui_story_5046_50461102_119_dialog_content = "Pero no lo haré.",
  ui_story_5046_50461102_120_dialog_content = "Porque PlayerName no quiere que lo haga.",
  ui_story_5046_50461102_121_dialog_content = "Mamá y papá tampoco querrían tu sangre en mis manos.",
  ui_story_5046_50461102_122_dialog_content = "Eh, tú. Es Kristen, ¿bien?",
  ui_story_5046_50461102_123_dialog_content = "Urgh...",
  ui_story_5046_50461102_124_dialog_content = "Deja de llorar ya. Antes de que te lo lleves, ¿puedo conseguir el colgante?",
  ui_story_5046_50461102_125_dialog_content = "¿Colgante? ¿Qué colgante? ¿Estás planeando robarme?",
  ui_story_5046_50461102_126_dialog_content = "¿¡Por qué todavía no estás dispuesto a confesar tus crímenes!?",
  ui_story_5046_50461102_127_dialog_content = "No entiendo de qué estás hablando.",
  ui_story_5046_50461102_128_dialog_content = "Señor... No, Zenas.",
  ui_story_5046_50461102_129_dialog_content = "Según los resultados de esta investigación, usted está relacionado con un caso de homicidio y dos casos de incendio premeditado de hace muchos años. Por favor, coopere conmigo.",
  ui_story_5046_50461102_130_dialog_content = "(Kristen se recuperó tan rápido. Ella estaba llorando hace un momento...)",
  ui_story_5046_50461102_131_dialog_content = "Mmm...",
  ui_story_5046_50461102_132_dialog_content = "Sigues siendo la chica obstinada y fuerte que siempre has sido...",
  ui_story_5046_50461102_133_dialog_content = "No quiero escuchar nada más de ti en este momento. Si tienes algo que decir, guárdalo para el Salón de la Justicia.",
  ui_story_5046_50461102_134_dialog_content = "Si debes saberlo, en realidad no quería matarte en este momento. Yo te rescaté en ese entonces, y me has acompañado durante tantos años.",
  ui_story_5046_50461102_135_dialog_content = "¿Cómo podría matarte?",
  ui_story_5046_50461102_136_dialog_content = "¿Por qué sigues tratando de engañarme?",
  ui_story_5046_50461102_137_dialog_content = "Con todo lo que te he dicho, ¿puedes decir lo que es verdad y lo que es falso?",
  ui_story_5046_50461102_138_dialog_content = "¡Para!",
  ui_story_5046_50461102_139_dialog_content = "¡Mentiroso! ¡Ya no tienes derecho a sermonearme!",
  ui_story_5046_50461102_140_dialog_content = "De ahora en adelante, juzgaré en quién confiar y en quién no confiar por mí mismo.",
  ui_story_5046_50461102_141_dialog_content = "he crecido Ya no soy la niña protegida que necesita tu guía.",
  ui_story_5046_50461102_142_dialog_content = "En cuanto a su crimen, la Sala de Justicia llegará a un veredicto justo.",
  ui_story_5046_50461102_143_dialog_content = "Lo siento, PlayerName. Perdón por perder la compostura frente a ti...",
  ui_story_5046_50461102_144_dialog_content = "Escoltaré a Zenas de vuelta a Lumopolis inmediatamente y te informaré del resultado del juicio a su debido tiempo.",
  ui_story_5046_50461102_145_dialog_content = "mi colgante",
  ui_story_5046_50461102_146_dialog_content = "Tenga la seguridad de que cuando encuentre el colgante, se lo entregaré personalmente.",
  ui_story_5046_50461201_1_dialog_content = "<color=#e8d9bb>Varios días después...</color>",
  ui_story_5046_50461201_2_dialog_content = "Kristen!",
  ui_story_5046_50461201_3_dialog_content = "Buenos días, PlayerName.",
  ui_story_5046_50461201_4_dialog_content = "Ha sido un largo tiempo, PlayerName.",
  ui_story_5046_50461201_5_dialog_content = "Vaya, Pittman!",
  ui_story_5046_50461201_6_dialog_content = "Por cierto, es Hati ¿aquí? Escuché que vino a visitar el Coloso.",
  ui_story_5046_50461201_7_dialog_content = "Kristen.",
  ui_story_5046_50461201_8_dialog_content = "Aquí tienes. Este es el colgante.",
  ui_story_5046_50461201_9_dialog_content = "El colgante de mamá...",
  ui_story_5046_50461201_10_dialog_content = "Zenas ahora me ha sido entregado para un mayor interrogatorio.",
  ui_story_5046_50461201_11_dialog_content = "Gracias a ti, PlayerName, también encontramos más pistas vitales para <color=#FFB400>ese otro caso</color>.",
  ui_story_5046_50461201_12_dialog_content = "Jaja... Me alegro de haber podido ayudar.",
  ui_story_5046_50461201_13_dialog_content = "¿Quién hubiera pensado que ser secuestrado causaría tanto drama?",
  ui_story_5046_50461201_14_dialog_content = "Ejem...",
  ui_story_5046_50461201_15_dialog_content = "Oh sí. Tengo algunas preguntas que hacer...",
  ui_story_5046_50461201_16_option_content = "¿Quién fue el verdadero culpable de esos casos de incendios provocados en los últimos dos meses?",
  ui_story_5046_50461201_17_dialog_content = "Nuestra investigación ha demostrado que todos los casos de incendios provocados en Umbraton en los últimos dos meses usaron el mismo combustible, incluido el ensayo en el orfanato.",
  ui_story_5046_50461201_18_dialog_content = "Envié a alguien a investigar este combustible y parece que solo hay unas pocas tiendas que lo venden.",
  ui_story_5046_50461201_19_dialog_content = "El dueño de la tienda identificó que Zenas había comprado grandes cantidades de este combustible hace dos meses.",
  ui_story_5046_50461201_20_dialog_content = "Zenas también admitió que inició todos estos incendios con la intención de silenciar a las víctimas.",
  ui_story_5046_50461201_21_dialog_content = "Pero, ¿por qué mató a esas personas?",
  ui_story_5046_50461201_22_dialog_content = "esta relacionado con <color=#FFB400>Ese caso</color>.",
  ui_story_5046_50461201_23_dialog_content = "En ese momento, cinco empleados, incluido Hamell, utilizaron el orfanato como tapadera para enviar a los niños a experimentar.",
  ui_story_5046_50461201_24_dialog_content = "A excepción de Zenas y Hamell, los otros tres huérfanos que sobrevivieron al incendio en el orfanato no estaban muy bien.",
  ui_story_5046_50461201_25_dialog_content = "Así que los tres usaron su pasado compartido para chantajear a Zenas, y Zenas se vio obligado a pagarles por su silencio.",
  ui_story_5046_50461201_26_dialog_content = "Pero cada vez exigían más...",
  ui_story_5046_50461201_27_dialog_content = "Y luego Zenas los silenció permanentemente.",
  ui_story_5046_50461201_28_dialog_content = "Correcto.",
  ui_story_5046_50461201_29_dialog_content = "¿Quién mató al Sr. Hamell?",
  ui_story_5046_50461201_30_dialog_content = "Zenas admitió haber iniciado los incendios y matado a los tres ex empleados del orfanato.",
  ui_story_5046_50461201_31_dialog_content = "Había cinco personas trabajando en el orfanato involucradas en el caso, incluido Zenas.",
  ui_story_5046_50461201_32_dialog_content = "Entonces, ¿Zenas mató al Sr. Hamell?",
  ui_story_5046_50461201_33_dialog_content = "Es muy sospechoso, pero actualmente no hay evidencia, y él no lo ha admitido.",
  ui_story_5046_50461201_34_dialog_content = "¿Es realmente responsable de tantos asesinatos...?",
  ui_story_5046_50461201_35_dialog_content = "(Kristen no parece que se lo esté tomando bien...)",
  ui_story_5046_50461201_36_dialog_content = "Kristen, ¿estás bien?",
  ui_story_5046_50461201_37_dialog_content = "¿De verdad me ves tan débil, PlayerName?",
  ui_story_5046_50461201_38_dialog_content = "¡N-No, eso no es lo que quise decir! Yo solo...",
  ui_story_5046_50461201_39_dialog_content = "Estoy bien.",
  ui_story_5046_50461201_40_dialog_content = "Recuerdo todo lo que me dijiste ese día, PlayerName.",
  ui_story_5046_50461201_41_dialog_content = "PlayerName me dijo que sería un excelente juez en el futuro.",
  ui_story_5046_50461201_42_dialog_content = "Con tanta gente a mi alrededor, animándome y apoyándome todo el tiempo, no hay forma de que pueda sentirme triste por estar solo.",
  ui_story_5046_50461201_43_dialog_content = "Aunque todavía tengo un largo camino por recorrer antes de alcanzar mi meta, haré todo lo posible para seguir avanzando.",
  ui_story_5046_50461201_44_dialog_content = "¡Porque realmente soy genial! ¿No soy yo? PlayerName?",
  ui_story_5046_50461201_45_dialog_content = "Estamos hablando acerca de Kristen aquí, ¿verdad? ¡Por supuesto que lo eres!",
  ui_story_5046_50461201_46_dialog_content = "Estoy de acuerdo.",
  ui_story_5046_50461201_47_dialog_content = "Secundo que.",
  ui_story_5046_50461201_48_dialog_content = "¡Oh! se me olvidó el sr. Pittman todavía estaba aquí...",
  ui_story_5046_50461201_49_dialog_content = "Ejem... he dado Hati su colgante, así que a menos que tengas algo más que discutir conmigo, permíteme despedirme.",
  ui_story_5046_50461201_50_dialog_content = "Adiós.",
  ui_story_5046_50461201_51_dialog_content = "...",
  ui_story_5046_50461201_52_dialog_content = "Sintiéndose nervioso, Hati?",
  ui_story_5046_50461201_53_dialog_content = "Sí.",
  ui_story_5046_50461201_54_dialog_content = "Estos dos colgantes son un par. Mi mamá me dio la mitad en ese entonces.",
  ui_story_5046_50461201_55_dialog_content = "Mamá dijo que mientras ponga estas dos mitades juntas, nuestra familia siempre estará unida...",
  ui_story_5046_50461201_56_dialog_content = "Pero mamá y yo hemos estado separados por tanto tiempo... boo-hoo...",
  ui_story_5046_50461201_57_dialog_content = "Mamá... *sollozo*",
  ui_story_5046_50461201_58_dialog_content = "Ahí, ahí, no llores...",
  ui_story_5046_50461201_59_dialog_content = "(Esta bien Hati, no llores.)",
  ui_story_5046_50461201_60_dialog_content = "(Que mamá te cante para dormir...)",
  ui_story_5046_50461201_61_dialog_content = "(Lalala ♪ Lalala ♪)",
  ui_story_5046_50461201_62_dialog_content = "(Hati, mirándote dormir tan profundamente, desearía que este momento pudiera durar toda la eternidad.)",
  ui_story_5046_50461201_63_dialog_content = "(Pero también quiero verte crecer. Apuesto a que terminas pareciéndote cada vez más a Fenrir).",
  ui_story_5046_50461201_64_dialog_content = "(Eras solo una pequeña bola esponjosa cuando naciste, pero ahora casi me llegas a la rodilla).",
  ui_story_5046_50461201_65_dialog_content = "(Puede que seas mayor ahora, pero todavía te gusta que te sostenga en mis brazos y te acueste, y cuando te despiertes, todavía me pides que te lleve a la mesa para la cena...)",
  ui_story_5046_50461201_66_dialog_content = "(¡Apenas puedo levantarte ahora, y mucho menos caminar contigo!)",
  ui_story_5046_50461201_67_dialog_content = "(Cuando sea viejo y ya no pueda caminar, me llevarás a la cama y me pondrás en mi taburete...)",
  ui_story_5046_50461201_68_dialog_content = "(Hati... Hay tanto que quiero decirte...)",
  ui_story_5046_50461201_69_dialog_content = "(Espero poder verte y crecer contigo, siempre...)",
  ui_story_5046_50461201_70_dialog_content = "(...)",
  ui_story_5046_50461201_71_dialog_content = "(...)",
  ui_story_5046_50461201_72_dialog_content = "(...)",
  ui_story_5046_50461201_73_dialog_content = "...",
  ui_story_5046_50461201_74_dialog_content = "Ya no te tengo miedo, ni le tendré miedo a... este poder.",
  ui_story_5046_50461201_75_dialog_content = "Puedo aceptarme completamente ahora.",
  ui_story_5046_50461201_76_dialog_content = "Ya sea el Hati que solía temer su poder y odiarse a sí misma.",
  ui_story_5046_50461201_77_dialog_content = "O el Hati quien usa sus llamas para proteger a las personas importantes para ella.",
  ui_story_5046_50461201_78_dialog_content = "No importa cual Hati lo es, son todos yo.",
  ui_story_5046_50461201_79_dialog_content = "(¿Estoy... listo para aceptarme a mí mismo...?)",
  ui_story_5046_50461201_80_dialog_content = "Estoy listo.",
  ui_story_5046_50461202_1_dialog_content = "¿Gané?",
  ui_story_5046_50461202_2_dialog_content = "Estás...?",
  ui_story_5046_50461202_3_dialog_content = "(Puedes aceptarte a ti mismo por completo ahora.)",
  ui_story_5046_50461202_4_dialog_content = "(Has llegado a una reconciliación contigo mismo.)",
  ui_story_5046_50461202_5_dialog_content = "(Estoy muy feliz de ver que puedes usar tu poder tan bien).",
  ui_story_5046_50461202_6_dialog_content = "(Debería irme ahora.)",
  ui_story_5046_50461202_7_dialog_content = "Puedo sentir el poder de las llamas...",
  ui_story_5046_50461202_8_dialog_content = "Este poder está constantemente inundando mi cuerpo...",
  ui_story_5046_50461202_9_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5046_50461202_10_dialog_content = "Una llama... Una llama creada por mis pensamientos...",
  ui_story_5046_50461202_11_dialog_content = "Es cálido.",
  ui_story_5046_50461202_12_dialog_content = "¿PlayerName?",
  ui_story_5046_50461202_13_dialog_content = "¿Estás despierto? Estaba tarareando una canción cuando te quedaste dormido.",
  ui_story_5046_50461202_14_dialog_content = "Parecías tan tranquilo que no quería despertarte.",
  ui_story_5046_50461202_15_dialog_content = "Soñaba con cuando era niño. Accidentalmente quemé algo con mis llamas y mi mamá me regañó.",
  ui_story_5046_50461202_16_dialog_content = "Me abrazó y me cantó una canción de cuna mientras me mecía para dormir.",
  ui_story_5046_50461202_17_dialog_content = "Después de quedarme dormido, vi...",
  ui_story_5046_50461202_18_dialog_content = "Mi demonio interior.",
  ui_story_5046_50461202_19_dialog_content = "Le dije que ya no le tenía miedo.",
  ui_story_5046_50461202_20_dialog_content = "¿Y entonces?",
  ui_story_5046_50461202_21_dialog_content = "Yo... lo derroté.",
  ui_story_5046_50461202_22_dialog_content = "Ya no le tengo miedo a las llamas. Puedo sentir su calor rodeándome.",
  ui_story_5046_50461202_23_dialog_content = "Es como ser sostenido por mi mamá y mi papá.",
  ui_story_5046_50461202_24_dialog_content = "Debe haber sido un lindo sueño.",
  ui_story_5046_50461202_25_dialog_content = "Me atrevo a enfrentar cualquier cosa. Lo obtuve de mi mamá y mi papá.",
  ui_story_5046_50461202_26_dialog_content = "y de ti, PlayerName.",
  ui_story_5046_50461202_27_dialog_content = "Gracias por estar ahí para mi.",
  ui_story_5046_50461202_28_dialog_content = "No necesitas agradecerme. Somos amigos, después de todo.",
  ui_story_5046_50461202_29_dialog_content = "Quiero juntar las dos mitades del colgante ahora. PlayerName, ¿Me acompañaras?",
  ui_story_5046_50461202_30_dialog_content = "¡Seguro! ¡Hagamos esto juntos!",
  ui_story_5046_50461202_31_dialog_content = "<color=#e8d9bb>Hacer clic-</color>",
  ui_story_5046_50461202_32_dialog_content = "Algo parece haber saltado en la parte inferior después de juntar las dos mitades...",
  ui_story_5046_50461202_33_dialog_content = "<color=#e8d9bb>*desdoblamiento de papel*</color>",
  ui_story_5046_50461202_34_dialog_content = "Es... Es un...",
  ui_story_5046_50461202_35_dialog_content = "Tantas fotos...",
  ui_story_5046_50461202_36_dialog_content = "Esta es... una foto de mi familia que dibujé cuando era pequeña.",
  ui_story_5046_50461202_37_dialog_content = "Esto es lo último que esperaba encontrar en el colgante.",
  ui_story_5046_50461202_38_dialog_content = "¡Algunas de tus fotos de la infancia también están aquí!",
  ui_story_5046_50461202_39_dialog_content = "Hay dos fotos más aquí...",
  ui_story_5046_50461202_40_dialog_content = "Esta debe ser tu madre. Entonces, esto debe ser...",
  ui_story_5046_50461202_41_dialog_content = "Padre...",
  ui_story_5046_50461202_42_dialog_content = "¿Eh? ¿Es ese tu padre?",
  ui_story_5046_50461202_43_dialog_content = "Parece que están en un laboratorio...",
  ui_story_5046_50461202_44_dialog_content = "Yo...",
  ui_story_5046_50461202_45_dialog_content = "Nunca conocí a mi papá.",
  ui_story_5046_50461202_46_dialog_content = "Pero mirando esta foto, creo que debe ser él...",
  ui_story_5046_50461202_47_dialog_content = "\"Mientras pongas estas dos mitades juntas, nuestra familia siempre estará unida...\"",
  ui_story_5046_50461202_48_dialog_content = "Ahora nuestra familia estará junta para siempre.",
  ui_story_5046_50461202_49_dialog_content = "<color=#e8d9bb>En algún lugar de Umbraton</color>",
  ui_story_5046_50461202_50_dialog_content = "Después de entregarle la carta a Zenas, lo seguí.",
  ui_story_5046_50461202_51_dialog_content = "Ustedes se quedan y peinan cada centímetro del lugar.",
  ui_story_5046_50461202_52_dialog_content = "¡Sí señor!",
  ui_story_5046_50461202_53_dialog_content = "...",
  ui_story_5046_50461202_54_dialog_content = "(¿Por qué va por este camino...? ¿Se dirige al orfanato?)",
  ui_story_5046_50461202_55_dialog_content = "Ha pasado mucho tiempo, viejo amigo.",
  ui_story_5046_50461202_56_dialog_content = "Eres tú.",
  ui_story_5046_50461202_57_dialog_content = "(¿Hamell? ¿Podría ser eso que tiene en la mano lo que quiere el Señor de las Sombras?)",
  ui_story_5046_50461202_58_dialog_content = "¿No estás feliz de ver a tu viejo amigo?",
  ui_story_5046_50461202_59_dialog_content = "Solo me temo que no estás aquí porque quisieras verme, sino porque quieres algo de mí.",
  ui_story_5046_50461202_60_dialog_content = "No seas tan cínico. Esta vez vengo a traerles una noticia.",
  ui_story_5046_50461202_61_dialog_content = "Entonces, ella pidió reunirse. ¿Qué tiene eso que ver conmigo?",
  ui_story_5046_50461202_62_dialog_content = "Andre y los otros dos están muertos. Tarde o temprano, será nuestro turno.",
  ui_story_5046_50461202_63_dialog_content = "En lugar de esperar a que ella venga a nuestra puerta, salgamos a saludarla.",
  ui_story_5046_50461202_64_dialog_content = "(Parece que Hamell sigue mirando hacia allí inconscientemente).",
  ui_story_5046_50461202_65_dialog_content = "Sé que quieres preguntar por qué no hice nada.",
  ui_story_5046_50461202_66_dialog_content = "En esta carta suya, me llama por mi nombre. Si alguien descubriera la conexión entre nosotros, podría hacer las cosas mucho más complicadas.",
  ui_story_5046_50461202_67_dialog_content = "Si eso sucede, ya no podré protegerte. Quién puede decir... incluso podrías ser descubierto también.",
  ui_story_5046_50461202_68_dialog_content = "me estas amenazando...",
  ui_story_5046_50461202_69_dialog_content = "Todos tenemos que cuidarnos a nosotros mismos. Esta es la dirección.",
  ui_story_5046_50461202_70_dialog_content = "Bien, puedo ayudarte con esto, pero necesitas encontrar algunas personas que me ayuden.",
  ui_story_5046_50461202_71_dialog_content = "Después de que Zenas se fue, rebusqué mientras Hamell dormía y lo encontré.",
  ui_story_5046_50461202_72_dialog_content = "Un registro de sus fechas de transacción, precios e información del comprador.",
  ui_story_5046_50461202_73_dialog_content = "Impresionante.",
  ui_story_5046_50461202_74_dialog_content = "Hace muchos años, Umbraton era una tierra caótica y sin ley. La gente de Lumopolis lo trató como un vertedero donde enterraban sus pecados.",
  ui_story_5046_50461202_75_dialog_content = "Ahora que soy el guardián de Umbraton, no dejaré que vuelva a ser como antes.",
  ui_story_5046_50461202_76_dialog_content = "Las sombras conocen todos los secretos.",
  ui_story_5046_50461202_77_dialog_content = "Entendido, Señor de las Sombras.",
  ui_story_5046_50461202_78_dialog_content = "Lo has hecho bien estos últimos días.",
  ui_story_5046_50461202_79_dialog_content = "<color=#e8d9bb>Prisión de Lumópolis</color>",
  ui_story_5046_50461202_80_dialog_content = "...",
  ui_story_5046_50461202_81_dialog_content = "Aquí viene mi jovencita.",
  ui_story_5046_50461202_82_dialog_content = "Es tan frío y sombrío aquí. Este no es lugar para una mujercita como tú.",
  ui_story_5046_50461202_83_dialog_content = "Vine a despedirme de ti y de mi pasado.",
  ui_story_5046_50461202_84_dialog_content = "Siempre te seguí a ciegas, avanzando en la dirección que tú querías, tanto en mis pensamientos como en mis acciones.",
  ui_story_5046_50461202_85_dialog_content = "Yo era tu marioneta.",
  ui_story_5046_50461202_86_dialog_content = "Jovencita, nunca te obligué a hacer nada que no quisieras. ¿Qué tienes en mente?",
  ui_story_5046_50461202_87_dialog_content = "Me enferma saber que estabas detrás de todo esto, ¡pero persistes en afectar esta actitud indiferente!",
  ui_story_5046_50461202_88_dialog_content = "¡Eres una completa y absoluta escoria!",
  ui_story_5046_50461202_89_dialog_content = "...",
  ui_story_5046_50461202_90_dialog_content = "Lo siento, me olvidé de mí.",
  ui_story_5046_50461202_91_dialog_content = "el colgante",
  ui_story_5046_50461202_92_dialog_content = "¿Qué hay en ese colgante?",
  ui_story_5046_50461202_93_dialog_content = "¿Eso es todo lo que querías preguntar?",
  ui_story_5046_50461202_94_dialog_content = "...",
  ui_story_5046_50461202_95_dialog_content = "Pagué mucho por este colgante.",
  ui_story_5046_50461202_96_dialog_content = "Quiero saber si hay algo escondido dentro... Lo que he estado buscando.",
  ui_story_5046_50461202_97_dialog_content = "Solo había algunas fotos de la familia de Hati.",
  ui_story_5046_50461202_98_dialog_content = "¿Solo algunas fotos?",
  ui_story_5046_50461202_99_dialog_content = "Solo algunas fotos.",
  ui_story_5046_50461202_100_dialog_content = "¡Jajajajajaja!",
  ui_story_5046_50461202_101_dialog_content = "Bueno, yo nunca...",
  ui_story_5046_50461202_102_dialog_content = "No esperaba que las cosas salieran así...",
  ui_story_5046_50461202_103_dialog_content = "Si no tienes nada más que decir...",
  ui_story_5046_50461202_104_dialog_content = "Me despediré.",
  ui_story_5046_50461202_105_dialog_content = "...",
  ui_story_5046_50461202_106_dialog_content = "Esta es la última vez que nos veremos.",
  ui_story_5046_50461202_107_dialog_content = "Adiós señor.",
  ui_story_5046_50461202_108_dialog_content = "(Adiós... a mi pasado.)",
  ui_story_5046_50461202_109_dialog_content = "<color=#e8d9bb>Ceremonia del día de finalización del orfanato de Umbraton</color>",
  ui_story_5046_50461202_110_dialog_content = "La finalización de este orfanato simboliza los arduos esfuerzos de innumerables ciudadanos solidarios de Umbraton. ¡Permítanme aprovechar esta oportunidad para expresar mi gratitud a estas personas una vez más!",
  ui_story_5046_50461202_111_dialog_content = "¡Por la presente declaro que el orfanato de Umbraton se completó oficialmente!",
  ui_story_5046_50461202_112_dialog_content = "¡Felicidades!",
  ui_story_5046_50461202_113_dialog_content = "¡Qué triunfo! ¡Es magnífico!",
  ui_story_5046_50461202_114_dialog_content = "Espero que este orfanato se convierta en la fuente de muchos recuerdos felices y que los errores del pasado nunca se repitan.",
  ui_story_5046_50461202_115_dialog_content = "Este orfanato ahora está bajo la supervisión del Señor de las Sombras de Umbraton, así que no tienes que preocuparte por eso. PlayerName.",
  ui_story_5046_50461202_116_dialog_content = "¿¡Grimme!?",
  ui_story_5046_50461202_117_dialog_content = "El día que arrestaron a Zenas, Hati y fui al Firefly Bar a buscarte, pero no estabas...",
  ui_story_5046_50461202_118_dialog_content = "Tenía negocios de los que ocuparme.",
  ui_story_5046_50461202_119_dialog_content = "Por cierto, ¿dónde está Hati?",
  ui_story_5046_50461202_120_dialog_content = "ella es...",
  ui_story_5046_50461202_121_dialog_content = "Ahora demos una calurosa bienvenida al héroe extintor de incendios de nuestro orfanato—Hati!",
  ui_story_5046_50461202_122_dialog_content = "...",
  ui_story_5046_50461202_123_dialog_content = "Las heroicas habilidades de extinción de incendios de Hati han evitado el desastre en Umbraton durante los últimos dos meses, apagando incendios grandes y pequeños.",
  ui_story_5046_50461202_124_dialog_content = "Hace unos días, una niña pequeña quedó atrapada en un incendio en el ensayo de esta ceremonia...",
  ui_story_5046_50461202_125_dialog_content = "Hati se apresuró sin pensarlo dos veces y la rescató...",
  ui_story_5046_50461202_126_dialog_content = "Entonces, ella no es una pirómana...",
  ui_story_5046_50461202_127_dialog_content = "¿Ella realmente estaba allí salvando a alguien?",
  ui_story_5046_50461202_128_dialog_content = "Ella es tan valiente, como un gran héroe...",
  ui_story_5046_50461202_129_dialog_content = "Extrañar Bethel es tan pensativo. Ahora nadie en Umbraton tratará Hati como un criminal",
  ui_story_5046_50461202_130_dialog_content = "Ella es inteligente. No podría manejar todo tan bien incluso si tuviera tres cerebros.",
  ui_story_5046_50461202_131_dialog_content = "Jeje... Tienes tus propias fortalezas, PlayerName. No lo olvides, nadie es perfecto.",
  ui_story_5046_50461202_132_dialog_content = "Esto es tan molesto.",
  ui_story_5046_50461202_133_dialog_content = "Oye... Saliste corriendo del escenario tan rápido.",
  ui_story_5046_50461202_134_dialog_content = "Mi pelo estaba de pie mientras estoy allí.",
  ui_story_5046_50461202_135_dialog_content = "Te acostumbrarás. Después de todo, no has estado en el mundo exterior tanto tiempo, y todavía hay muchas cosas que aprender aquí.",
  ui_story_5046_50461202_136_dialog_content = "Mmm...",
  ui_story_5046_50461202_137_dialog_content = "Hati, ¿Cuáles son sus planes para el futuro?",
  ui_story_5046_50461202_138_dialog_content = "Yo...",
  ui_story_5046_50461202_139_dialog_content = "No lo sé.",
  ui_story_5046_50461202_140_dialog_content = "Encontrar mis recuerdos perdidos de mi madre solía ser mi objetivo.",
  ui_story_5046_50461202_141_dialog_content = "Pero ahora ese objetivo se ha logrado...",
  ui_story_5046_50461202_142_dialog_content = "No sé qué más debo hacer.",
  ui_story_5046_50461202_143_dialog_content = "Eso no importa. ¡La vida es esencialmente una meta tras otra!",
  ui_story_5046_50461202_144_dialog_content = "Siempre debes tomarte un descanso antes de encontrar tu próximo objetivo.",
  ui_story_5046_50461202_145_dialog_content = "Después de todo, ya lo hiciste muy bien en lograr tu última meta.",
  ui_story_5046_50461202_146_dialog_content = "¿Mi próxima meta?",
  ui_story_5046_50461202_147_dialog_content = "No sé cuál será mi próximo objetivo.",
  ui_story_5046_50461202_148_dialog_content = "lo encontrarás",
  ui_story_5046_50461202_149_dialog_content = "¡Tu vida no ha hecho más que empezar!",
  ui_story_5046_50461202_150_dialog_content = "Como dije antes, ¡muchas cosas nuevas y emocionantes te están esperando para descubrir en este mundo!",
  ui_story_5046_50461202_151_dialog_content = "Por ahora, ¡disfruta de tu tiempo libre mientras puedas!",
  ui_story_5046_50461202_152_dialog_content = "Sí.",
  ui_story_5046_50461202_153_dialog_content = "Gracias, PlayerName.",
  ui_story_5046_50461202_154_dialog_content = "Estoy más preocupado por si podrías tener otro dolor de cabeza pronto...",
  ui_story_5046_50461202_155_dialog_content = "Me pregunto qué te dirá a continuación ese perro grande que se parece un poco a ti...",
  ui_story_5046_50461202_156_dialog_content = "no me importa",
  ui_story_5046_50461202_157_dialog_content = "Ya hemos llegado a un acuerdo.",
  ui_story_5046_50461202_158_dialog_content = "Ahora, somos uno.",
  ui_story_5046_50461202_159_dialog_content = "¡Whoa!",
  ui_story_5046_50461202_160_dialog_content = "¡Te pareces a ese perro grande!",
  ui_story_5046_50461202_161_dialog_content = "Sí.",
  ui_story_5046_50461202_162_dialog_content = "No tengas miedo.",
  ui_story_5046_50461202_163_dialog_content = "Ahora puedo aprovechar completamente su poder...",
  ui_story_5046_50461202_164_dialog_content = "Es el poder del fuego.",
  ui_story_5046_50461202_165_dialog_content = "perrito grande!",
  ui_story_5046_50461202_166_dialog_content = "Estás...",
  ui_story_5046_50461202_167_dialog_content = "Eres... la niña de ese día.",
  ui_story_5046_50461202_168_dialog_content = "¡Hice un anillo de flores para el gran perrito que nos salvó!",
  ui_story_5046_50461202_169_dialog_content = "¿Sabes dónde está el perrito grande?",
  ui_story_5046_50461202_170_dialog_content = "Ella...",
  ui_story_5046_50461202_171_dialog_content = "Ella está aquí.",
  ui_story_5046_50461202_172_dialog_content = "¡Wow!",
  ui_story_5046_50461202_173_dialog_content = "¿De verdad me veo tan aterrador?",
  ui_story_5046_50461202_174_dialog_content = "¡Qué perrito más grande!",
  ui_story_5046_50461202_175_dialog_content = "¡Ella es hermosa!",
  ui_story_5046_50461202_176_dialog_content = "...",
  ui_story_5046_50461202_177_dialog_content = "¿Eres el perrito grande que me salvó el otro día?",
  ui_story_5046_50461202_178_dialog_content = "Sí.",
  ui_story_5046_50461202_179_dialog_content = "¡Oh! ¡Sé!",
  ui_story_5046_50461202_180_dialog_content = "¡El gran perrito ha estado trabajando tan duro para salvar a la gente de toda la ciudad, haciéndose más y más fuerte y más y más increíble!",
  ui_story_5046_50461202_181_dialog_content = "¡Es por eso que el perrito se convirtió en un perrito súper enorme!",
  ui_story_5046_50461202_182_dialog_content = "Ajajajaja...",
  ui_story_5046_50461202_183_dialog_content = "¡Perrito! Gran perrito héroe!",
  ui_story_5046_50461202_184_dialog_content = "Ja... ja...",
  ui_story_5046_50461202_185_dialog_content = "Waah... no puedo alcanzar...",
  ui_story_5046_50461202_186_dialog_content = "¿Estás tratando de ponerle esta guirnalda?",
  ui_story_5046_50461202_187_dialog_content = "¡Sí!",
  ui_story_5046_50461202_188_dialog_content = "Déjame agacharme un poco.",
  ui_story_5046_50461202_189_dialog_content = "¡Perfecto!",
  ui_story_5046_50461202_190_dialog_content = "¡Gracias por salvarme!",
  ui_story_5046_50461202_191_dialog_content = "Salí en secreto a recoger estas flores sin decírselo al cuidador...",
  ui_story_5046_50461202_192_dialog_content = "¡No deberías escabullirte así!",
  ui_story_5046_50461202_193_dialog_content = "Pero... Pero pensé que el perrito grande me salvó...",
  ui_story_5046_50461202_194_dialog_content = "¡Así que debería darle un regalo al perrito grande!",
  ui_story_5046_50461202_195_dialog_content = "Mientras estés bien.",
  ui_story_5046_50461202_196_dialog_content = "No necesitas darme nada.",
  ui_story_5046_50461202_197_dialog_content = "Nuh-uh!",
  ui_story_5046_50461202_198_dialog_content = "¡En el orfanato, los niños que ayudan a las personas obtienen recompensas del cuidador!",
  ui_story_5046_50461202_199_dialog_content = "El gran perrito me salvó, ¡así que el gran perrito merece una recompensa!",
  ui_story_5046_50461202_200_dialog_content = "Pero no tengo nada...",
  ui_story_5046_50461202_201_dialog_content = "...",
  ui_story_5046_50461202_202_dialog_content = "Solo decir \"gracias\" es suficiente.",
  ui_story_5046_50461202_203_dialog_content = "Entonces, estaba pensando, \"¿cuál sería un buen regalo para un perrito grande...?\"",
  ui_story_5046_50461202_204_dialog_content = "¡Y justo cuando estaba pensando que una pequeña flor flotaba desde afuera de la ventana!",
  ui_story_5046_50461202_205_dialog_content = "¡Era como el gran perrito cayendo del cielo!",
  ui_story_5046_50461202_206_dialog_content = "Así que hice este anillo de flores, con la esperanza de que el perrito grande estuviera feliz de verlo...",
  ui_story_5046_50461202_207_dialog_content = "¿Te gusta el anillo de flores que hice?",
  ui_story_5046_50461202_208_dialog_content = "Seguro...",
  ui_story_5046_50461202_209_dialog_content = "Me gusta.",
  ui_story_5046_50461202_210_dialog_content = "Gracias.",
  ui_story_5046_50461202_211_dialog_content = "Gracias a todos."
}
return config
